["__consistent_tr_266846a333b05d8f"] = "Gerçek şu: Fıçı palyaçoları, rodeo palyaçolarının en üst sınıfıdır. Önemli olan tek işi yaparlar. Seyirciyi eğlendirmek. Vahşi bir boğanın gözlerinin önünde birini deşebileceğini insanların fark etmesini önlemek. İşte o dikkat dağıtma, bütün gösterinin anahtarı.$NL;Soygundayken fıçı palyaçosu sensin. Kalabalık denetiminin ustası. \"Bana bakın millet! Vezne arkasındaki silah seslerini boş verin! Kaçmayı düşünmeyin; mermilerimiz daha hızlı koşar! Gözler bende, hanımlar ve mikroplar! Eller başta, gözler palyaçoda!\"",
