["__consistent_tr_38982b895d150cd6"] = "Uzun ve amansız bir insan avından sonra kanun sonunda Billy the Kid’i yakaladı. Hücreye kilitlediler, kelepçelediler, asılmaya mahkûm ettiler. Vakti dolmuş gibiydi ama insan ölümün eşiğinde olduğunu bilince kaçmak için hemen her şeyi dener. Sıradan bir mahkûm, muhafızın silahını çalıp hapishaneden ateş ederek çıkmayı hayal bile edemezdi. Ne yazık ki New Mexico’nun Lincoln kasabasının şerif yardımcıları unuttu... Billy the Kid sıradan bir mahkûm değildi.",
["__consistent_tr_390d81ab2d3706c3"] = " ",
