["__consistent_tr_3cfe1b4351451653"] = "Amaroq 900 Sniper Rifle",
["__consistent_tr_3dd4735c8c4ff3bc"] = "Tüm özel düşmanlara ek hasar verir. Her vuruşun zehirleme, elektrikle sersemletme, hatta anında öldürme şansı vardır.",
["__consistent_tr_3f4300abc6174809"] = "Moonlight Stock",
["__consistent_tr_3fe40f24a8336a89"] = " ",
["__consistent_tr_3fecc7a63829d7f3"] = " ",
["__consistent_tr_3ff538b500c77ca5"] = "Pazarda satılamaz, takas edilemez veya açılamaz.",
["__consistent_tr_40432fbf55459c16"] = " ",
["__consistent_tr_409595d72ac85002"] = " ",
["__consistent_tr_40e11d257e273278"] = "Her zanaatın dâhileri vardır. Müzikte Mozart, sanatta Picasso, kanun kaçaklarında Billy the Kid. Billy 21 yaşına gelene kadar yirmiden fazla adam öldürmüş, sayısız kez kanundan kaçmıştı. Batı’nın en hızlı silahıydı, akıcı İspanyolca konuşurdu ve onunla tanışan herkes onu gerçekten severdi. Uzun yaşamadı ama her saniyesinin hakkını verdi.",
["__consistent_tr_40f53acfc3f3dc4b"] = "Açmak için Under the Hammer DLC’sini satın al!",
["__consistent_tr_42059757fc12580d"] = "Genellikle acil durumda yardım veya ikmal çağrısı yapmak için kullanılır.",
["__consistent_tr_4211f89e925de762"] = " ",
