["__consistent_tr_48fe067dedce76f2"] = "Esteban Santiago iyi bir adam değildi. Pek sevimli de değildi. Hatta azıcık bile düzgün değildi. Ama silahları severdi. Teksas’ı severdi. Askerî sınıf silahları Teksas’a kaçırmayı severdi. Bir de harika döş eti pişirirdi.$NL;Hem... En azından kardeşi kadar zırdeli değildi. Öyle değil mi?",
["__consistent_tr_49e840915ec961a4"] = "Large Magazine",
["__consistent_tr_4a0d1c0ed26b9c78"] = "Hey! Teksas kırsalındaki bir çiftlikte silah kaçakçılarının üssünü bastığımız zamanı hatırlıyor musun? Sonra Fort Worth’te treni resmen raylardan kaldırarak soymuştuk. Ardından iki yozlaşmış petrol baronunun güç kavgasına çekildik; Dallas’ta bir şirketin genel merkezini yağmalayıp açık denizdeki bir petrol platformunu paramparça ettik. Hahaaa dostum. Güzel günlerdi. Çooook güzel günler.",
