["__consistent_tr_63fcb12d03aea747"] = " ",
["__consistent_tr_64d8bc5bd4a14753"] = "Küçük kardeşi Esteban silah satmayı severken Gabriel Santiago onları ateşlemeyi tercih ediyordu. Deniz Piyadeleri’nde görev yaptı, ardından yıllarca Bellmead International adlı özel askerî şirkette çalıştı. Acımasız verimliliği petrol baronesi Alice Rainey’nin dikkatini çekti. Gabriel’in savaş becerileriyle suç bağlantılarından yararlanmak isteyen Rainey, ona SERA’nın Güvenlik Şefliğini teklif etti. Servet ve mevki arayan Gabriel kabul etti.$NL;Rainey, Teksas yeraltı dünyasındaki köklerini güçlendirmek istediğini söyleyince Gabriel onu Esteban’la tanıştırdı. Esteban artık Midland Ranch’ten silah kaçakçılığı yürütüyordu. Bu buluşma Santiago Brothers ile Payday Gang’i beklenmedik bir çatışma rotasına soktu; Gabriel’in sonunu da bu getirecekti. Şiddet dolu bir yaşam, şiddet dolu bir ölüm doğurur.",
["__consistent_tr_652a45841626a217"] = "Lupa Grip",
["__consistent_tr_65469cb9fe5d3c6e"] = "Her suçlunun hayatında bir boğa vardır. Belki bölgene çökmeye çalışan o boktan çete lideridir. Parasını dünden isteyen tefecidir. Seni tekrar hapse tıkmaya niyetli şartlı tahliye memurudur. Bir süredir boğanla dans ediyorsun. Her seferinde yeni hücumuna hazırlanıp zamanında kaçabilmeyi umuyorsun. Ezilip parçalanmamak için dua ediyorsun. $NL;Artık yeter. Dans bitti. Bir dahaki karşılaşmanızda o boğayı boynuzlarından yakalayıp boynuzlarını sökecek, kıçına sokacaksın. Bu senin ilk rodeon değil ama onun sonuncusu olacak. Yihaa, dallamalar.",
