["__consistent_tr_b9a097229c728beb"] = "Casus Kamerasını kullanmak için $BTN_USE_ITEM; düğmesini basılı tut. Yerleştirdikten sonra $BTN_INTERACT; düğmesini basılı tutarak geri alabilirsin. Sen ve ekibin, uzaktan kameraya bakarken $BTN_INTERACT; düğmesini basılı tutarak Casus Kameralarını kullanabilirsiniz.$NL;$NL;Casus Kamerası muhafızları ve düşmanları tekrar tekrar işaretler. Kamerayı kullanırken hedefleri gecikmesiz işaretlersin.$NL;$NL;Casus Kamerası, casusların istihbarat toplamak ve casusluk alanında üstünlük sağlamak için taşıdığı taşınabilir bir kayıt cihazıdır.",
["__consistent_tr_b9f8353844f6bbd0"] = " ",
