["__consistent_tr_badc2c5429c82a19"] = "Açmak için Starbreeze Nebula hesabı oluştur veya Steam’de Speedrunners oyununa sahip ol!",
["__consistent_tr_bbd63a9cb8e4e0b5"] = "Vücut zırhını, düşmanları, kalkanları ve duvarları deler.",
