["__consistent_tr_bc58103dcd69451f"] = " ",
["__consistent_tr_bc730b400d005aae"] = "Gizliliğin çok zor olduğunu düşünüyorsan şunu hatırla. Bass ve çetesi Amerikan tarihinin en büyük tren soygunlarından birini yaptı; altın sikkelerle servet kazandı ve tek bir kişiyi bile öldürmedi. Sıfır can kaybı, geride kalan sıfır ganimet. Hırsız avantaj destesi olmadan bunu başarabiliyorlarsa sen de alarmı çaldırmadan birkaç çağrı cihazını yanıtlayabilirsin.",
