["__consistent_tr_c7ca48634865f950"] = "Bu oyun gerçekten öldüyse bu yazıyı kimse okumayacak. O zaman hemen her istediğimi söyleyebilirim. Hmm... En iyi patates kızartması incecik olandır. Kusura bakmayın ama elma dilim ve kalın kesim patatesler fazla yoğun. Bildiğin patates isteseydim patates söylerdim. Ben kızartma istiyorum. İnce olsun istiyorum. Çıtır olsun istiyorum. Düşünmek bile acıktırıyor. Tamam. Bunu nasıl bitireceğimden emin değilim. Son?",
