["__consistent_tr_e217a7f4490ff704"] = "İsyancılar. Katiller. Vatanseverler. Hırsızlar. Amerikan tarihinde derin kökleri olan gerilla askerleri bushwhacker’ları herkes farklı tanımlıyordu. Bağımsızlık Savaşı’ndan İç Savaş’a kadar, kendilerine ait olanı korumak için dişleriyle tırnaklarıyla savaştılar. Sevsen de nefret etsen de Vahşi Batı’nın bir devinin doğuşundaki rollerini inkâr edemezsin: Jesse James’e silah kullanmayı onlar öğretti.",
["__consistent_tr_e25b75706f0f42a2"] = "İsabeti artırmak için geciktirilmiş geri tepmeli çoklu atış modu.",
["__consistent_tr_e2b3250f2851ae4a"] = "Choose Second Accent",
["__consistent_tr_e2efd552ac134334"] = "Pek çok yönden sıradan bir hırsızsın. Cep boşaltır, kasadan çalarsın. Hayatı kocaman bir sayı oyunu olarak görürsün. Ama sende şöyle bir şey var: Zekisin. Ceplerin kendiliğinden boşalmasını sağlamayı çözdün. Tek bir yasayı çiğnemeden kasaları kurutmayı öğrendin. O sayı oyununa gelince; açık farkla kazanıyorsun. Şirketler dünyası bir suçlunun oyun alanıdır; emekle kazandığın başarının sırrı bu. Yani hayır, sıradan bir hırsız değilsin. Olağanüstü bir hırsızsın.",
