["__consistent_tr_e9e4c72cd7635658"] = "Sam Bass o Union Pacific trenini soyarken demiryolunun tarihindeki en büyük tren soygununu yaptığını bilmiyordu. Ömür boyu yetecek kadar altın sikke kazanacağını, böylece kâr yerine heyecan için suç işleyebileceğini fark etmemişti. Efsane olmak için tek bir iş yeter; Bass da 1877’de altını buldu.",
