["__consistent_tr_f4c0551074f51315"] = "Eski çağlarda tiyatro maskeleri, seyircinin karakterlerin duygularını daha kolay görmesi için takılırdı.$NL;Günümüzde de aynı amaçla kullanılıyorlar ama artık seyirci rehineler.$NL;$NL;Bu maske seyirciye zarar vermek istemediğini anlatır; ama yalnızca uslu dururlarsa.",
