["__consistent_tr_fda5a1423929e36d"] = "Bu ölü oyunu hayatta tutan güzel soygunculara selam olsun!",
["__consistent_tr_fdd891da5f594220"] = " ",
["__consistent_tr_fe134e44d0563fd9"] = "Açmak için Starbreeze Nebula hesabı oluştur veya Steam’de Hotline Miami 2: Wrong Number oyununa ya da The Jacket Character Pack’e sahip ol!",
["__consistent_tr_fe60a35648d089ce"] = " ",
["__consistent_tr_fe6aead98eb2c73b"] = "Yeniden Dolum Süresi",
["__consistent_tr_fee711b016e68aa4"] = " ",
["__consistent_tr_ff1a14b7efe72ffa"] = "Gece boyunca avlan.",
["__consistent_tr_ff1d8e44f6c17b10"] = " ",
["__consistent_tr_ff2d0be337d8475a"] = " ",
["__consistent_tr_ff3f4db77862a8db"] = "Zenginler ve güçlüler kapalı kapılar ardında ne konuşur? Suçlular kenar mahallelerinin karanlık köşelerinde hangi sırları fısıldar? Görünmez ipler en yüce kralları en aşağılık suçlulara bağlar ve bu bağlantıları yalnızca sen görebilirsin. Gözlerin hep izliyor. Her yerde kulağın var. Bilgi güçse senin gücün sınırsız. Arkana yaslanıp her şeyin gelişmesini mi izleyeceksin, yoksa kendi komplonu mu kuracaksın? Pek çok soru gibi bunun cevabını da ancak sen verebilirsin.",
["american_desc"] = "Uyruk: Amerikalı$NL;Yaş: 31$NL;$NL;Houston, hayatı buna bağlı olsa bile bir işte tutunamazdı. Yaşam tarzı onu dolandırıcılığa ve hırsızlığa sürükledi. Borçları da yıllar süren üçkâğıtçılığının kazandırdığı düşmanları da çoğaldı. Tefecileri uzak tutmak için giderek daha büyük paralar bulması gerekiyordu. İlk büyük suçunu 24 yaşında işledi; o günden beri riskler hep büyüdü.",
["bm_ability_chico_injector"] = "Enjektör",
["bm_ability_chico_injector_desc"] = "Kullanıldığında kullanıcı acı hissetmez ve korkusuzlaşır. Acı duymaması, çatışmanın kalbinde herkesten uzun süre ortalığı kasıp kavurmasını sağlar. Korkusuzluğuysa onu düşmanları için korkutucu ve bariz bir tehdide dönüştürür.",
["bm_ace"] = "Dawn Patrol",
["bm_ace_desc"] = "Çok eskiden, Güneydoğu Asya’daki gizli ve son derece tehlikeli bir paralı asker görevinde Chains bu eski ABD Ordusu miğferini edindi. Önceki sahibinin kim olduğunu kimse bilmiyor.",
["bm_al_pacino"] = "Al Capone",
["bm_al_pacino_desc"] = "Suç hayatını gerçekten özenecek bir şeye dönüştüren asıl mafya babası. Bugün yaşasaydı Payday ekibinin kesin üyesi olurdu. Ama en azından kılığına girip hayalet gördüklerini sanan polisleri korkutabilirsin.",
["bm_armor_chainmail"] = "Zincir Zırh",
["bm_armor_kevlar"] = "Kevlar",
["bm_armor_leather"] = "Deri",
["bm_armor_level_1"] = "İki Parçalı Takım Elbise",
["bm_armor_level_1_desc"] = "Hareket cezası yok, dikkat çekmez.$NL;$NL;Kendine saygısı olan her suçlunun giymesi gereken standart iki parçalı takım elbisedir.$NL;$NL;Ek koruma sağlamaz ama en yüksek Gizlenebilirliğe sahiptir. Fark edilmeden kalabalığa karışmak istediğin soygunlar için en iyi seçimdir.$NL;$NL;Takım elbiseler genellikle düğün, cenaze ve banka soygunu gibi özel günlere saklanır.",
["bm_armor_level_2"] = "Hafif Balistik Yelek",
["bm_armor_level_2_desc"] = "Hafif hareket cezası, düşük görünürlük.$NL;$NL;Hafif Balistik Yelek, giymesi kolay ve gizlenebilir bir kurşungeçirmez yelektir. Özel geliştirilmiş travma astarı, künt darbelerin etkilerine karşı etkili koruma sağlayarak onu iyi bir savunma seçeneği yapar.$NL;$NL;Hafif Balistik Yelekler; devlet büyükleri, önemli kişiler, hava güvenliği görevlileri ve üst düzey yönetici ve diplomat korumaları tarafından kullanılır.",
["bm_armor_level_3"] = "Balistik Yelek",
["bm_armor_level_3_desc"] = "Hafif hareket cezası, düşük görünürlük.$NL;$NL;Balistik Yelek, gövdeye giyilen, standart kullanımda olan yumuşak yapılı kurşuna dayanıklı bir yelektir. Küçük kalibreli tabanca ve pompalı tüfek mermilerine karşı iyi koruma sağlayarak ateş hattındaki herkes için temel bir ekipman olur.$NL;$NL;Balistik Yelekler; polisler, güvenlik görevlileri ve korumalar tarafından kullanılır.",
["bm_armor_level_4"] = "Ağır Balistik Yelek",
["bm_armor_level_4_desc"] = "Az hareket cezası, orta görünürlük.$NL;$NL;Ağır Balistik Yelek, gövdeye giyilen ve sert plakalarla güçlendirilmiş bir yelektir. Balistik yeleği omuz ve yan koruma parçalarıyla birleştiren modern bir vücut zırhı olarak güçlü bir koruma sunar.$NL;$NL;Ağır Balistik Yelekler; askerler, polis taktik birimleri ve rehine kurtarma ekipleri tarafından kullanılır.",
["bm_armor_level_5"] = "Şarapnel Yeleği",
["bm_armor_level_5_desc"] = "Orta hareket cezası, orta görünürlük.$NL;$NL;GenSec Security Industries üretimi Şarapnel Yeleği, klasik tasarımın modern bir yorumudur. Ateşli silah mermilerinin ve patlamalardan saçılan şarapnellerin darbesini emer.$NL;$NL;Ağır Balistik Yeleği omuz ve yan koruma parçalarıyla birleştirir; ayrıca omurgayı da korur.$NL;$NL;Şarapnel Yelekleri; deniz piyadeleri, muharip askerler ve GenSec FTSU görev kuvvetleri tarafından kullanılır.",
["bm_armor_level_6"] = "Birleşik Taktik Yelek",
["bm_armor_level_6_desc"] = "Orta hareket cezası, yüksek görünürlük.$NL;$NL;Birleşik Taktik Yelek, modern savaşın zorlukları nedeniyle geliştirildi. Yüksek performanslı balistik malzemelerden yapılır ve mühimmat keseleri, telsizler ve diğer aksesuarlar gibi ağır yükleri taşımak için tasarlanmıştır. $NL;$NL;Birleşik Taktik Yelekler, dünyanın dört bir yanındaki askerler, özel kuvvetler ve diğer düzenli askerî birimler tarafından kullanılır.",
["bm_armor_level_7"] = "Geliştirilmiş Birleşik Taktik Yelek",
["bm_armor_level_7_desc"] = "Ağır hareket cezası, yüksek görünürlük.$NL;$NL;Geliştirilmiş Birleşik Taktik Yelek, GenSec Security Industries tarafından üretilmiş, çalınmış deneysel bir prototiptir.$NL;$NL;White Mesa teknolojisine dayanır ve hem yumuşak hem de sert zırh çözümlerini kullanır. Metal plakalarla sıkıca örülmüş, birbirine tam oturan kilitli lif katmanları; mermileri saptırmak ve patlamalardan korumak için özel açılarla yerleştirilmiştir. Kısacası tam koruma sağlar.",
