["bm_askn_find_in_crime_spree"] = "Bu zırh ##Suç Serisi## oyun modunda kazanılabilir. Kaplama takas edilemez veya satılamaz.",
["bm_askn_navy_blue"] = "Navy Blue Armor",
["bm_askn_none"] = "Kaplama Yok",
["bm_askn_tam"] = "Immortal Python Armor",
["bm_askn_tam_unlock"] = "Bu zırh ##1000 Başarım Dönüm Noktası## ödülü olarak kazanılır. Kaplama takas edilemez veya satılamaz.",
["bm_bandana"] = "Bloody Bandana",
["bm_bandana_desc"] = "Bu kırmızı alın bandını takan askerin kimliği gizli. Sızan raporlar, gerilla taktiklerinde uzman bir savaş gazisinden ve eski bir U.S. Army Special Forces askerinden söz ediyor. Silah arkadaşları onu sert, gözü kara ve aşırı saldırgan diye tanımlıyordu. İzini bulup katlettiği üst düzey subay sayısına bakılırsa otoriteyle ciddi bir sorunu olabilir...",
["bm_beret"] = "Commando",
["bm_beret_desc"] = "Chains bu bereyi Batı Afrika’daki bir paralı asker operasyonuna hazırlanırken özel yaptırdı. Ama onu takarken neler yaptığını anlatmıyor.",
["bm_bugsy"] = "George \"Bugs\" Moran",
["bm_bugsy_desc"] = "Al Capone’un rakibi. İçki yasağı dönemi birkaç şişe viski bulabilen herkese içkiyi altına çevirirken bu iki adam kapışıyordu. Capone, kötü şöhretli Saint Valentine’s Day Massacre sırasında onu vurdurmaya bile çalıştı. Ama başaramadı.",
["bm_c_jacket1"] = "Jacket 1",
["bm_c_jacket2"] = "Jacket 2",
["bm_c_jacket3"] = "Jacket 3",
["bm_c_jacket4"] = "Jacket 4",
["bm_c_trousers1"] = "Pantolon 1",
["bm_c_trousers2"] = "Pantolon 2",
["bm_c_trousers3"] = "Pantolon 3",
["bm_c_trousers4"] = "Pantolon 4",
["bm_cap_n_beard"] = "A.W.O.L",
["bm_cap_n_beard_desc"] = "Çok gizli raporlarda seçkin bir özel harekât birliğinin bu askerinden söz ediliyor. Önemli askerî operasyonlara katılıyor, sürekli tetikte yaşıyordu; hayatı aşırı baskı ve kesintisiz adrenalinle geçiyordu. Kanıtlar, hassas bir stratejik operasyon sırasında kendi birliğine saldırdığını gösteriyor. Ama katliamdan sağ kalan olmadığı için kimse kesin olarak bilmiyor. Asker firar etti ve o günden beri bir daha görülmedi.",
["bm_chains_rising"] = "Risen Chains Mask",
["bm_chains_rising_desc"] = "Karanlığa gir, çağrıyı duy ve parmağı tetikte bir kâbus gözü karasına dönüş. Bu, sahada ölümü aldattığın tüm anlara bir saygı duruşudur. Karanlık ordusunun askerisin. Damarlarında adrenalin akıyor; cehenneme bile meydan okuyacak kadar mühimmat taşıyorsun. Karanlıkta yenilmez, ölüme meydan okumaya hazırsın. Bu kez tüm zincirler kırılacak ve yoluna çıkan herkes yaratıcısına kavuşacak.",
["bm_cloaker"] = "Batshit Crazy",
["bm_cloaker_desc"] = "Fizik yasalarını bir şekilde büken, \"Cloaker\" lakaplı WPD özel birimi, her şeyi tek başına yapabileceğini kanıtlamaya çalışan kötü adamların baş belasıdır. Söylentiye göre ilk Cloaker, kimsenin ekip kurmak istemediği sıradan bir SWAT polisiydi. Bunun nedeni belki de etrafında mermiler uçuşurken kung fu tekmeleri savuran kaçık bir ölüm makinesi olmasıydı. Neredeyse her zaman aşırı güç kullanır; ekibiyle birlikte tüm savaş taktiklerini geride bırakırdı. Ama sonuç alıyordu. Üstleri de onu görevde tutup benzer kafadakileri eğitmesini sağladı.$NL;$NL;Gece Görüşü Modunu etkinleştirmek için Atış Modu düğmesini basılı tut.",
