["bm_concussion"] = "Sersemletici El Bombası",
["bm_concussion_desc"] = "Bu sersemleten küçük güzellik herkesin nefesini kesecek, onları öldürmek için gereken fazladan birkaç saniyeyi sana verecek.",
["bm_cop_kawaii"] = "Mega Kawaii",
["bm_cop_kawaii_desc"] = "Kawaii adına seni cezalandıracağım! Aşk için, adalet için, MERCURY BUBBLE BLAST İÇİN!$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_cop_mega_skull"] = "Mega Death Wish",
["bm_cop_mega_skull_desc"] = "Sıkı soyguncuların kendilerine neden Death Wishers demediğini hiç anlamadık. Belki fazla havalıdır.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_cop_plague_doctor"] = "Mega Plague Doctor",
["bm_cop_plague_doctor_desc"] = "Yıllarca iyileştirmek onu yıprattı. İnsanların çaresizlikten doğan zalim yollarına tanık oldu. Vebayı bir hastalık olarak görmekten vazgeçip çare olarak yaymaya başladı.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_cs_continental_coin_cost"] = "$cost; Sikke",
["bm_cs_not_enough_coins"] = "Yeterli Sikke Yok",
["bm_dallas_rising"] = "Risen Dallas Mask",
["bm_dallas_rising_desc"] = "Bugünün toplumunun her lifine işleyen çürümüş yozlaşmaya sert bir karşılık vermek gerekiyor. Kendini kandırmaya, sahte bir güvenlik duygusu için çırpınmaya. Ama güvende değilsin; ne şimdi ne de hiçbir zaman. Amerikan Rüyası, zavallı ruhları yoldan çıkarmak için kılık değiştirmiş, korkunç yaralarla dolu bir kâbus. İhtiyacını al; geleceğini boğazından yakala, hırsını boğulana kadar boğazından aşağı tık. Geçtiğin yerleri arkanda bıraktığın cesetlerle işaretle.",
["bm_donald"] = "The 45th",
["bm_donald_desc"] = "Siyasetçi, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etmeyi amaçlıyordu. Konuşkan bir adam olduğuna şüphe yok.$NL;$NL;45. başkan, tarihin en tartışmalı başkanlarından biriydi. Suçlular arasında ise hâlâ son derece popüler.",
["bm_donald_mega"] = "God Emperor",
["bm_donald_mega_desc"] = "Önünde eğil.$NL;$NL;Mega 45th maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;OVERKILL seni selamlıyor!",
["bm_dynamite"] = "Dinamit",
["bm_dynamite_desc"] = "İsveçli mühendis Alfred Nobel dinamiti ve kayaları patlatmadaki etkisini keşfetti. Ama insanları patlatmadaki etkisini keşfeden, sarhoş maden arayıcısı Ol’ Kenneth oldu.",
["bm_e_wish"] = "The Mayhem Skull",
["bm_e_wish_desc"] = "Tam potansiyeline az kaldı. Değişimi kucakla. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu insan kafatasına benzemiyor; yine de endişelenmene gerek yok.$NL;$NL;Bütün soygunları Mayhem zorluğunda bitirdin mi? Sen nesin, yaratık falan mı? Belki de bu maske sana yakışır.",
["bm_equipment_ammo_bag"] = "Mühimmat Çantası",
["bm_equipment_ammo_bag_desc"] = "Mühimmat Çantasını yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Yerleştirilen çanta taşınamaz. Sen veya ekip arkadaşların, $BTN_INTERACT; tuşunu basılı tutarak çantadan mühimmat alabilir. Çanta, silahlarından birinin mühimmatını dört kez tamamen doldurabilir. Mühimmat Çantasının içeriği tükendiğinde çanta kaybolur. Kalan mühimmat miktarını çantaya bakarak anlayabilirsin.$NL;$NL;Mühimmat Çantası, askerlerin çatışmaya ek mühimmat taşımasını sağlamak amacıyla tasarlanmış taşınabilir bir çantadır.",
["bm_equipment_armor_kit"] = "Zırh Çantası",
["bm_equipment_armor_kit_desc"] = "Zırh Çantasını kullanmak için $BTN_USE_ITEM; düğmesini basılı tutarak seçili zırhını giy. O zamana kadar İki Parçalı Takım Elbise giyersin.$NL;$NL;Zırh Çantası yalnızca bir kez kullanılır ve kullanıldığında kaybolur. Zırh Çantası, seçtiğin zırhı taşımaya yarayan, soygun sırasında kullanılabilen taşınabilir bir çantadır.",
["bm_equipment_bodybags_bag"] = "Ceset Torbası Çantası",
["bm_equipment_bodybags_bag_desc"] = "Ceset Torbası Kutusunu kullanmak için $BTN_USE_ITEM; düğmesini basılı tutarak yerleştir. Yerleştirildikten sonra taşınamaz. Sen ve ekibin $BTN_INTERACT; düğmesini basılı tutarak içinden ceset torbası alabilirsiniz.$NL;$NL;Ceset Torbası Kutusunun kullanım sayısı sınırlıdır. Kalan kullanım sayısını Ceset Torbası Kutusuna bakarak görebilirsin. Ceset Torbası Kutusu, gizlilik sırasında cesetleri taşımak için ek torbalar içerir.",
["bm_equipment_doctor_bag"] = "Doktor Çantası",
["bm_equipment_doctor_bag_desc"] = "Doktor Çantasını yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Yerleştirilen çanta taşınamaz. Sen veya ekip arkadaşların, $BTN_INTERACT; tuşunu basılı tutarak çantayı kullanabilir ve sağlığını yenileyebilir. Doktor Çantasını kullanmak, gözaltına alınmadan önce yere düşebileceğin kalan haklarını da yeniler. Çanta iki kez kullanılabilir.$NL;$NL;Doktor Çantasının kullanım hakkı tükendiğinde çanta kaybolur. Kalan kullanım sayısını çantaya bakarak anlayabilirsin.$NL;$NL;Doktor Çantası, hekimlerin ve diğer sağlık çalışanlarının tıbbi malzeme ve ilaç taşımak için kullandığı taşınabilir bir çantadır.",
["bm_equipment_ecm_jammer"] = "ECM Karıştırıcı",
["bm_equipment_ecm_jammer_desc"] = "ECM Karıştırıcıyı yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Yerleştirilen cihaz taşınamaz ve 20 saniye boyunca etkin kalır.$NL;$NL;$BTN_INTERACT; tuşuna basarak ECM Karıştırıcının geri besleme işlevini açıp kapatabilirsin. Bu işlevin, belirli bir yarıçap içindeki düşmanları etkisiz hâle getirme şansı vardır. Kullanım süresi dolduğunda cihaz çalışmayı durdurur.$NL;$NL;Elektronik karşı tedbir (ECM), radar, sonar ve diğer tespit sistemlerini yanıltmak için tasarlanmış bir elektronik cihazdır. Hedefine ulaşmanı kolaylaştırır.",
["bm_equipment_first_aid_kit"] = "İlk Yardım Kiti",
["bm_equipment_first_aid_kit_desc"] = "İlk Yardım Kiti, ilk yardım için gereken tıbbi malzeme ve ekipmanları içerir.$NL;$NL;İlk Yardım Kitini yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Yerleştirilen kit taşınamaz. Sen veya ekip arkadaşların, $BTN_INTERACT; tuşunu basılı tutarak kiti kullanabilir ve sağlığını yenileyebilir.$NL;$NL;Her İlk Yardım Kiti bir kez kullanılabilir. Kullanıldıktan sonra kaybolur.",
["bm_equipment_grenade_crate"] = "Patlayıcı Çantası",
["bm_equipment_grenade_crate_desc"] = "Patlayıcı Çantasını kullanmak için $BTN_USE_ITEM; düğmesini basılı tutarak yerleştir. Yerleştirildikten sonra taşınamaz ama hem sen hem de ekibin kullanabilir. Fırlatılabilir eşyalarını yenilemek için Patlayıcı Çantasının yakınında $BTN_INTERACT; düğmesini basılı tut. Yalnızca dört kez kullanılabilir.$NL;$NL;Patlayıcı Çantası tükendiğinde kaybolur. Kalan kullanım sayısını Patlayıcı Çantasına bakarak görebilirsin. $NL;$NL;Patlayıcı Çantası, muharebe personelinin patlayıcıları ve diğer fırlatılabilir silahları çatışma alanına taşımak için kullandığı taşınabilir bir çantadır.",
["bm_equipment_sentry_gun"] = "Otomatik Taret",
["bm_equipment_sentry_gun_desc"] = "Otomatik Tareti yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Tareti yerleştirmek, silahlarındaki toplam mühimmatın %30'unu tüketir. Taret ateş edilerek yok edilebilir. Tamamen yok edilmediği sürece tareti geri toplamak, onu otomatik olarak onarır ve içinde kalan mühimmatı iade eder. Mühimmatı bittiğinde ateş etmeyi durdurur. Tareti geri toplayıp yeniden yerleştirerek doldurabilirsin.$NL;$NL;Otomatik Taret, sensörlerinin algıladığı hedeflere otomatik olarak nişan alır ve ateş eder. Genellikle düşmanların dikkatini senden ve ekibinden uzaklaştırmak için kullanılır.",
["bm_equipment_sentry_gun_old"] = "Otomatik Taret",
["bm_equipment_sentry_gun_old_desc"] = "Otomatik Taret, sensörlerinin algıladığı hedeflere otomatik olarak nişan alan ve ateş eden bir silahtır. Askerî taretler geçmişte yakın mesafeden gelen füzeleri ve düşman uçaklarını tespit edip yok etmek için kullanılmıştır.$NL;$NL;Otomatik Tareti yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Yerleştirilen taret taşınamaz. Taret ateş edilerek yok edilebilir. Mühimmatı bittiğinde ateş etmeyi durdurur.",
["bm_equipment_sentry_gun_silent"] = "Susturuculu Otomatik Taret",
["bm_equipment_sentry_gun_silent_desc"] = "Susturuculu Otomatik Tareti yerleştirmek için $BTN_USE_ITEM; tuşunu basılı tut. Tareti yerleştirmek, silahlarındaki toplam mühimmatın %30'unu tüketir. Taret ateş edilerek yok edilebilir. Tamamen yok edilmediği sürece tareti geri toplamak, onu otomatik olarak onarır ve içinde kalan mühimmatı iade eder. Mühimmatı bittiğinde ateş etmeyi durdurur. Tareti geri toplayıp yeniden yerleştirerek doldurabilirsin.$NL;$NL;Susturuculu Otomatik Taret, standart Otomatik Taretin daha sessiz sürümüdür. Dikkat dağıtmaktan çok düşmanları ortadan kaldırmak için kullanılır.",
["bm_equipment_trip_mine"] = "Trip Mines and Shaped Charges",
["bm_equipment_trip_mine_desc"] = "Tuzak Mayınını kullanmak için $BTN_USE_ITEM; düğmesini basılı tutarak yerleştir. $BTN_INTERACT; düğmesine basarak tetikleyici lazeri patlama ve algılama modları arasında değiştirebilirsin.$NL;$NL;Yönlendirilmiş Patlayıcıları kullanmak için $BTN_USE_ITEM; düğmesini basılı tutarak yerleştir. Yerleştirilen patlayıcı birkaç saniye içinde patlar. Tuzak Mayınları, ışını geçen düşmanları yaralayan veya öldüren tuzaklardır. Yönlendirilmiş Patlayıcılar genellikle kasa ve kapıları açmak için kullanılır. İkisi de her türlü çatışmada iyi bir destektir.",
["bm_global_value_a11th_unlock"] = "Açmak için Starbreeze Nebula hesabı oluştur!",
["bm_global_value_afp"] = "Federales Weapon Pack",
["bm_global_value_afp_unlock"] = "Açmak için Federales Weapon Pack DLC’sini satın al!",
["bm_global_value_akm4_pack"] = "Butcher AK/CAR Mod Pack",
