["bm_global_value_alienware_alpha"] = "Alienware Alpha",
["bm_global_value_alienware_alpha_promo"] = "Alienware Alpha",
["bm_global_value_alienware_alpha_promo_unlock"] = "Kilidini açmak için PAYDAY 2: Alienware Alpha Mauler Pack içeriği gerekir!",
["bm_global_value_alienware_alpha_unlock"] = "Kilidini açmak için PAYDAY 2: Alienware Alpha Mask Pack içeriği gerekir!",
