["bm_gloves_bananabike"] = "Banana Black",
["bm_gloves_bananabike_desc"] = "Motosiklet sürerken bunları takıp karşıdan gelen eşekarılarının ödünü kopar.",
["bm_gloves_bike_red_led"] = "Crimson Wave Grips ",
["bm_gloves_bike_red_led_desc"] = "Ele oturan yapısı, şıklığı ve o retro vaporwave havasıyla yanlış seçim olmaz.",
["bm_gloves_bike_yellow_led"] = "Hornet Glow Grips",
["bm_gloves_bike_yellow_led_desc"] = "Eldivenler arasında bunlar hem kullanışlı hem de modayı takip eden türden. Her duruma fazladan bir ışıltı katarlar.",
["bm_gloves_biker"] = "Hardtail",
["bm_gloves_biker_blue"] = "Icy Hardtail",
["bm_gloves_biker_blue_desc"] = "Daha mavi ama bu eldivenin siyah çeşidi kadar dayanıklı.",
["bm_gloves_biker_desc"] = "Rust’ın sele çantasında genellikle bunlardan bir çift bulunur. Gerçi sürmekten çok yumruk atarken kullanmayı sever.",
["bm_gloves_biker_orange"] = "Sunset Hardtail",
["bm_gloves_biker_orange_desc"] = "Kaliforniya gün batımları için.",
["bm_gloves_biker_red"] = "Fiery Hardtail",
["bm_gloves_biker_red_desc"] = "Ekim ayındaki motosiklet gezileri için.",
["bm_gloves_blackstar"] = "Bandido",
["bm_gloves_blackstar_desc"] = "Sen geldiğinde Cehennem de pek geride değildir.",
["bm_gloves_bonemittens"] = "Skeletal",
["bm_gloves_bonemittens_desc"] = "İçindekini dışına yansıt.",
["bm_gloves_chopper"] = "Simple Black",
["bm_gloves_chopper_desc"] = "Gösterişten kaçınan soyguncular bu sade eldiven çiftini tam kendilerine göre bulabilir.",
["bm_gloves_chromecross"] = "Chrome and Crossbones",
["bm_gloves_chromecross_desc"] = "Açık denizde de açık yolda da senin hayatın korsan hayatı.",
["bm_gloves_continental"] = "Lucky",
["bm_gloves_continental_desc"] = "Soyguncular muhatap oldukları kişilerce sürekli yargılanır. Bir toplantıya yanlış kravatla git, çıkarken hakkında ölüm emri verilmiş olabilir. Patronun kızının düğününe hazır takım elbiseyle git, bir sonraki büyük işe çağrılmayabilirsin. Ama böyle eldivenler iyi ya da kötü olmayan, sadece son derece huzursuz edici ve dikkat dağıtıcı bir izlenim bırakır. Jimmy bu yüzden onlara bayılıyor; onun uğurlu damaları.",
["bm_gloves_cosmo"] = "Cosmos",
["bm_gloves_cosmos"] = "Cosmos",
["bm_gloves_cosmos_desc"] = "Soyguncu dediğin nedir ki? Yıldız tozu. Sonsuz evren neler barındırıyor acaba? Kim bilir uzaylı gezegenlerinde, doğru soyguncunun gelip kendilerini soymasını bekleyen kaç banka vardır.",
["bm_gloves_darkmat"] = "Dark Matter",
["bm_gloves_darkmat_desc"] = "Kozmik bir güçsün; görünmez ama inkâr edilemez. Seni hiç kimse görmedi ama çekim gücünün etkilerine her gün tanık oluyorlar. Her yerdesin ve hiçbir yerdesin.",
["bm_gloves_default"] = "VARSAYILAN",
["bm_gloves_default_desc"] = "Soyguncunun varsayılan eldivenlerini kullan",
["bm_gloves_desperadoleather"] = "Pistolero",
["bm_gloves_desperadoleather_desc"] = "Hızla çeker, hep hedefi bulur.",
["bm_gloves_devilclaws"] = "Faustian Bargain",
["bm_gloves_devilclaws_desc"] = "Hadi el sıkışalım.",
["bm_gloves_dodskull"] = "Pallbearer",
["bm_gloves_dodskull_desc"] = "Ne diyeyim, kendi cenazen.",
["bm_gloves_dragonscale"] = "Firescale ",
["bm_gloves_dragonscale_desc"] = "Ateşli pullarla kaplı, sivri dikenlerle dolu bu eldivenleri nefret ettiğin biriyle tokalaşacağın zaman tak.",
["bm_gloves_driverleather"] = "Getaway",
["bm_gloves_driverleather_desc"] = "Twitch’in gözdesi.",
["bm_gloves_esport"] = "Game",
["bm_gloves_esport_desc"] = "Oynamaya hep hazır.",
["bm_gloves_fancycloth"] = "Regal",
["bm_gloves_fancycloth_desc"] = "Sydney’nin bir zamanlar böyle bir çifti vardı ama bir soygunda hepsini kana buladı.",
["bm_gloves_goldnet"] = "70s Driver",
["bm_gloves_goldnet_desc"] = "Güçlü Amerikan arabalarının sokaklara hükmettiği, favorilerin uzunluğunun sınırı olmadığı günlerden bir kaçış şoförü olmak mı istiyorsun? Özlediğin dönem buysa bu eldivenler sana iyi gelir, seni doğru havaya sokar.",
["bm_gloves_hardwork"] = "True Grit",
["bm_gloves_hardwork_desc"] = "Ellerini kirletmekten korkma.",
["bm_gloves_heatleather"] = "Master",
["bm_gloves_heatleather_desc"] = "Bu işi senden iyi bilen yok.",
["bm_gloves_heistwrinkled"] = "Heister",
["bm_gloves_heistwrinkled_desc"] = "Çalmak için şık giyin.",
["bm_gloves_heistwrinkled_purple"] = "Night Heister",
["bm_gloves_heistwrinkled_purple_desc"] = "Gece vakti, soygun vakti.",
["bm_gloves_heistwrinkled_white"] = "Ghost Heister",
["bm_gloves_heistwrinkled_white_desc"] = "Ne girerken gördüler seni ne de çıkarken.",
["bm_gloves_hockey"] = "Cross Check",
["bm_gloves_hockey_desc"] = "Bir soyguncu parmaklarını buzdan korumalı; hem donmuş su olandan hem de karbon türünden.",
["bm_gloves_jesterstripe"] = "Celebratory Leathers",
["bm_gloves_jesterstripe_desc"] = "Bu sağlam deri eldivenlerin dikişleri saf altından. Dünyanın en iyi dokumacıları sekiz ayrı ipliği örerek yaptı. Bir soyguncunun elleri daha azını hak etmez; hele işte geçen sekiz şanlı yıl kutlanıyorsa.",
["bm_gloves_kidswool"] = "Rookie",
["bm_gloves_kidswool_desc"] = "Joy’un soğuk kış gecelerinde hackleme yaparken en sevdiği eldivenler.",
["bm_gloves_leatherspark"] = "Magic Touch",
["bm_gloves_leatherspark_desc"] = "Hiç elmas eldivenlerle elmas çaldın mı? İşte lüks BUDUR!",
["bm_gloves_mnk"] = "Padded Monkey",
["bm_gloves_mnk_desc"] = "Bitkisel tabaklanmış deriden, dolgulu ve hava alan, rahat ve kullanışlı eldivenler.",
["bm_gloves_mnt"] = "Padded Mantis",
["bm_gloves_mnt_desc"] = "Bitkisel tabaklanmış deriden, dolgulu ve hava alan, rahat ve kullanışlı eldivenler.",
["bm_gloves_molten"] = "Molten",
["bm_gloves_molten_desc"] = "Volkanlar genellikle kötü haberdir. Soyulmak üzere olan yerde çalışıyorsan bunları takmış bir soyguncu çok daha kötü haberdir.",
["bm_gloves_murky"] = "Mercenary",
["bm_gloves_murky_desc"] = "İşi yap, vurgunu kap.",
["bm_gloves_neoncity"] = "Neon City",
["bm_gloves_neoncity_desc"] = "90’lar arayıp eldivenleri geri istedi ama Payday Gang \"Siktir et\" deyip elinde tuttu.",
["bm_gloves_overkillpunk"] = "Digital Pistons",
["bm_gloves_overkillpunk_desc"] = "Bu tasarım, bir doz fazla zekâ ilacı almış, kafası bozuk bir Silikon Vadisi dâhisinin eseri. Onun yanmış beyninden kazançlı çıkan sensin.",
["bm_gloves_postmoto"] = "The Classics",
["bm_gloves_postmoto_desc"] = "İnce, klasik siyah deri eldivenler. Hafif ve esnek olduklarından, ganimetinle arana giren kimseye kurşunu sıkman gerektiğinde tetiğe uzanmayı çok kolaylaştırırlar.",
["bm_gloves_punkleather"] = "Horns",
["bm_gloves_punkleather_desc"] = "Korkakça boyun eğenlerden değilsin.",
["bm_gloves_railwork"] = "Engineer",
["bm_gloves_railwork_desc"] = "Senin sayende para treni her zaman vaktinde çalışır.",
["bm_gloves_rainbowmittens"] = "Flower Child",
["bm_gloves_rainbowmittens_desc"] = "Bunu para için yapmıyorsun.",
["bm_gloves_ranchdiesel"] = "Ranchhand",
["bm_gloves_ranchdiesel_desc"] = "Çiftlik hayatının sınav ve sıkıntılarıyla baş etmek için sağlam el gerekir. Özellikle çiftliğin büyük bir silah kaçakçılığı operasyonunun paravanıysa.",
["bm_gloves_redhand"] = "Red Handed",
["bm_gloves_redhand_desc"] = "Seni yakaladılar ama yakalamamış olmayı dileyecekler.",
["bm_gloves_saintsleather"] = "Calling",
["bm_gloves_saintsleather_desc"] = "Acı verme zamanı.",
["bm_gloves_silver"] = "Silver Champion",
["bm_gloves_silver_desc"] = "Gösteriş ve ihtişam, sportif bir kesimle birleşti. Yeter ki üzerine kasa yağı bulaştırma.",
["bm_gloves_sneak"] = "Shadow",
["bm_gloves_sneak_desc"] = "Gizlenerek zenginleş.",
["bm_gloves_spikeknuckle"] = "Mountain Spikes ",
["bm_gloves_spikeknuckle_desc"] = "Dengesiz, gergin ve her yanı sivri. Evet, bu eldiven tam sana göre.",
["bm_gloves_sportsbike"] = "Windriders",
["bm_gloves_sportsbike_desc"] = "Kır yolunda hız yapmak, bankada vezne camını kırarken boğumlarını korumak için.",
["bm_gloves_tactical"] = "Frontline",
["bm_gloves_tactical_desc"] = "Bunlar Washington DC polislerinin sahip olduğu her şeyden daha kaliteli.",
["bm_gloves_tasslefringe"] = "The Impaler",
["bm_gloves_tasslefringe_desc"] = "Bu malzemeden kanı yıkayıp çıkarmak çok kolay!",
["bm_gloves_techhigh_bird"] = "Padded Moto Vermilion",
["bm_gloves_techhigh_bird_desc"] = "Çin uzay programı için geliştirilip sivil kullanıma uyarlanmış koruyucu plakalarla yapılan bu eldivenler, üstün hareket kabiliyeti ve rahatlık sunar.",
["bm_gloves_techhigh_dragon"] = "Padded Moto Azure",
["bm_gloves_techhigh_dragon_desc"] = "Çin uzay programı için geliştirilip sivil kullanıma uyarlanmış koruyucu plakalarla yapılan bu eldivenler, üstün hareket kabiliyeti ve rahatlık sunar.",
["bm_gloves_techhigh_tiger"] = "Padded Moto White",
["bm_gloves_techhigh_tiger_desc"] = "Çin uzay programı için geliştirilip sivil kullanıma uyarlanmış koruyucu plakalarla yapılan bu eldivenler, üstün hareket kabiliyeti ve rahatlık sunar.",
["bm_gloves_techhigh_tortoise"] = "Padded Moto Black",
["bm_gloves_techhigh_tortoise_desc"] = "Çin uzay programı için geliştirilip sivil kullanıma uyarlanmış koruyucu plakalarla yapılan bu eldivenler, üstün hareket kabiliyeti ve rahatlık sunar.",
["bm_gloves_techlow_bird"] = "Comfort Moto Vermilion",
["bm_gloves_techlow_bird_desc"] = "Modern sentetik kumaşlardan yapılmış, hava geçirgenliği ve nem uzaklaştırma özelliği yüksek, ince dolgulu ve kullanışlı bir motosiklet eldiveni.",
["bm_gloves_techlow_dragon"] = "Comfort Moto Azure",
["bm_gloves_techlow_dragon_desc"] = "Modern sentetik kumaşlardan yapılmış, hava geçirgenliği ve nem uzaklaştırma özelliği yüksek, ince dolgulu ve kullanışlı bir motosiklet eldiveni.",
["bm_gloves_techlow_tiger"] = "Comfort Moto White",
["bm_gloves_techlow_tiger_desc"] = "Modern sentetik kumaşlardan yapılmış, hava geçirgenliği ve nem uzaklaştırma özelliği yüksek, ince dolgulu ve kullanışlı bir motosiklet eldiveni.",
["bm_gloves_techlow_tortoise"] = "Comfort Moto Black",
["bm_gloves_techlow_tortoise_desc"] = "Modern sentetik kumaşlardan yapılmış, hava geçirgenliği ve nem uzaklaştırma özelliği yüksek, ince dolgulu ve kullanışlı bir motosiklet eldiveni.",
["bm_gloves_texriding"] = "Rodeo Star",
["bm_gloves_texriding_desc"] = "Bu işi kolaymış gibi gösteriyorsun.",
["bm_gloves_tgr"] = "Padded Tiger",
["bm_gloves_tgr_desc"] = "Bitkisel tabaklanmış deriden, dolgulu ve hava alan, rahat ve kullanışlı eldivenler.",
["bm_gloves_tiger"] = "Tiger Stripe",
["bm_gloves_tiger_desc"] = "Bu şık el ısıtıcılarıyla dünyanın dört bir yanındaki büyük kedilerin yaşadığı zorluklara karşı dayanışmanı göster.",
["bm_gloves_tornrags"] = "Touch of Death",
["bm_gloves_tornrags_desc"] = "İşte ruh budur!",
["bm_gloves_tstp_blackdragon"] = "Black Dragon Claws",
["bm_gloves_tstp_blackdragon_desc"] = "Her parmak deliğinden belalılık sızan daha havalı eldivenler hayal edebiliyorsan hayal gücün epey iyi demektir. En yeni teknolojili kumaşlardan yapılan bu eldivenler parmaklarını hem sıcaktan hem soğuktan korur, özellikle stresli soygunlarda ellerinde oluşan o nemi uzaklaştırır.",
["bm_gloves_tstp_flame"] = "Flame Grip",
["bm_gloves_tstp_flame_desc"] = "Merak etmeden olmuyor... 50’lerde bu modern teknolojili kumaş eldivenler olsaydı bugünün hotrod kültürü nasıl görünürdü?",
["bm_gloves_tstp_reddragon"] = "Red Dragon Claws",
["bm_gloves_tstp_reddragon_desc"] = "Bunları takıp parmaklarının bütün o baş belası polislere ateş püskürttüğünü hayal et.",
["bm_gloves_tstp_redstripe"] = "Burnout Champ",
["bm_gloves_tstp_redstripe_desc"] = "Bir şeyin üzerindeki kırmızı çizgilerin onu hızlandırdığına dair yaygın bir inanış var. 1980’lerin araba kovalamaca filmlerinde işe yaramış olabilir ama soygunu hızlandırması pek olası değil. Yine de hoş görünüyorlar, sence de öyle değil mi?",
["bm_gloves_vpr"] = "Padded Viper",
["bm_gloves_vpr_desc"] = "Bitkisel tabaklanmış deriden, dolgulu ve hava alan, rahat ve kullanışlı eldivenler.",
["bm_gloves_wool"] = "Highland Wool Combo",
["bm_gloves_wool_desc"] = "Hava karanlık, soğuktan donuyorsun. Şehrin lüks semtindeki zengin bir pisliğin malikanesini soymaya hazırlanıyorsun. Bu şık eldivenler olmasa silahının soğuk çeliği ellerini bir dakikada uyuştururdu. Züppeleri soyarken ellerin bile ortama uygun görünmeli!",
["bm_gloves_workranch"] = "Untamed",
["bm_gloves_workranch_desc"] = "Hayatın dizginlerini eline al.",
["bm_grenade_copr_ability"] = "Sülük Ampulü",
["bm_grenade_copr_ability_desc"] = "Sülük yeteneğini etkinleştirmek için burnunun altında küçük bir cam ampul kırıp derin bir nefes almalısın. İçinde ne olduğunu tam bilmiyorsun ama dünyayı daha net görmeni sağlıyor, adrenalinini de tavana vurduruyor. Kesin olan bir şey var: Bu meret ayıltma tuzu değil.",
["bm_grenade_dada_com"] = "Matryoshka Grenade",
["bm_grenade_dada_com_desc"] = "Matruşka El Bombası, fırlatılabilir bir patlayıcıdır. Bebeğin dış katmanları iç mekanizmayı gizler. Ana vatana saygı sunarken ciddi hasar verir.",
["bm_grenade_damage_control"] = "Stoacının Cep Matarası",
["bm_grenade_damage_control_desc"] = "Duke’a gençliğinde Budist keşişlerle eğitim görürken verilmiş, üzerinde \"Stoic\" ve \"JW Spirits\" yazan 1882 tarihli antika bir matara. Duke onu en sevdiği viskiyle dolu tutuyor. Bir yudum almak, sakinleşmeyi simgeleyen bir hareket; taşıyana zen benzeri bir odaklanma anı sağlayıp hasarı hafifletiyor.",
["bm_grenade_electric"] = "X1-ZAPper",
["bm_grenade_electric_desc"] = "Şarapnel iyidir hoştur ama bazı şeyleri kızartmak gerekir. Bu küçük güzellik, yüksek voltajla hasar vermek için pek kullanışlı bir canavar.",
["bm_grenade_fir_com"] = "Yangın El Bombası",
["bm_grenade_fir_com_desc"] = "Yangın El Bombası, kendiliğinden tutuşan tehlikeli bir fosfor kabıdır. Birkaç saniye sonra tutuşur; bu da onu duvarlardan sektirip düşmanlara göndermek için ideal kılar. Tutuştuğunda düşmanları alevler içinde bırakarak ciddi hasar verir.",
["bm_grenade_frag"] = "Parça Tesirli El Bombası",
["bm_grenade_frag_com"] = "HEF El Bombası",
["bm_grenade_frag_com_desc"] = "Bu, klasik el bombasının yenilenmiş sürümü. Orijinal parça tesirli el bombası hâlâ kullanılsa da bu yeni, zarif tasarım her patlamaya OVERKILL dokunuşu katacak. Hâlâ aynı derecede ucuz, hâlâ aynı derecede etkili.",
["bm_grenade_frag_desc"] = "Parça tesirli el bombası ilk ortaya çıktığından beri pek az değişmiş bir kavramdır. Fırlatılan gövde patlayıp parçalarını öyle bir kuvvetle saçar ki eti, kemiği ve hafif zırhı kesip geçebilirler. Ucuz ve etkili.",
["bm_grenade_molotov"] = "Molotofkokteyli",
["bm_grenade_molotov_desc"] = "Molotofkokteyli, el bombası denebilecek belki de en basit silahtır. \"Fitili\" yanan bir bezle değiştirilmiş, yanıcı sıvı dolu kırılabilir bir şişeden ibarettir. Ucuz, basit ve çok etkilidir.",
["bm_grenade_pocket_ecm_jammer"] = "Cep ECM Cihazı",
["bm_grenade_pocket_ecm_jammer_desc"] = "Yakındaki şifreli sinyalleri yakalayıp denetimini ele geçiren küçük bir cihaz. Kablosuz verileri bulup bozan gelişmiş algoritmaları sayesinde Cep ECM Cihazı, hem gölgelerde gizlenirken hem de çatışmanın ortasında kullanıcıya üstünlük sağlar.",
["bm_grenade_poison_gas_grenade"] = "Viper Grenade",
["bm_grenade_poison_gas_grenade_desc"] = "Hem ölümcül hem küçük bir kimyasal silah mı arıyorsun? Daha fazla arama! Bu son derece yasadışı el bombasının patlama yarıçapı sınırlı olsa da saldığı geniş zehirli gaz bulutu, engereğin gücünü avucuna verir. Düşmanların solunum sistemlerine veda edebilir.",
["bm_grenade_smoke_screen_grenade"] = "Sis Bombası",
["bm_grenade_smoke_screen_grenade_desc"] = "Bunlardan birini bırak, bir duman bulutunun içinde kaybol. Düşmanların sana nişan almak için debelenip dursun. Seni doğru dürüst göremediklerinde mermilerden sıyrılmak çocuk oyuncağı.",
["bm_grenade_sticky_grenade"] = "Yapışkan El Bombası",
["bm_grenade_sticky_grenade_desc"] = "Düşmanlara ve yüzeylere yapışan, fırlatılabilir bir patlayıcı.",
["bm_grenade_tag_team"] = "Gaz Dağıtıcı",
["bm_grenade_tag_team_desc"] = "Vücudun duyularını geçici olarak güçlendiren, iki müttefike iyileştirme etkisi sağlayan küçük bir gaz dağıtıcı.",
["bm_grenade_xmas_snowball"] = "Kartopu",
["bm_grenade_xmas_snowball_desc"] = "Suya batır, dondurucuya at; işte ölümcül bir fırlatma silahın var. Basit.",
["bm_hoxton_rising"] = "Risen Houston Mask",
["bm_hoxton_rising_desc"] = "Hayalet hikâyeleri işte böyle çarpık bir yüzden doğar. Parçalanmış ve kasvetli, gölgelerde beklersin. Sonra çıkıp yoluna gelenin ödünü koparırsın. Gerçek korku, bu dehşete bakınca öğrenilir. Bu canavarı besleyen o korkudur; leziz, saf, diri korku. Daha fazlası için bitmeyen bir susuzluk doğurur. Bakma ama gözlerini kapatma.",
["bm_jar_head"] = "Martial Law",
["bm_jar_head_desc"] = "Bu, Chains’in silahlı bir darbeden sonra Orta Amerika’da VIP korumalığı yaparak geçirdiği iki uzun, sıkıcı ayın anısına sakladığı eski bir hatıra. Ona paralı askerliği bıraktıran askerî tekdüzeliği hatırlatıyor.",
["bm_lucky_luciano"] = "Charles \"Lucky\" Luciano",
["bm_lucky_luciano_desc"] = "\"Modern suçun babası\" sayılır. Neden Lucky lakabını aldığı tam belli değil ama 25 kez tutuklanıp hapiste bir gün bile geçirmemeyi başardı. Başka bir mafyaya katılmayı reddettiği için boğazı kesildiğinde de hayatta kaldı. Her hâlükârda gerçek bir ilham kaynağı.",
["bm_madame_st_claire"] = "Stephanie \"Madame\" St. Clair",
["bm_madame_st_claire_desc"] = "Bu gerçekten çetin ceviz. St. Clair’in suçlu yanı, karanlık bir gecede cehennemi yaşarken doğdu. Sonra yasadışı dünyanın derinlerine daldı. Ama sivil haklar ve polis yolsuzluğu konusunda da sesini duyuruyordu. Bir bakıma Robin Hood’un modern, çarpık bir sürümü denebilir.",
