["bm_mclr_yellow"] = "Sarı",
["bm_mega_clover"] = "Mega Clover",
["bm_mega_clover_desc"] = "Mega Clover maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_melee_agave"] = "El Verdugo",
["bm_melee_alien_maul"] = "Alpha Mauler",
["bm_melee_aziz"] = "Tactical Flashlight",
["bm_melee_aziz_desc"] = "Düşmanın geldiğini görmezken kafasına vurmayı sportmenliğe aykırı buluyorsan, indirmeden önce bu el fenerini rahatsız edici biçimde doğrudan gözüne tutmaya ne dersin?",
["bm_melee_ballistic"] = "Specialist Knives",
["bm_melee_baseballbat"] = "Lucille Baseball Bat",
["bm_melee_baseballbat_desc"] = "Sayı turu vuruşları yapabileceğin bir beyzbol sopası.",
["bm_melee_bat"] = "Beyzbol Sopası",
["bm_melee_baton"] = "Telescopic Baton",
["bm_melee_baton_desc"] = "Her soyguncunun ve kolluk görevlisinin kalabalığı denetlemek, itaat etmeyenleri dağıtmak için en sevdiği silah. Teleskopik copun sabit copa göre pek çok avantajı var. Hafif ve etkili, daha çok yönlü; olası saldırganlara da daha korkutucu görünüyor.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_bayonet"] = "Bayonet Knife",
["bm_melee_beardy"] = "Bearded Axe",
["bm_melee_becker"] = "Utility Machete",
["bm_melee_becker_desc"] = "Pala, tropikal ülkelerde yağmur ormanı çalılıklarını ve isyanları kesip biçmek için, bir de tarımda sıkça kullanılan büyük, satıra benzer bir bıçaktır. İnsanların palaları hindistancevizi veya kafatası açmak, bahçe işi yapmak ve banka soymak gibi başka işlerde kullandığını görmek de olağandır.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_boltcutter"] = "Bolt Cutters",
["bm_melee_bowie"] = "Arkansas Toothpick",
["bm_melee_boxcutter"] = "Utility Knife",
["bm_melee_boxing_gloves"] = "OVERKILL Boxing Gloves",
["bm_melee_branding_iron"] = "You're Mine",
["bm_melee_brass_knuckles"] = "350K Brass Knuckles",
["bm_melee_brass_knuckles_desc"] = "Muşta türü silahlar yüzlerce yıldır dünyanın her yerinde kullanılıyor. Muştalar, yumruğun kuvvetini daha sert ve küçük bir alana yönlendirerek yoğunlaştırır; doku hasarı olasılığını artırır. Yeterince sert vurursan kemik de kırarsın.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_brick"] = "Hotline 8000x",
["bm_melee_briefcase"] = "50 Blessings Briefcase",
["bm_melee_buck"] = "Buckler Shield",
["bm_melee_bullseye"] = "Compact Hatchet",
["bm_melee_catch"] = "Hook",
["bm_melee_chac"] = "El Ritmo",
["bm_melee_chac_desc"] = "Ritmi hisset.",
["bm_melee_chef"] = "Psycho Knife",
["bm_melee_clean"] = "Alabama Razor",
["bm_melee_cleaver"] = "Cleaver Knife",
["bm_melee_cqc"] = "Kunai Knife",
["bm_melee_cqc_desc"] = "Başlangıçta tarım aleti olan kunai, doğunun gölge suikastçılarının elinde savaşa girdi. Her an hazır olması için elde, ağızda, kemerde veya parmağa takılı taşınabilir.",
["bm_melee_cqc_info"] = "Zamanla hasar veren ve düşmanların eylemini kesintiye uğratma şansı olan zehirli uçlu bıçak.",
["bm_melee_croupier_rake"] = "Croupier's Rake",
["bm_melee_croupier_rake_desc"] = "Tek amacı parayı kendine çekmek olan bir eşya mı? Tam siz soygunculara göre! Şu baş belası polislere kasanın neden hep kazandığını göster.",
["bm_melee_cs"] = "Lumber Lite L2",
["bm_melee_detector"] = "Metal Detector",
["bm_melee_detector_desc"] = "Bir daha anahtarlarını kaybetmeyeceksin!",
["bm_melee_dingdong"] = "Ding Dong Breaching Tool",
["bm_melee_fairbair"] = "Trench Knife",
["bm_melee_fear"] = "Stainless Steel Syringe",
["bm_melee_fear_desc"] = "Endişelenme; iğnelerden hoşlanmadığını söylediğinde seninle ilgilenen görevliler kızmayacak veya korkak olduğunu düşünmeyecek.",
["bm_melee_fear_info"] = "Zamanla hasar veren ve düşmanların eylemini kesintiye uğratma şansı olan zehir dolu şırınga.",
["bm_melee_fight"] = "Empty Palm Kata",
["bm_melee_fight_desc"] = "Uzak denizaşırı topraklarda bulunan gizli dövüş tarzı",
["bm_melee_fireaxe"] = "Fire Axe",
["bm_melee_fists"] = "Yumruklar",
["bm_melee_fists_desc"] = "Boksör değilsin ama yine de iyi yumruk atabilirsin. Biraz güç, hız ve zamanlama yeter; hemen etkili bir darbe indirirsin.$NL;$NL;Daha fazla hasar vermek için yakın dövüş düğmesini basılı tutarak yumruğunu hazırlayabilirsin.",
["bm_melee_fork"] = "The Motherforker",
["bm_melee_freedom"] = "The Spear of Freedom",
["bm_melee_gator"] = "Machete",
["bm_melee_gerber"] = "Berger Combat Knife",
["bm_melee_gerber_desc"] = "Berger Combat Knife, katlanır klips uçlu namlusu olan popüler bir taktik bıçaktır. Küçük, hafif yapısı ve yüksek teknolojili malzemeleri onu hızlı ve tehlikeli bir alet yapar.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_great"] = "Great Sword",
["bm_melee_grip"] = "Knuckle Daggers",
["bm_melee_hammer"] = "Carpenter's Delight",
["bm_melee_happy"] = "Hackaton",
["bm_melee_hauteur"] = "Kento's Tanto",
["bm_melee_hauteur_desc"] = "Japon Tanto bıçakları, yani kısa kılıçları, hançere benzeyen tasarımlarıyla tanınır.",
["bm_melee_hockey"] = "Hockey Stick",
["bm_melee_hockey_desc"] = "Buz üzerinde diskle kullanılmak üzere tasarlanmış sağlam bir hokey sopası. Ama buz dışında da etkili olduğu kanıtlandı.",
["bm_melee_kabar"] = "URSA Knife",
["bm_melee_kabar_desc"] = "URSA Knife, geçmişi 1942’ye dayanan, dayanıklı ve yıkılmaz bir dövüş ve iş bıçağıdır. Bowie namlu, tırtıklı kenar, laf kalabalığı yok. Bir klasik.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_kabar_tanto"] = "Ursa Tanto Knife",
["bm_melee_kampfmesser"] = "Krieger Blade",
["bm_melee_kampfmesser_desc"] = "Krieger Blade, Alman Ordusu’nun standart bıçağıdır. Sağlam kavrayışı ve Tanto namlusu onu çatışma için mükemmel bir seçim yapar.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_machete"] = "Machete Knife",
["bm_melee_meat_cleaver"] = "Dragan's Cleaver Knife",
["bm_melee_meter"] = "Two Handed Great Ruler",
["bm_melee_meter_desc"] = "İki elle kullanılan büyük cetvelimiz, ürettiğimiz en büyük cetvel. Ama boyutuna aldanma; bu harika cetvelin hantal veya kullanışsız bir yanı yok.",
["bm_melee_microphone"] = "Microphone",
["bm_melee_microphone_desc"] = "Mikrofon mu dedin?",
["bm_melee_micstand"] = "Microphone Stand",
["bm_melee_micstand_desc"] = "Sahne korkusunu sahne hâkimiyetine dönüştür!",
["bm_melee_mining_pick"] = "Gold Fever",
["bm_melee_model24"] = "Potato Masher",
["bm_melee_moneybundle"] = "Money Bundle",
["bm_melee_moneybundle_desc"] = "Parayı bir şeritle demetlemek, paranın kendisi kadar eskidir. Zenginler ve pezevenkler de çok uzun zamandır insanları parayla dövüyor.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_morning"] = "Morning Star",
["bm_melee_nin"] = "Pounder",
["bm_melee_oldbaton"] = "Classic Baton",
["bm_melee_oldbaton_desc"] = "Klasiklerin üstüne yok!",
["bm_melee_ostry"] = "Kazaguruma",
["bm_melee_ostry_desc"] = "Yel Değirmeni olarak da bilinen Kazaguruma, eti tereyağı gibi kesen hızlı ve ölümcül bir yakın dövüş silahıdır.",
["bm_melee_oxide"] = "Rezkoye",
["bm_melee_pitchfork"] = "Pitchfork",
["bm_melee_poker"] = "Poker",
["bm_melee_pugio"] = "Diving Knife",
["bm_melee_push"] = "Push Daggers",
["bm_melee_rambo"] = "Trautman Knife",
["bm_melee_rambo_desc"] = "Trautman Knife, ağır bir bowie namlusu olan hayatta kalma bıçağıdır. Uzunluğu, tırtıklı sırtı ve ortalanmış ucu doğada da yakın dövüşte olduğu kadar iyi iş görür.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_road"] = "Chain Whip",
["bm_melee_sandsteel"] = "Shinsakuto Katana",
["bm_melee_sap"] = "Leather Sap",
["bm_melee_scalper"] = "Scalper Tomahawk",
["bm_melee_scoutknife"] = "Scout Knife",
["bm_melee_selfie"] = "Selfie-Stick",
["bm_melee_shawn"] = "Shawn's Shears",
["bm_melee_shillelagh"] = "Clover's Shillelagh",
["bm_melee_shock"] = "Monkey Wrench",
["bm_melee_shock_desc"] = "Patron cumartesi çalışmamız gerekeceğini söyleyerek planlarımıza çomak soktu.",
["bm_melee_shovel"] = "K.L.A.S. Shovel",
["bm_melee_shovel_desc"] = "K.L.A.S. kürek, ordular tarafından pek çok amaçla kullanılır. Hayatta kalma meraklılarının, serbest dalışçıların, kampçıların, doğa yürüyüşçülerinin, bahçıvanların ve savaş canlandırması gruplarının elinde de görülebilir. Silah olarak da kullanılabilir; kenarlarını bile, eti de kemiği de kesip geçersin. Tabii doğru kullanırsan. Sen öyle kullanmıyorsun.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_slot_lever"] = "Jackpot",
["bm_melee_slot_lever_desc"] = "Bir hafta süren, fazla ileri gitmiş bir Vegas âleminin hüzünlü (ve komik) kalıntısı. Kötü şansın ve kötü hayat kararlarının gücüyle polisleri patakla.",
["bm_melee_spatula"] = "Spatula",
["bm_melee_spoon"] = "Comically Large Spoon",
["bm_melee_spoon_gold"] = "Comically Large Spoon of Gold",
["bm_melee_stick"] = "Shepherd's Cane",
["bm_melee_swagger"] = "Swagger Stick",
["bm_melee_switchblade"] = "Switchblade",
["bm_melee_switchblade_desc"] = "Ellilerde iki New York gençlik çetesinin hesabını görmesi için sıkça kullanılırdı. Şarkıya da eşlik edebilirsin.",
["bm_melee_sword"] = "The Pen",
["bm_melee_sword_desc"] = "Keskin, isabetli ve gizlenebilirliği yüksek Pen, her şeyin tükendiğinde ve bir aortu delmek istediğinde en iyi dostundur.",
["bm_melee_taser"] = "Buzzer",
["bm_melee_taser_desc"] = "İşte beklediğin bu. Şu kendini beğenmiş Taser’lardan tatlı, elektrikli intikamını al. Al sana yıldırım!",
["bm_melee_taser_info"] = "Temasta hedeflere elektrik verip onları durduran aygıt",
["bm_melee_tenderizer"] = "Tenderizer",
["bm_melee_tiger"] = "Talons",
["bm_melee_tiger_desc"] = "Birden çok bıçağın olabilecekken neden tek bir taneyle yetinesin?",
["bm_melee_tomahawk"] = "Survival Tomahawk",
["bm_melee_tomahawk_desc"] = "Tarih boyunca çok amaçlı bir alet olarak, insanlara fırlatmak için ve ara sıra göğüs göğüse çarpışmada kullanıldı. Neredeyse her haydudun az çok ustalaşabileceği bir silah. Tomahawk’ın hem alet hem de silah olarak gerçek potansiyeli ancak hakkıyla soygun yaparak keşfedilebilir. Ama daha çok silah olarak.$NL;$NL;Yakın dövüş düğmesini basılı tutarak bu silahın darbesini güçlendirebilir ve daha fazla hasar verebilirsin.",
["bm_melee_toothbrush"] = "Nova's Shank",
["bm_melee_topaz"] = "Ice Pick",
["bm_melee_twins"] = "Okinawan Style Sai",
["bm_melee_twins_desc"] = "Okinawalı kolluk görevlilerinin kullandığı Sai hem saldırı hem savunma silahıdır. Soygunda karşına çıkanlara hızlı darbeler indirmek için de kusursuz bir araçtır.",
["bm_melee_weapon"] = "Weapon Butt",
["bm_melee_weapon_desc"] = "Silahlı soygunlarda kurbanları silahla dövmek, onları vurmaktan veya bıçaklamaktan genellikle daha yaygındır. Çoğunlukla tüfekle dipçik vurur veya tabancayla kabza darbesi indirirsin.$NL;$NL;Bu en hızlı yakın dövüş saldırısıdır.",
