["bm_mod_incompatibility_most"] = "çoğu",
["bm_mod_incompatibility_some"] = "bazıları",
["bm_mr_pickle"] = "Pickle Face",
["bm_mr_pickle_desc"] = "İnce, sert, yeşil bir ölüm makinesi. Başın derde girip bir an önce sıvışman gerektiğinde takılacak kusursuz maske. Su gibi ol dostum.",
["bm_msg_alex_desc"] = "Kız ve erkek kardeşten oluşan ikilinin bir yarısı Alex. Kuğular gibi amansızlar. Kuğuların aksine testere ve hafif makineli silah kuşanıyorlar. Kuğular gibi birbirlerine sıkı sıkıya bağlılar. Kuğuların aksine katliama düşkünler.",
["bm_msk_achievement_milestone_postfix_WIN32"] = "$NL;$NL;Bu maske bir başarım dönüm noktası ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_achievement_postfix_WIN32"] = "$NL;$NL;Bu maske bir başarım ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_agatha_knight"] = "Agatha Knight Veteran",
["bm_msk_agatha_knight_desc"] = "Tenosia’nın kurak çorak topraklarından çıkarılan bu Agathian Knight miğferi, onu kılıçlardan ve oklardan koruyabilirdi. Ama King Alphonso kadar hayalperest bir liderin kanlı hırslarından koruyamadı.",
["bm_msk_agatha_vanguard_veteran"] = "Agatha Vanguard Veteran",
["bm_msk_agatha_vanguard_veteran_desc"] = "Yurdunu ve kralının düzenini haddini bilmez Masons’dan geri almaya çalışırken güce, desteğe ve korkutucu bir çehreye ihtiyacın olur. Bu Vanguard miğferi üçünü de sağlar.",
["bm_msk_alex"] = "Alex",
["bm_msk_alex_desc"] = "Kız ve erkek kardeşten oluşan ikilinin bir yarısı Alex. Kuğular gibi amansızlar. Kuğuların aksine testere ve hafif makineli silah kuşanıyorlar. Kuğular gibi birbirlerine sıkı sıkıya bağlılar. Kuğuların aksine katliama düşkünler.",
["bm_msk_alien_helmet"] = "Alpha Gray",
["bm_msk_alien_helmet_desc"] = "Gray Aliens, varlıkları UFO, paranormal olaylar ve New Age topluluklarında savunulan, ten renklerinden adını alan sözde dünya dışı varlıklardır.$NL;$NL;Yoksa gerçekten varlar mı?",
["bm_msk_alienware"] = "Alienware",
["bm_msk_alienware_desc"] = "Dünya dışı bir varlık gördüğünü sanan bir delinin hayallerinden esinlendi.$NL;$NL;Ama tuhaf; çünkü sağlam malzemeleri Dünya’nın hiçbir yerinden gelmiyor.",
["bm_msk_almirs_beard"] = "Almir's Beard",
["bm_msk_almirs_beard_achievement"] = "Açmak için Kar Fırtınasının Binicileri başarımını tamamla!",
["bm_msk_almirs_beard_desc"] = "Bazıları gerçek erkekler tıraş olmaz der ama doğrusu gerçek erkekler tıraş olamaz. Sıradan jiletler, gür bir Almir sakalının sık, görkemli bitki örtüsünden sekip gider.",
["bm_msk_ami_01"] = "Mega Rad Mutant",
["bm_msk_ami_01_desc"] = "Radyoaktif sprey boya çekmiş gibi, güç seviyesi bir kademe daha yükseldi; artık patlamak üzere. Soyguna çıktığında sen geçerken çevrendeki herkes siper arayacak. Şehirdeki bütün Geiger sayaçları çıldırmak üzere.",
["bm_msk_ami_02"] = "Mega Famine",
["bm_msk_ami_02_desc"] = "İstediğin o somun ekmeği düşün. Şimdi o açlığı bin katına çıkar. Bu sadece yemek eksikliği değil; ruhunun kendisi de karnın kadar boş kalana dek besinden yoksun. Açlık ölümün ötesinde sürseydi böyle bir çehreye bürünürdü. Ama böyle bir çile, soygun için güçlü bir itici güç olabilir.",
["bm_msk_ami_03"] = "Mega Conquest",
["bm_msk_ami_03_desc"] = "Eski kralların böyle bir eseri olsaydı yenilmez olurlardı. Hangi düşman ihtişamına bakarken önünde eğilmemeye dayanabilir? Sun Tzu gidip limon emsin; böyle bir maskeyle savaşta sanata kimin ihtiyacı var?",
["bm_msk_ami_04"] = "Mega Arch Nemesis",
["bm_msk_ami_04_desc"] = "Bir hamle, sonra bir hamle daha. Rakibin hamle yapar, sen karşılık verirsin. Altın dağının tepesinde duruyor, gelip meydan okumasını kabul etmen için sana kafa tutuyor. Bu maskeyi takarak boyun eğmediğini ilan edersin; oyun sürer, rekabet bitmez.",
["bm_msk_ami_05"] = "Mega Tormentor",
["bm_msk_ami_05_desc"] = "İşkenceci mi, işkence gören mi? Belki ikisi de. Gözlerindeki kaynayan parıltı, kanunun ruhuna dehşet ürpertileri salıyor. Seni yakalama girişimlerinin her birini boşa çıkarırken damarlarında kötücül bir neşe akıyor. Mavi üniformalılardan ustalıkla sıyrılırken ağıtlarını dinle.",
["bm_msk_ami_06"] = "Mega Greed",
["bm_msk_ami_06_desc"] = "Kalbine yanıp işler, kafatasından eti söker; turuncu alevler, daha fazlasına duyulan dinmez ihtiyacın rengiyle tezat oluşturur. Tatmin olana kadar kasaya kaç kez daha döneceksin? Kaç silah seni mutlu eder? Hepsi! Belki.",
["bm_msk_amp_01"] = "Schneider",
["bm_msk_amp_01_desc"] = "Gelmiş geçmiş en vahşi ve acımasız korsanlardan biri. Aynı zamanda en az bilinenlerden. Tam da Schneider’in istediği gibi. Onun yerine Schneider’in \"the Devil\" lakabı çok daha yaygındı. Kimsenin gerçek yüzünü bilmemesini daha kârlı buluyordu. Ama \"şeytanın\" yedi denizde nasıl yelken açtığına dair hikâyeler Karayip barlarında dolaşıyordu. Biri denizde kaybolunca \"ufukta the Devil’ı görmek\" sıkça söylenirdi. Gerçekse Schneider’in onları sonsuza dek sulu bir mezara gömmesiydi.",
["bm_msk_amp_02"] = "Keelhauled Alex",
["bm_msk_amp_02_desc"] = "Her gemi hayalet hikâyeleri getirir. Gece geç vakitte yorgun gözcülerin gördüğü huzursuz ruhlar; Kraken’lerden denizkızlarına kadar her şey. Ama Keelhauled Alex’in hikâyesi belki de en korkulanlardan biridir. Alex, denizdeki uzun bir yolculukta yiyecek çalıyordu. Yakalanınca geminin omurgasının altından sürüklenmeye mahkûm edildi. Suçu ağır değildi ama cezası ağırdı. Alex geminin altındayken başka bir gemi ateş açtı ve Alex aşağıda terk edilip unutuldu. Ortalık yatışınca cesedi derinliklere atıldı. Ama o zamandan beri Keelhauled Alex geceleri gemilerde dolaşır, kaptandan sıradan tayfaya kadar herkese gözlerini diker. Ruhunun içine bakıp onu yutabildiği söylenir.",
["bm_msk_amp_03"] = "Nilam",
["bm_msk_amp_03_desc"] = "Nilam, korsanların ve deniz yağmacılarının arasında büyüdü. Konuşmadan romu tanıdı, yürümeden kılıç tuttu. Nilam’ın ailesi yoktu; onun yerine korsanların göçebe yaşamını kaderi olarak benimsedi. Kılıcı çevikti, dövüşte pek az kişi ona denk gelirdi. Tek istediği, diğerlerinin gördüğü saygıydı ama bu dünya erkeklerin elindeydi. Sonunda Nilam’ın sabrı taştı. Ona haksızlık edenler boğazları kesilerek \"hüküm giydi\". Şöhreti kendisinden önce gidiyordu; Verdict adlı gemisi limana girerken, limanlar yanında getirdiği kıyımdan korkardı.",
["bm_msk_amp_04"] = "One-Eyed Jessicah",
["bm_msk_amp_04_desc"] = "Jessicah’nın iki gözü olsaydı asla ünlü olmazdı. Bir gemi kazasından sonra küçük bir adacığa yüzmeyi başardı. Etrafında bir köpekbalığı dolaşıyor, görünürde yardım da yoktu; kapana kısılmıştı. Elinde sadece kırık bir bıçak vardı. Kıyıya güvenle yüzebilmek için tek seçeneği köpekbalığını öldürmekti. Ama onu gafil avlamak için bir yeme ihtiyacı vardı. Parmağını kaybetmek yüzmeyi zorlaştırırdı; o da gözlerinden birini oyup kanlı parçayı suya attı. Sonra daldı.",
["bm_msk_ancient"] = "The Crossbreed",
["bm_msk_ancient_desc"] = "Bazılarının evrendeki en gelişmiş varlıklar olarak tanımladığı güçlü bir uzaylı ırkı. Crossbreed ile temas kuran farklı ırklar onlara farklı adlar verir.$NL;$NL;Güçlü, ince yapılı ve zeki Crossbreed, karşılaştığı her uzaylı ırkının DNA’sındaki en iyi özellikleri alır ve hep doğru yönde evrildiğinden emin olur.",
["bm_msk_ancient_desc_WIN32"] = "Bazılarının evrendeki en gelişmiş varlıklar olarak tanımladığı güçlü bir uzaylı ırkı. Crossbreed ile temas kuran farklı ırklar onlara farklı adlar verir.$NL;$NL;Güçlü, ince yapılı ve zeki Crossbreed, karşılaştığı her uzaylı ırkının DNA’sındaki en iyi özellikleri alır ve hep doğru yönde evrildiğinden emin olur.$NL;$NL;Bu maske bir Humble Bundle E3 maskesidir. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_andromeda"] = "Augmentation",
["bm_msk_andromeda_desc"] = "Gelecek geldi. Bu özel ağızlığın geleceğin askerleri için geliştirildiği düşünülüyor. Yalnızca gaz maskesi olmakla kalmıyor, takan kişiye su altında nefes alma yeteneği de veriyor. Ne yazık ki bu bozuk gibi ama hâlâ havalı görünüyor.",
["bm_msk_anonymous"] = "Anonymous",
["bm_msk_anonymous_desc"] = "Maskeyi tak, anonim ol ve dilediğini yap.$NL;$NL;İnandığın için yap, sana söylendiği için yap ya da sırf eğlencesine yap.$NL;$NL;Normal toplumun izin vermediği her şeyi yap. Banka soymak gibi.",
["bm_msk_ant_01"] = "INTERCEPTOR ",
["bm_msk_ant_01_desc"] = "Interceptor BX-99 modeli, \"düzeni sağlamak\" için üretildi. Yoruma çok açık bir görev. Sokaklarda dolaşır, sivillerin güvende, her şeyin \"yolunda\" olduğundan emin olurdu. Bir montaj fabrikasının yakınında olay çıkınca bu Interceptor işi fazla ileri götürdü. Bazı siviller yaralandı, bazıları yok edildi, hava mermilerle doldu. Interceptor, montaj fabrikasının işleyişini aksatmamak için mutlak gerekli gördüğü şeyi yaptı. 151010130807 seri numaralı Interceptor BX-99 daha sonra söküldü.",
["bm_msk_ant_02"] = "VIZOR ",
["bm_msk_ant_02_desc"] = "Robot savaşlarıyla dalga geçmek kolay. Ölü şeylerle savaşan başka ölü şeyler. Ama yapay zekâ geliştikçe işler ciddileşti. Vizor gibi askerler, çoktan ölmüş insanların düzenlediği kargaşada kilit rol oynadı. Düğmeye basan ama sonuçlarını yaşamayan insanlar. Robotlar robotlara karşı dönerken Vizor gibi askerler yükseldi; kalbi atanlar ise anıya dönüştü.",
["bm_msk_ant_03"] = "MOTH ",
["bm_msk_ant_03_desc"] = "Her savaşın haini vardır. Moth da onlardan biriydi. Ne pahasına olursa olsun bilgi elde etmek için yapılmış bir nöbetçi robot. Ama hiyerarşi ve güç sıkça arzulanır. Savaşlar yozlaşma doğurur; Moth mantığını izleyip taraf değiştirdi ve milyonlarca robotun bağlantısının kesilmesine neden oldu. Bir tarafın alkışlayıp diğerinin nefret ettiği Moth, savaşın gidişini değiştiren piyonlardan biri oldu.",
["bm_msk_ant_04"] = "DOME ",
["bm_msk_ant_04_desc"] = "Dome, karşı tarafın planlayıp başlattığı büyük bir tertibin merkezindeydi. Onarmak, yeniden birleştirmek ve düzenlemek için yapılmış basit bir robot olan Dome, düşmanın yıktığı bir devlet binasını yeniden kurmakla görevliydi. Commander Wasp’ın arabası enkazın yanından geçerken yakınlarda onu öldürmek için gizli bir saldırı hazırlanıyordu. Dome saldırıyı gördü, kendini arabanın önüne atarak aracın patlamadan uzaklaşmasını sağladı ve Commander’ı korumak için kendini feda etti. Wasp hayatta kaldı, Dome kalmadı.",
["bm_msk_ant_05"] = "SKULL ",
["bm_msk_ant_05_desc"] = "Her savaşın cellatlara ihtiyacı vardır. Sıradan bir asker değil; tehditkâr tavrıyla can alabilen biri. \"Sistem\" için çalışan, emirlere körü körüne uyan biri. Skull bunlardan biriydi. Bıkmadan robot üstüne robotun, savaş suçlularının ve \"dava\" için \"tehlikeli\" sayılan diğer herkesin bağlantısını kesen biri.",
["bm_msk_ant_06"] = "DRONE ",
["bm_msk_ant_06_desc"] = "Bir robotun olabileceği kadar ölümcül tasarlandı. Great Purge’den tek başına Drone sorumluydu. Tüm zihinlere ve tarihî veri sunucularına sonsuza dek kazındı. Drone, gözden çıkarılabilir bir erden beklenenin ötesine geçecek becerilere sahipti; sonunda paha biçilemez oldu. Great Purge savaşın yönünü değiştirdi: uyuyan hücreler ortaya çıktı, robotların bağlantısı kesildi, Hive Mind binlerce zettabayt kaybetti. Drone, Ming Ji Memorial Park’ta bakılıp hayranlık duyulan bir heykele dönüştü. ",
["bm_msk_ant_07"] = "WASP ",
["bm_msk_ant_07_desc"] = "Commander Wasp inanılmaz teknik kapasiteye sahipti. Gücü ve zekâsı karşı tarafı açık ara geride bırakıyordu. Düşman kuvvetlerini zekâsıyla alt edecek devrelere sahip bir prototipti. Ama denenmemiş bir prototip. Aceleye gelmiş. Fazla deneysel. Delilik devre kartlarına da vurur ama biz ona \"hata\" deriz. Bir paranoya nöbetinde kendi askerlerini öldüren Commander Wasp, savaş suçlusuna dönüştü.",
["bm_msk_ant_08"] = "RAPTOR ",
["bm_msk_ant_08_desc"] = "Raptor bir avcı pilotuydu. Uçurduğu her uçağın merkezine bağlanıp kararlılıkla yön verirdi. Mesele birikmiş bilgiydi. Bütün pilotlara aynı yazılım yüklense de yapay zekâ öğrenir. Raptor da bir şekilde bilgisini koruyacak kadar uzun yaşamayı başardı. Düşman bölgesine geçince yakalanıp hacklenebilecekleri için avcı pilotlarına Hive Mind yasaktı. Ama Raptor, düşman üslerini tereddütsüz yok etmekte en iyi olmayı öğrendi.",
["bm_msk_anubis"] = "Anubis",
["bm_msk_anubis_desc"] = "Mısır’ın çakal başlı ahiret tanrısı Anubis, mezarları doldurmaktan çok korumaya çalışırdı.",
["bm_msk_arch_nemesis"] = "Arch Nemesis",
["bm_msk_arch_nemesis_desc"] = "Sözlükte Nemesis (baş düşman)$NL;$NL;İsim [baş düş-man]$NL;$NL;1. Kişinin üstesinden gelemediği, başaramadığı şey vb.: \"Öğle yemeğindeki o Çin büfesi benim baş düşmanım çıktı.\"$NL;2. Kişinin yenemediği rakip.$NL;3. Klasik mitolojide, ilahi intikam tanrıçası.$NL;4. İntikam veya ceza getiren kişi, etken ya da eylem.$NL;$NL;Hoxton’a göre: \"O siktiğimin Bulldozer’ı. Benim baş belası düşmanım o. İğrenç herif!\"",
["bm_msk_area51"] = "The Anomaly",
["bm_msk_area51_desc"] = "Penrose desenli, hızla soğutulmuş metal alaşımlardan dövülen bu miğfer, çok gizli bir kaza alanından çıkarılan enkazla yapıldı. Hükümet varlığından haberdar olduğunu inkâr etmeyi sürdürüyor.",
["bm_msk_aviator"] = "The Heat",
["bm_msk_aviator_desc"] = "Herkes iyi bir güneş gözlüğünü sever.$NL;$NL;Ama yalnızca en küstah, en çok aranan, polisi takmayan belalı herifler onu takıp banka soyacak kadar çılgındır.$NL;$NL;İşte o sensin.$NL;$NL;Bu maske, Kötü Şöhret ağacı ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin. Ancak desen, renk veya malzeme ile bunları birleştirmek için ödediğin özelleştirme ücreti kaybolur.",
["bm_msk_baba_yaga"] = "Baba Yaga",
["bm_msk_baba_yaga_desc"] = "Bazen kötücül, her zaman gizemli. The Baba Yaga, Slav mitlerinin karanlık ormanlarında dolaşır. Bir havanda uçar, havaneli kullanır ve dev tavuk bacakları üzerinde yürüyen bir kulübede yaşar.",
["bm_msk_baby_angry"] = "Angry Baby",
["bm_msk_baby_angry_desc"] = "HIRRRRRRR HIRR hırr hır hır HIRRR Iıh, ııh, IIIIIIIIIIIH! HIRR! Hır.$NL;$NL;HIRRR hır HIRRR hırr HIRRRRRRRRRRRR, ııh, IH, IH, IH, HIRR.",
["bm_msk_baby_cry"] = "Cry Baby",
["bm_msk_baby_cry_desc"] = "Iıııh, ıııh, ıh, IIIIIIIIIIIIIIIIIH, ıh, IIIIIIIIH, IIIIIIH!$NL;$NL;IIIIIIIIIIIIIIIIIH, ıh, IIIIIIIIH, IIIIIIH, Iıııh, ıııh, ıh. Ih. IIIIIIIIIIIIIIIIIIIIIIIIIIIIIH!",
["bm_msk_baby_happy"] = "Happy Baby",
["bm_msk_baby_happy_desc"] = "Ffff, gaga, bo, gaga bo GAGA GAGA? GAGAGAGA? GAGA? Gagag GOGOGO GAGA? GAGA! GOGO! Bah. Gaga bah gogo go.$NL;$NL;GAGA? GAGA! GOGO! Bah. GAGAGA? GAGA GOGO GAGAGA? GAGA! Gagaga gogoga. Fff.",
["bm_msk_babyrhino"] = "Baby Rhino",
["bm_msk_babyrhino_desc"] = "Kim yavru gergedan başı takmak istemez ki? Sevimli değil mi? Takınca kendini biraz aptal hissediyorsun, belki de görünüşünden.$NL;$NL;Takarken maskeden görmenin biraz zor olduğundan endişeleniyorsun. Domuz kafalı dostlarınla uzaklara gitmediğin sürece sorun olmaz.",
["bm_msk_baitface"] = "Funnyman",
["bm_msk_baitface_desc"] = "The Funnyman insanları güldürmeyi bilir. The Funnyman bazen fazla ileri gidip bir iki darbe yiyebilir. Ama dikkat et; başkalarının kahkahasını yönetebilen biri, son gülen olmayı da bilir.",
["bm_msk_balaclava"] = "Balaclava",
["bm_msk_balaclava_desc"] = "Silahlar değişebilir, ideolojiler kayabilir, aksanlar farklılaşabilir ama kar maskesi on yıllardır silahlı soyguncuyla teröristin vazgeçilmezidir. Çakmaktaşı gibi sert gözlerinle zalim, çarpık ağzın dışında her yerini kapatır; hava soğukken sıcak da tutar.",
["bm_msk_bandcap_dark"] = "State Crime",
["bm_msk_bandcap_dark_desc"] = "Amarillo’da bir benzin istasyonunu soyarken bu şapka, kasiyere paranın memlekette kalacağını anlatır.",
["bm_msk_bandit"] = "Wild West Classic",
["bm_msk_bandit_desc"] = "Geniş kenarlı şapka, çelik bakış ve ağza çekilmiş fular. Öyle ikonik, klasik ve etkili bir birleşim ki her yerde gangsterlerin ve soyguncuların vazgeçilmezi olmayı sürdürüyor.",
["bm_msk_banshee"] = "Geist",
["bm_msk_banshee_desc"] = "Bazı ruhlar varoluşun kıyısında oyalanıp mobilyaları hareket ettirmekle, geceleri inlemekle yetinir. Bazılarıysa daha somut bir etki ister. D.C. Polisi daha geçenlerde şehirdeki büyük bankalarda, sanat müzelerinde ve kuyumcularda hayalet vakalarının keskin biçimde arttığını bildirdi. Tanıklar değerli eşyaların kendi kendine kapıdan süzülüp çıktığını söylüyor. Son bir vurgun için dönen, çoktan ölmüş soyguncuların hayaletleri olmalı.",
["bm_msk_bear"] = "Mark",
["bm_msk_bear_desc"] = "Rusya’dan merhaba.$NL;$NL;Bence dünyanın en iyi oyunu olacak.$NL;$NL;Sadece bir ayı.$NL;$NL;Az önce burada bir boşluk vardı.$NL;$NL;Teşekkürler$NL;$NL;- Vasiliy",
["bm_msk_biglips"] = "The Big lips",
["bm_msk_biglips_desc"] = "Bu maskeyi takıp birine dudak göster.$NL;$NL;İnsanları etkileyen şey, maskenin ağzını çevreleyen iki etli kıvrım; gördüğün en büyük dudaklar.$NL;$NL;\"Ağzını aç ve aaa de\" diye talimat verdi banka soyguncusu.",
["bm_msk_biker"] = "Biker",
["bm_msk_biker_classic"] = "The Classic",
["bm_msk_biker_classic_desc"] = "Bu eski usul motosiklet kaskı, dünyanın her yanındaki motorcuların değer verdiği bir mirasın parçası. Tarzdan çok nostaljiyle ilgili. Bu kask seni motorculuğun altın çağı olan 1940’lara götürüyor.",
["bm_msk_biker_desc"] = "Heyecan peşinde koşan, risk alan, anı yaşayan bir soyguncuysan en azından biraz korunman önemlidir. Satır sallayan bir manyaksan da öyle.",
["bm_msk_biker_helmet_red_led"] = "Crimson Striker Helmet ",
["bm_msk_biker_helmet_red_led_desc"] = "Bu göz alıcı kask sana akıcı, aerodinamik bir görünüm verir. Tasarımcısının onu yaparken son ses vaporwave dinlediğine şüphe yok.",
["bm_msk_biker_helmet_yellow_led"] = "Hornet Striker Helmet",
["bm_msk_biker_helmet_yellow_led_desc"] = "Bu neon tarzı belalı kask, dalıp her vuruşunu etkili kılman ve mallarla çıkman için sana ilham verecek.",
["bm_msk_bloodysnarl"] = "Vampyr",
["bm_msk_bloodysnarl_desc"] = "Vampirlerden iyi soyguncu olur mu, henüz belli değil. Hipnoz, yarasaya dönüşmek; hepsi büyük avantajlar. Ama davet edilmeden binaya giremiyorlar. Bu da izinsiz girme işini eliyor. Bir de yansımaları yoksa güvenlik kameralarında görünürler mi? Vampir dostlarımıza sormamız gerekecek.",
["bm_msk_bny_01"] = "Navy Beanie",
["bm_msk_bny_01_desc"] = "Bu çekici parça seni şehrin diline düşürecek. \"TASER’LARI GÖNDERİN!\", \"POLİS! ELLERİNİZ HAVADA DIŞARI ÇIKIN!\" veya \"BU ADAMLAR KİM, ESKİ ASKER Mİ?!\" gibi şeyler duyman garanti.",
["bm_msk_bny_02"] = "Green Beanie",
["bm_msk_bny_02_desc"] = "Görünümüne hafif bir gizem katan bulanık yeşil. FBI, kendi yeşil üniformalı ekiplerine duyduğun yakınlığı takdir edecektir. Bu, üzerinize açıkça ateş etmelerini engellemeyecek gerçi!",
["bm_msk_bny_03"] = "Black Beanie",
["bm_msk_bny_03_desc"] = "Çoğu soyguncu geceye karışabilmek için bu sıkı, gizleyici başlığı seçer. Ne yazık ki onca ekipmanı taşırken kendini gizlemene pek faydası olmayacak.",
["bm_msk_bny_04"] = "Red Beanie",
["bm_msk_bny_04_desc"] = "Sözde \"üç milyon dolarlık şapka\" ya düşmanlarının kanına bulanmış ya da yalnızca kırmızı yünden yapılmış. Her soygundan sonra yıka yeter!",
["bm_msk_bobblehead_dozer"] = "Dozer Mask",
["bm_msk_bobblehead_dozer_desc"] = "\"Senpai Beni Fark Etti!!! :3\"$NL;$NL;Normalde korkutucu olan Bulldozer yüz plakasının komik bir çeşidini hazırlayan topluluk üyesi Far2close’a çok teşekkürler.$NL;$NL;Bu maske yalnızca çevrim içi OVERKILL ürün mağazasından satın alınan PAYDAY 2 DOZER BOBBLEHEAD ile gelen kodla alınabilir.",
["bm_msk_bodhi"] = "Bodhi",
["bm_msk_bodhi_begins"] = "Bodhi Begins",
["bm_msk_bodhi_begins_desc"] = "İkonik Bodhi maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin görünüşünü hiç beğenmedin mi? İşte tarihi değiştirme fırsatın.",
["bm_msk_bodhi_desc"] = "Maskeler; tanrılara, ilahi olana ve benliğin tanrısallaşmasının peşindeki insanlara ilişkin ruhani geleneklerde hep kullanıldı. Bodhi’nin maskesi arkasındaki adamı yansıtır. Güçlü, kurnaz, kararlı ve kendine hâkim.",
["bm_msk_bonnie"] = "Bonnie",
["bm_msk_bonnie_begins"] = "Bonnie Begins",
["bm_msk_bonnie_begins_desc"] = "İkonik Bonnie maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin görünüşünü hiç beğenmedin mi? İşte tarihi değiştirme fırsatın.",
["bm_msk_bonnie_desc"] = "İnsanlığa İskoçya kadar katkı sunmuş pek az ulus var. Bilimden sanata, mutfağa her alanda bu kutsanmış diyarın insanları özgürce ve cömertçe verir. Bonnie, bu maskeyle eğilimi tersine çevirmeye kararlı.",
["bm_msk_boombox"] = "Boom Box",
["bm_msk_boombox_desc"] = "Broşüre göre Alesso’nun Boom Box’ında \"Havanı söndürecek pil yok, dangalakların ritmini duymasını önleyen ses yalıtımı var, polislerin yüzüne vurmasını engelleyen tam yüz zırhı var.\"",
["bm_msk_borsuk"] = "Borsuk",
["bm_msk_borsuk_desc"] = "Dünya çapında soyguncu olmak, silahı eline almaktan fazlasını ister. Eğitim, kondisyon ve normalin çok ötesine geçmeye adanmış bir odak gerekir. Böyle soyguncular neredeyse mutanttır; azgın savaşın içine dalıp hep muzaffer çıkarlar.",
["bm_msk_boss"] = "Shady Business",
["bm_msk_boss_desc"] = "Takımın varsa burun köpründen sallanacak uyumlu göz koruması da lazım, değil mi? Clowns ile Saints’in birleşen havalılığı kozmik bir çelişki yaratıp bütün evreni içe çökertebilir. (Yalnız ortalığı Aldstone’a temizletme, tamam mı?)",
["bm_msk_boss_gold"] = "Golden Draped Visor",
["bm_msk_boss_gold_desc"] = "Som altından maske takmaya ne denir? İddialı bir gösteri denir, işte o kadar.",
["bm_msk_boss_silver"] = "Sterling Draped Visor",
["bm_msk_boss_silver_desc"] = "Ayna gibi parlak, gümüş gibi de ağır olan bu maske bütün dikkatleri üzerine çekecek.",
["bm_msk_brainiack"] = "The Brainiac",
["bm_msk_brainiack_desc"] = "Bu, kafasında çok şey olan birinin maskesi.$NL;$NL;Bu maskeyi takmak, suçlar ve nasıl işlendikleri hakkında daha fazla öğrenmeye yönelik aşırı, neredeyse patlayıcı bir arzu uyandırır.",
["bm_msk_brazil_baby"] = "Brazil Baby",
["bm_msk_brazil_baby_desc"] = "GAGA? GAGA! GOGO! Boo! GAGAGA? GAGA GOGO GAGAGA? GAGA? GAGA! GAGAGA? GAGA GAGAGA?$NL;$NL;GAGAGA? GAGAGAGOGO? Boo! BOOO! Gagagaga boo gaga.",
["bm_msk_brutal"] = "Road Rage",
["bm_msk_brutal_desc"] = "Bu miğfer motosiklet çetesinin en tepesindeki adama ayrılmıştır. Kardeşlerinden saygı ve otorite ister. Savaş vakti geldiğinde gururla takar, en önde sürersin.",
["bm_msk_buha"] = "The Rage",
["bm_msk_buha_desc"] = "Muhtemelen gördüğün en öfkeli palyaço maskelerinden biri.$NL;$NL;Wolf’un maskesini neredeyse utandırıyor.$NL;$NL;Neredeyse.",
["bm_msk_bullet"] = "The Bullet",
["bm_msk_bullet_desc"] = "Güçlü bir ateşli silahla yüzünden vurulmaktan mı endişelisin?$NL;$NL;Bir Bulldozer, Cloaker ve Shield’ın aynı anda seni ezmesinden mi korkuyorsun?$NL;$NL;Bu maskeyi takmak sana yardım etmez ama yere şık bir şekilde düşersin. The Bullet, şu anda yakınınızdaki karaborsalarda!",
["bm_msk_bullskull"] = "Desert Skull",
["bm_msk_bullskull_desc"] = "Issız kanyonlarda, düşüncelerinden başka yoldaşın olmadan sendeleyerek ilerlerken en son görmek isteyeceğin şey, senden önce geçenlerin kurumuş kemikleridir. Bir anda o düşünceler çığlığa dönüşür.",
["bm_msk_buluc"] = "Undead Peacock",
["bm_msk_buluc_desc"] = "Başına en akıl almaz derecede iğrenç suratı takan kazanır.",
["bm_msk_bush"] = "The 43rd",
["bm_msk_bush_desc"] = "Siyasetçi, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etti.$NL;$NL;Kelimelerin ustası olduğuna şüphe yok.$NL;$NL;43. başkan, tarihin en sevilmeyen başkanlarından biriydi. Suçlular arasında ise hâlâ son derece popüler.",
["bm_msk_butcher"] = "The Butcher from Hell",
["bm_msk_butcher_desc"] = "Doğudan gelen deli kasap hakkında pek çok söylenti var. Birine göre, domuz kesmekten o kadar zevk alan bir adammış ki zamanla onlara benzemeye başlamış.$NL;$NL;Cehennem kadar sıcak bir kasaphanede çalışırken derisi kabarcıklar ve kesiklerle bozulmuş. İnsanlar içeriden çığlıklar geldiğini anlatıyor... Hem de sadece domuz çığlıkları değil.",
["bm_msk_cantus"] = "Cantus",
["bm_msk_cantus_desc"] = "İster otobüste ol ister yönetim kurulu odasında; Alesso kulaklarını ilahi melodilerle doldururken dünyaya uygun bir yüz göstermek önemlidir. Karşınızda Cantus: müziğin ve şarkının meleği. Ruhun kanatlansın!",
["bm_msk_card_jack"] = "Jack of Cards",
["bm_msk_card_jack_desc"] = "Maskeye dönüşmüş bir klasik. Standart 52 kartlık deste, günümüzde en çok oynanan iskambil destesidir. Acemi de olsan profesyonel de olsan bu yüzü büyük olasılıkla tanırsın. Tam bir poker suratı maskesi.",
["bm_msk_card_joker"] = "Joker of Cards",
["bm_msk_card_joker_desc"] = "Maskeye dönüşmüş bir klasik. Standart 52 kartlık deste, günümüzde en çok oynanan iskambil destesidir. Acemi de olsan profesyonel de olsan bu yüzü büyük olasılıkla tanırsın. Tam bir poker suratı maskesi.",
["bm_msk_card_king"] = "King of Cards",
["bm_msk_card_king_desc"] = "Maskeye dönüşmüş bir klasik. Standart 52 kartlık deste, günümüzde en çok oynanan iskambil destesidir. Acemi de olsan profesyonel de olsan bu yüzü büyük olasılıkla tanırsın. Tam bir poker suratı maskesi.",
["bm_msk_card_queen"] = "Queen of Cards",
["bm_msk_card_queen_desc"] = "Maskeye dönüşmüş bir klasik. Standart 52 kartlık deste, günümüzde en çok oynanan iskambil destesidir. Acemi de olsan profesyonel de olsan bu yüzü büyük olasılıkla tanırsın. Tam bir poker suratı maskesi.",
["bm_msk_carnotaurus"] = "Alfred",
["bm_msk_carnotaurus_desc"] = "Alfred the Carnotaurus, yaşayıp ortalıkta dolaşırken çok hızlı bir dinozordu. Kendine özgü boynuzları ve kaslı boynu onu diğer dinozorlardan ayırıyordu. Büyük başı ve darbe emen boynuzları sayesinde, tarih öncesinin en büyük aletinin kimde olduğunu göstermek için diğer dinozorlara kafa atmakta özellikle ustaydı.",
["bm_msk_cctp_mnk"] = "Cyber Monkey",
["bm_msk_cctp_mnk_desc"] = "Beton ormanında soygun yapma ihtiyacı duyduğunda.",
["bm_msk_cctp_mnt"] = "Robo Mantis",
["bm_msk_cctp_mnt_desc"] = "Diğer bütün yapay zekâ birimlerine karış.",
["bm_msk_cctp_tgr"] = "Electro Tiger",
["bm_msk_cctp_tgr_desc"] = "Polis peşine düştüğünde 100000 voltla kükre.",
["bm_msk_cctp_vpr"] = "Viper Cyberjack",
["bm_msk_cctp_vpr_desc"] = "Tehdit altında kaldığında süzülüp kaç ya da öldürmek için ısır.",
["bm_msk_chains"] = "Chains",
["bm_msk_chains_clean"] = "Chains Begins",
["bm_msk_chains_clean_desc"] = "Bu, ikonik Chains maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_chains_desc"] = "Chains’in maskesi.",
["bm_msk_chains_glow"] = "Mega Chains",
["bm_msk_chains_glow_desc"] = "Mega Chains maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_champion_dallas"] = "The Champ",
["bm_msk_champion_dallas_desc"] = "Bu, Champ maskesi. Dallas’ın kötü bir gününden esinlendi. Ne kadar kötü mü? Profesyonel bir boksörün karşısında on üç raunt yumruk yediğini düşün. Şişmiş kaş, kırık burun, patlamış dudak, morarmış göz, ezikler, beyin sarsıntısı, çıkık çene; ne ararsan bu maskede var. Evet, Dallas için gerçekten kötü bir gün.",
["bm_msk_character_locked"] = "Karakterin Maskesi",
["bm_msk_character_locked_desc"] = "Bu maske yuvasını kuşandığında tercih ettiğin karakterin maskesini takarsın.",
["bm_msk_cheat_error"] = "HİLELİ MASKE!",
["bm_msk_chef_hat"] = "The Chef",
["bm_msk_chef_hat_desc"] = "İster yol kenarındaki lokantada köfte çeviren bir aşçı ol, ister masası 1000 $ olan bir mekânda zehirli balık doğrayan bir itamae; bu şapka tek bir şey söyler: Şef sensin.",
["bm_msk_chico"] = "Scarface",
["bm_msk_chico_begins"] = "Scarface Begins",
["bm_msk_chico_begins_desc"] = "Bu, ikonik Scarface maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_chico_desc"] = "Scarface, ABD’ye iki boş el ve kötü bir tavırdan başka bir şeyle gelmedi. Kalbindeki karanlığa ancak suç dehasının parlaklığı denk düşüyordu. Maskesi, iz bırakmaya başlarken ardında bıraktığı kan iziyle birlikte bu hikâyeyi anlatıyor.",
["bm_msk_chrodome"] = "Chrome Dome",
["bm_msk_chrodome_desc"] = "Kaskını bu kadar parlak, bu kadar lekesiz tutmanın bir sebebi var. Patlattığın arabalardaki bombaları böyle çok daha güzel yansıtıyor.",
["bm_msk_churchill"] = "British Bulldog",
["bm_msk_churchill_desc"] = "Siyasetçi, ödül sahibi, pek çok madalyanın sahibi ve Amerika Birleşik Devletleri’nin ilk fahri vatandaşı. Bazıları kusurlu bir karakteri olduğunu söyleyip şöyle derdi: \"İnsanlar bir adama aynı anda bu ölçüde hayranlık ve nefret duymamıştı; böylesi zıt uçlar aynı insanda hiç birleşmemişti.\"",
["bm_msk_clinton"] = "The 42nd",
["bm_msk_clinton_desc"] = "Siyasetçi, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etti.$NL;$NL;Kadınların gözdesi olduğuna şüphe yok.$NL;$NL;42. başkan, tarihin en barışçıl başkanlarından biriydi. Suçlular arasında ise hâlâ son derece popüler.",
["bm_msk_cloth_commander"] = "Commander Crime",
["bm_msk_cloth_commander_desc"] = "Commander Crime, OVERKILL Comics’in çizgi romanlarında görünen Amerikalı kurgusal bir süper kötü ve suç ağı C.R.I.M.E.’ın yüce lideridir.$NL;$NL;Karakteri, artık dünyaca ünlü yazar, editör, sanatçı ve profesyonel badminton oyuncusu Max Elmberg Sjöholm yarattı.$NL;$NL;Commander Crime ilk kez The Amazing Career Criminals: The Payday Gang gets a C.R.I.M.E. offer they can't refuse! adlı eserde göründü.",
["bm_msk_clown_56"] = "The Starved",
["bm_msk_clown_56_desc"] = "Bu maskenin korkunç bir görünümü, kemikli bir yüz yapısı ve kurumuş derisi var.$NL;$NL;İnsana kâbus gördüren türden bir maske.",
["bm_msk_clowncry"] = "The Crybaby",
["bm_msk_clowncry_desc"] = "Ağlayan bir palyaçodan daha acıklı bir şey var mı?$NL;$NL;Belki de korkunç maskeli bir suçlunun bağırışlarıyla yere yatan, ağlayan siviller.$NL;$NL;Ya da kasası boş bir banka müdürü.",
["bm_msk_cmo_01"] = "Retro Dallas",
["bm_msk_cmo_01_desc"] = "İyi bir taktik oyunu, büyük soygundan önce hazırlanmanın en iyi yoludur. Dallas stratejik düşüncesini, zafer için birlik ve kaynak yönetmek gereken zor, hesaplı bir oyunla harekete geçirmeyi tercih eder.",
["bm_msk_cmo_02"] = "Retro Hoxton",
["bm_msk_cmo_02_desc"] = "Yoğun suç faaliyetlerinden sonra zihni çalıştıran mantık bulmacaları çözmek, gevşemek için harika bir yoldur. Hoxton, verilen ipuçlarıyla bir sorunu kavrayıp adım adım çözebildiği oyunları sever.",
["bm_msk_cmo_03"] = "Retro Wolf",
["bm_msk_cmo_03_desc"] = "Şiddet dolu oyunlar Wolf’u soygun havasına sokar. Kan, vahşet ve katliam ne kadar fazlaysa o kadar iyi. Tepkini ve hızını sınayan oyunları tercih eder. Neredeyse sonsuz düşman sürüsüne karşı hayatta kalmak için her saniyenin önemli olduğu oyunları.",
["bm_msk_cmo_04"] = "Retro Chains",
["bm_msk_cmo_04_desc"] = "Oyuncular arasında yoğun durumları canlandıran dövüş ve nişancı oyunları, işler arasında becerilerini keskin tutmak için harikadır. Chains, durumsal farkındalığı geliştiren ve becerikli oyunu çatışmada üstünlükle ödüllendiren oyunları sever.",
["bm_msk_cmt_01"] = "Alces",
["bm_msk_cmt_01_desc"] = "Bu etkileyici boynuzlarla her soygunu sendeleye sendeleye aşabilen efsanevi Thomoose gibi, avken avcıya dönüş.",
["bm_msk_cmt_02"] = "Canis Lupus",
["bm_msk_cmt_02_desc"] = "Bu maskeyi tak, banka kasalarını üfleyerek yık ve bütün küçük domuzların ödünü kopar.",
["bm_msk_cmt_03"] = "Felis Lynx",
["bm_msk_cmt_03_desc"] = "Asla bir kediyle avının, bir soyguncuyla ganimetinin arasına girme!",
["bm_msk_cmt_04"] = "Ursus Maritimus",
["bm_msk_cmt_04_desc"] = "Bu görkemli yüz örtüsünü takıp kudretli bir kükremeyle küresel ısınmaya karşı savaş.",
["bm_msk_combusto"] = "Firestarter",
["bm_msk_combusto_desc"] = "Bu palyaço eskiden bir piroteknik ustasıydı; kimsenin aşamadığı bir ateş üfleme gösterisi vardı. Pek bilinmeyen ateş üfleyen palyaçolar camiasındaki rakipleri başarısından hoşnut değildi... Kokteyline bir şey kattılar.$NL;$NL;Yüzünde üçüncü derece yanıklar, gözlerinde kötücül bir bakışla ateşe ateşle karşılık verip diğer palyaçoları yaktı. Ama orada durmadı; içindeki alevli nefret fazla parlaktı. Şimdi dünyayı ateşe vermek istiyor.",
["bm_msk_concert_female"] = "Female Concert Goer",
["bm_msk_concert_female_desc"] = "Alesso konserinin coşkusuyla kaynayan girdabına inerken en iyi yüzünü taksan iyi olur. The Female Concert Goer ifadesiz ve kopuktur; çünkü müzikten başka hiçbir şey önemli değildir.",
["bm_msk_concert_male"] = "Male Concert Goer",
["bm_msk_concert_male_desc"] = "Batik tişörtler 70’lerde kaldı. Çakmak kaldırma modası 80’lerde bitti. Düdükler ve ışıklı çubuklar 90’larda geride bırakıldı; 00’lerden ise ne kadar az bahsetsek o kadar iyi. Günümüz konser müdavimi ise maskeyi tercih ediyor.",
["bm_msk_conquest"] = "Conquest",
["bm_msk_conquest_desc"] = "Mahşerin ilk atlısının kimliği ve tam olarak neyi temsil ettiği bugün bile hararetle tartışılıyor. Kimileri ona Fetih der, kimileri Christ’ın kendisi olduğunu söyler, kimileriyse Antichrist olduğunu iddia eder.",
["bm_msk_corey"] = "Corey",
["bm_msk_corey_desc"] = "Savanın en lezzetli öğle yemeğiysen hayatta kalmak için hızlı, çevik ve kurnaz olmalısın. Corey bunların hepsi. Zebralar ayrıca barışçıl, uysal ve otoburdur. Corey bunların hiçbiri.",
["bm_msk_crazy_lion"] = "Mad Lion",
["bm_msk_crazy_lion_desc"] = "Aslan başı şeklinde korkunç bir maske.$NL;$NL;Bu maske hakkında pek az şey biliniyor. Aslanlara hastalıklı bir hayranlık besleyen çılgın bir Balkan bilim insanının yaptığı söyleniyor. Bu maskenin güzelliğini yalnızca o görebiliyordu.$NL;$NL;Maskeyi sana iyiliğini isteyen biri verdi.",
["bm_msk_croupier_hat"] = "Wheeler Dealer",
["bm_msk_croupier_hat_desc"] = "Göz alıcı neon 80’ler görünümüne hava kat! Bu nane yeşili başlıklar, yoğun ışık kaynaklarının gözleri yormasını önlemek için 19. yüzyıldan beri kullanılıyor. Kokain çekmiş kumarbazlar ve gonzo gazeteciler krupiye şapkasını herkesin ilgi odağına taşıdı. Sahil partileri, plajda güzelleri tavlamak, yakındaki golf kulübünün 18. deliğinde sözleşme imzalamak ve genel olarak seksenlik biri gibi görünmek için de idealler.",
["bm_msk_crowgoblin"] = "Crow Goblin",
["bm_msk_crowgoblin_desc"] = "Çok uzun süre Crow Goblin’in gerçek kimliğini kimse bilmedi. Yirmi yıl sonra öğrendiler ama tatmin olmayınca o kişinin sahtekâr falan olduğunu söylediler. Gerçek Crow Goblin başkasıydı.$NL;$NL;Gerisiyle seni sıkmak istemem ama maske hoş görünüyor, değil mi? Mor bir şapkası var; belki de kapüşon, bilmiyorum. Havalı bir sırıtışı, yüzü boyunca dikilmiş birkaç ipi var. Yine de maskenin arkasında kimin saklandığını merak ediyorum.",
["bm_msk_cthulhu"] = "Cthulhu",
["bm_msk_cthulhu_desc"] = "Korkunç görünümlü bir maske; dehşetin ta kendisi.$NL;$NL;Kötücül yaratıkların pek çok adı olduğu söylenir. Bu yaratığın Tulu, Clulu, Clooloo, Cthulu, Cthullu, C'thulhu, Cighulu, Cathulu, C'thlu ve daha nice adla bilinmesi bundan olsa gerek.$NL;$NL;Kısmen insan, kısmen ahtapot, kısmen ejderha; insanlığın bildiği en büyük kötülüklerden biri.",
["bm_msk_cursed_crown"] = "The Cursed One",
["bm_msk_cursed_crown_desc"] = "Adı efsanelerde kayboldu. Bir kral da olabilir, kudretli bir büyücü de. Ama en büyükleri bile Diamond’ın karşısında yıkılır.",
["bm_msk_daft"] = "Android",
["bm_msk_daft_desc"] = "Gerçekten kopuk ve duygusuz olanlara Android maskesini sunuyoruz. Hafif alaşımlar, krom kaplama ve çok havalı LED ışıklar bu maskeyi hem banka işine hem dans pistine hazır kılıyor. Ne yazık ki altı milyon dili akıcı konuşmanı sağlamıyor.",
["bm_msk_dallas"] = "Dallas",
["bm_msk_dallas_clean"] = "Dallas Begins",
["bm_msk_dallas_clean_desc"] = "Bu, ikonik Dallas maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_dallas_desc"] = "Herkesin korktuğu maske.",
["bm_msk_dallas_glow"] = "Mega Dallas",
["bm_msk_dallas_glow_desc"] = "Mega Dallas maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_damned"] = "Floating Guy",
["bm_msk_damned_desc"] = "Koridorda ilerlerken bu korkutucu ama biraz da yavaş adamı görüyorsun. Uğursuzca havada süzülüyor. Tehdit mi, yoksa sadece biraz dolanıyor mu, anlamak zor. Derken bir patlama sessizliği bozuyor ve sen artık yoksun. O yüzden Floating Guy’la bir dahaki karşılaşmanda hazırlıklı gel, onu hafife alma.",
["bm_msk_daredev"] = "Daredevil",
["bm_msk_daredev_desc"] = "Kusursuz bir an. Havada asılısın; motosiklet rampası arkanda, Grand Canyon’ın karşı kıyısı her saniye yaklaşıyor. Yere sağlam mı ineceksin, yoksa ölümüne mi düşeceksin? Bu soru aklından bile geçmiyor. Şu anda, belki hayatında ilk kez... Gerçekten yaşıyorsun.",
["bm_msk_dawg"] = "Dawg",
["bm_msk_dawg_desc"] = "Ne maske. Çok gizlenme. Pek soyguncu.",
["bm_msk_dawn_of_the_dead"] = "The Undead",
["bm_msk_dawn_of_the_dead_desc"] = "Yaşayan ölü, ölmüş olmasına rağmen bir şekilde hâlâ yaşıyormuş gibi davranan bir varlıktır.$NL;$NL;Gizemli yollarla yaratılmıştır; zombi de olabilir, vampir de.$NL;$NL;Banka soyacaksan bunu yaparken neden insanların ödünü de koparmayasın?",
["bm_msk_day_of_the_dead"] = "Calaca",
["bm_msk_day_of_the_dead_desc"] = "Meksika’daki Ölüler Günü festivaliyle bağlantılı bir iskelet maskesi.$NL;$NL;Kökeni Aztek tasvirlerine kadar götürülse de kimse tam emin değil.$NL;$NL;Calaca’yı takmak, etrafındaki ölümlerde neşe bulmaktır. Başkalarının ölümü sevinçli bir olay olmalı!",
["bm_msk_dbd_00"] = "Blister Head",
["bm_msk_dbd_00_desc"] = "Kabarcıklarla kaplı bu yaratık, gerçek dehşetin vücut bulmuş hâli. Çocukluk korkularının hepsi akıl almaz, korkunç bir şeyin içine dökülmüş. Asıl soru, artık mermiye ihtiyacın olup olmayacağı.",
["bm_msk_dbd_01"] = "The Clawer",
["bm_msk_dbd_01_desc"] = "Ayın parlak olduğu kasvetli gecelerde The Clawer’ın suyun derinliklerinden çıkışına tanık olabilirsin. Taze et ister, açlığı dinene kadar durmaz. The Clawer, kamp ateşinde gençlerin anlattığı şehir efsanelerinden biridir; tam da The Clawer saldırmadan önce. Sonra derinlere döner. Midesi yeniden guruldayana kadar uykuya yatar.",
["bm_msk_dbd_02"] = "Feeder",
["bm_msk_dbd_02_desc"] = "Feeder çenesini tek bir amaç için yerinden çıkardı: Bütün bir insan kalbini yutabilmek. Bu yüzden dişleriyle dili işe yaramıyor; çiğnemek önemli değil. Gece dolaşırken onu ayakta tutacak güçlü kalpleri olan gençler arıyor. O yüzden göğsü yarılmış bir ceset görürsen kaç.",
["bm_msk_dbd_03"] = "Dendron",
["bm_msk_dbd_03_desc"] = "Karanlık orman, yaşın ne olursa olsun herkesi korkutur. İçindekilerden, gölgelerde pusuda bekleyenlerden korkarsın. Ama ağaçların kendisini pek düşünmezsin. Dendron’ı hiç düşünmezsin. Düşündüğündeyse çok geçtir. Dendron acımadan saldırır. O yüzden ağaçların arkasındakinden değil, ağaçlardan kork.",
["bm_msk_dbd_04"] = "The Killer",
["bm_msk_dbd_04_desc"] = "Zırdeli katillerin bile paraya ihtiyacı var. Gerçek bu. O yüzden bazen gençleri biçmeye ara verip kanlı palayı asmak zorundasın. Ama öldürmenin pek çok yolu var, bir hobi de çok önemli. Unutma, polisler de kanar.",
["bm_msk_de_gaulle"] = "The Constable",
["bm_msk_de_gaulle_desc"] = "Constable, 1940-1969 arasındaki dönemin büyük bölümünde Fransa’nın baskın askerî ve siyasi lideriydi. Hükümetinin 1940’ta Alman işgalcilerle yaptığı ateşkesi kabul etmeyerek Londra’da üs kurdu. Kendisini Fransa’nın vücut bulmuş hâli ilan edip Özgür Fransa hareketini başlattı. Savaş sırasında özellikle Afrika’daki denizaşırı sömürgeleri birleştirdi, direnişi yurt dışından örgütledi ve İngilizlerle Amerikalılardan tam tanınma almak için mücadele etti.",
["bm_msk_death_rider"] = "Death",
["bm_msk_death_rider_desc"] = "Mahşerin dördüncü ve son atlısı Ölüm’ün ta kendisidir. Ölüm nereye giderse gitsin, Hades de çenelerini ardına kadar açmış, Ölüm’ün katlettiği kurbanların ruhlarını yutmaya hazır hâlde peşinden gelirdi.",
["bm_msk_deltaforce"] = "Alpha Force",
["bm_msk_deltaforce_desc"] = "Alayla Alpha Force diye anılan 4th Domestic Operation Group-force Enforcers-Alpha (4th DOGE-A), ABD Ordusu’nun Joint Common Operations Command bünyesindeki bir birliğidir. İtibarları pek iyi değil; giderek daha az saygı duyulan bir kuvvete dönüştüler.$NL;$NL;Muhtemelen üyelerinden biri senden kaçarken bu miğferi düşürdü.",
["bm_msk_demon"] = "The Horned Beast",
["bm_msk_demon_desc"] = "Uçurumdan gelen bir yaratık.$NL;$NL;Aslan gövdeli, ayı ayaklı ve leopar ağızlı.$NL;$NL;Bu yaratık veya maskeyi kimin tasarladığı hakkında başka pek bir şey bilinmiyor.",
["bm_msk_demonictender"] = "Kenneth",
["bm_msk_demonictender_desc"] = "İblis başı şeklinde korkunç bir maske.$NL;$NL;Adı dışında hakkında pek bir şey bilinmiyor: Kenneth.$NL;$NL;Şimdi bu intikamcı ruh, insanlığa bir kez daha musallat olmak için dünyaya döndü.",
["bm_msk_destroyer"] = "Demonshank",
["bm_msk_destroyer_desc"] = "Savaşçı ruhu kendiliğinden ortaya çıkmaz. Doğuştan gelen bir şey değildir. Çelik gibi ateşte dövülür. Savaşın ocağında çekiçlenir; su verilir, parlatılır, bilenir. Bu maske, savaşçı ruhun doğuşunu kutlar: Ocakta doğan çeliğin kanatlanışını.",
["bm_msk_devilhorn"] = "Mephistopheles",
["bm_msk_devilhorn_desc"] = "Aldatıcı pek çok ad taşıdı, pek çok şekle girdi. Zamanın başından beri gölgelerden fısıldayıp ruhlarımızı yozlaştırdı, bizi anlatılamaz eylemlere sürükledi. Parmağını kıpırdatmadan yıkım getirebilir... Ama bu biraz uzaktan iş yapmak oluyor, değil mi? Bazen ihtiyar Satan, Dünya’da kocaman bir iblis olarak belirip koşturmak ve bir şeyler çalmak ister. Çok mu şey istiyor?",
["bm_msk_devourer"] = "Devourer",
["bm_msk_devourer_desc"] = "Denizlerin altında hüküm süren Great Old Ones’dan büyük ölçüde esinlenilmiş bu maske, eli kanlı bir tarikata yapılan baskında bulunduktan sonra tutulduğu polis deposundan çıkarıldı. O canavarca görüntüsü, karanlıkta hangi varlıkların pusuya yattığını düşündürüyor.",
["bm_msk_dgm"] = "Golden Dallas",
["bm_msk_dgm_desc"] = "PAYDAY’in tek bir günde en çok oynanan işbirliği oyunu olduğu 10 Haziran 2017’yi anmak için. Saatte yaklaşık 221 bin soyguncu birlikte, şık bir şekilde banka soyuyordu. Böylece tüm zamanların bir günde en çok oynanan oyunları arasında İlk 5’e girdik. PAYDAY tarihe altın harflerle adını yazdırıyor. Dallas memnun.",
["bm_msk_dillinger_death_mask"] = "The Dillinger Death Mask",
["bm_msk_dillinger_death_mask_desc"] = "John Herbert Dillinger ünlü bir Amerikalı banka soyguncusuydu.$NL;$NL;Çetesi iki düzine banka, hatta dört polis karakolu soydu.$NL;$NL;Dillinger iki kez hapisten kaçtı ve Büyük Buhran dönemi ABD’sinin en belalı heriflerinden biri olarak tanındı.",
["bm_msk_divided"] = "Trickster Demon",
["bm_msk_divided_desc"] = "The Trickster Demon, kaos yaratıp ortalığı karıştırarak beslenen muzip bir varlıktır. Pek korkutucu görünmeyebilir ama o sırıtışa aldanma; onun \"eğlence\" anlayışı seninkiyle benimkinden çok farklı. Bu konuda bana güven.",
["bm_msk_dnm"] = "The Normal Skull",
["bm_msk_dnm_desc"] = "İnsan kafatası tuhaf bir şey. Hem sade hem güzel. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var.$NL;$NL;Bütün soygunları Normal zorlukta bitirdin mi? Sen nesin, gangster falan mı? Belki de bu maske sana yakışır.",
["bm_msk_doctor"] = "The Doctor",
["bm_msk_doctor_desc"] = "Genellikle hastane ve ambulanslarla ilişkilendirilen, ağızla burnu kapatan bir maske. Hapşırma veya öksürmeyle saçılan bakteri dolu tükürük ve mukusu tutarak takan kişinin havadan bulaşan virüsleri yaymasını önler. Hem doktorlar hem de hastalar takar; o yüzden kendine sormalısın: Hasta olan ben miyim, sağlıklı olan mı? Hastalık mıyım, çare mi?$NL;$NL;Her durumda ateş mevsimi geldi ve tek reçete ölü Bulldozer’lar.",
["bm_msk_dodhat"] = "Telaraña",
["bm_msk_dodhat_desc"] = "Hayatın, \"efsane\" denen duvar halısına titizlikle dokunmuş karmaşık hikâyelerden ve anlatı iplerinden oluşuyor. Sen gittikten çok sonra taklitçilerin ağa yakalanmış sinekler gibi mirasına takılacak. Gölgenden kaçmaya çalışacaklar ve gölgen hepsini yutacak.",
["bm_msk_dragan"] = "Dragan",
["bm_msk_dragan_begins"] = "Dragan Begins",
["bm_msk_dragan_begins_desc"] = "Bu, Dragan’ın ikonik maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_dragan_desc"] = "Dragan’ınki gibi bir geçmişe sahip birinin suç dünyasında büyüklük peşinde olması şaşırtıcı değil.$NL;$NL;Maskesi onun pek çok özelliğini yansıtıyor. İlk ekibin bazı maskelerine açıkça benzeyen yanları, sızıp uyum sağlayabilme becerisini anlatıyor. Diğer ayrıntılarsa dinmeyen acımasızlığını gösteriyor.$NL;$NL;Alnındaki Hırvat damaları hem kendisine hem de düşmanlarına onun sıradan bir Batılı sokak serserisi olmadığını hatırlatıyor.",
["bm_msk_dripper"] = "The Dripper",
["bm_msk_dripper_desc"] = "The Dripper, büyük bir sıvı kütlesinin zerreciklere ayrılmasıyla yapılmış. Pürüzsüz yüzeyi korunurken bir şekilde sert bir malzemeye dönüşmüş.$NL;$NL;Ona bakan herkes başka şeyler görüyor.$NL;$NL;Sen ne görüyorsun?",
["bm_msk_eagle"] = "Chuck",
["bm_msk_eagle_desc"] = "Chuck the Eagle doğru, iyi ve dürüst olan her şeyi temsil eder.$NL;$NL;Ünlü bir dövüş sanatları ustası, Alaska dağlarında karate yaparken bu dev kartalı buldu.$NL;$NL;Saatlerce dövüştüler ama sonunda dövüş sanatları ustası kazandı. Başını alıp maske yaptı ve ona kendi adını verdi.",
["bm_msk_ecp_female"] = "Hila",
["bm_msk_ecp_female_begins"] = "Hila Begins",
["bm_msk_ecp_female_begins_desc"] = "Bu, ikonik Hila maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_ecp_female_desc"] = "Bu maske sanki muzip bir kötülük yayıyor. Ona bakan çoğu kişinin içine anında bir huzursuzluk çöküyor; banka soyarken de tam böyle bir şeye ihtiyacın var!",
["bm_msk_ecp_male"] = "Ethan",
["bm_msk_ecp_male_begins"] = "Ethan Begins",
["bm_msk_ecp_male_begins_desc"] = "Bu, Ethan’ın maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_ecp_male_desc"] = "Bu maske, onu takan adamın tam tersine güç ve kaba kuvvet saçıyor. Palyaçoya özgü hüzün ile gönülsüz öfkeyi eşit ölçüde taşıyarak, biraz istemeye istemeye soygunculuğu seçmiş birinin ruh hâlini kusursuzca yansıtıyor.",
["bm_msk_eggian"] = "Eggian",
["bm_msk_eggian_desc"] = "Xenogogs’da bu yaratıklar, o sahnede Troy Templeton’ın kıçını parçalayarak çıktıklarında korkunun ta kendisiydi.",
["bm_msk_eighthgrin"] = "The Burning 8th",
["bm_msk_eighthgrin_desc"] = "Yıl dönümleri özeldir; bazıları daha da özel. Kaos ve Soygun Tanrıları (yani Payday Gang) görkemli bir saygı gösterisinden azını istemez. Bu yüzden sadakatini gösterebileceğin bu alevli palyaço çehresini sunuyoruz.",
["bm_msk_elegantteeth"] = "Frayed Harvest",
["bm_msk_elegantteeth_desc"] = "Başkalarının ektiğini biçer, yalnızca istediğini alırsın. Asil ama sade ve vahşi bu maske ihtiyaçlarını karşılar.",
["bm_msk_elfhat"] = "Green Elf",
["bm_msk_elfhat_desc"] = "Kimya diploması olan bir sosyopat Green Elf, Kuzey Kutbu’nun zehirler ve sinir toksinleri uzmanıdır.",
["bm_msk_elfhat_red"] = "Red Elf",
["bm_msk_elfhat_red_desc"] = "Santa’nın Noel Milisi’nde bir asker olan Red Elf, düşmanlarının kanında yıkanmayı sever. Sen sevmez miydin?",
["bm_msk_elfhat_violet"] = "Purple Elf",
["bm_msk_elfhat_violet_desc"] = "Purple Elf aslında çok rahat bir adamdır. Evet, insan kurban ediyor da olabilir etmiyor da, bir ölü dirilticisidir ama onun dışında çok iyidir.",
["bm_msk_elfhat_yellow"] = "Yellow Elf",
["bm_msk_elfhat_yellow_desc"] = "Neşeli mizacının ardında Yellow Elf, bu dünyadaki Yaramazları yakıp bitirene kadar dinlenmeyecek öfkeli bir kundakçıdır.",
["bm_msk_eng_01"] = "The Bullet",
["bm_msk_eng_01_desc"] = "Sonsuz mühimmatlı Blasphemy kılıcıyla The Bullet, bütün yüreğiyle savaşırken tam gücünü açığa çıkarır.",
["bm_msk_eng_02"] = "The Robot",
["bm_msk_eng_02_desc"] = "The Robot, killbot ordusunun onurlu bir üyesiydi. Efendisi EMP-R0R, insan direnişinin liderini öldürmesini emrettiğinde protokole uymadı ve insanlığı yok edemedi.",
["bm_msk_eng_03"] = "The Cultist",
["bm_msk_eng_03_desc"] = "Hep \"2 Numara\" diye anılan The Cultist, yoluna çıkan herkese meydan okur. Dart Gun kuşanmış bu rakibi hafife almamak gerekir!",
["bm_msk_eng_04"] = "The Marine",
["bm_msk_eng_04_desc"] = "The Marine, bir deneyin ters gidip tesise Boyutlararası Dehşet saldığı sırada Primerdyne R&D’de görevli bir muhafızdı. Kimileri herkesi ölüme terk ettiğini söylerken kimileri de onu herkesi kurtaran bir kahraman olarak alkışlıyor!",
["bm_msk_evil"] = "Black Death",
["bm_msk_evil_desc"] = "Bob Robertson bir mor madde fabrikasında çalışıyordu. Mor madde fabrikası eskiydi, onarılması gerekiyordu. Bob bunu amirlerine söyledi ama onu dinlemediler. Bob da doğru dürüst çalışmayıp işletim sisteminde hazır gelen oyunları oynamayı sürdürdü. Bir gün erkenden çıkarken mor madde dolu bir tankta çatlaklar oluşmaya başladı. Tam yanından geçerken tank patladı ve Bob mor maddeye bulandı.$NL;$NL;Hastaneden çıktığında artık bir süper kötüydü. O günden beri yüzü mor.",
["bm_msk_fable_cat"] = "The Cat",
["bm_msk_fable_cat_desc"] = "Bir kedi kadar çevik, onun kadar da şanslı olarak her soyguna cesaret eder, her savunmayı aşarsın. İşler sarpa sardığında hep sıyrılır, dört ayak üstüne düşersin. Dokuz canını harcamanın daha iyi bir yolu yok; sen soğukkanlı bir katilsin, herkes de biliyor.",
["bm_msk_fable_fox"] = "The Fox",
["bm_msk_fable_fox_desc"] = "The Fox: yırtıcıların en kurnazı, en sinsisi. Hiçbir kilit seni dışarıda tutamaz, hiçbir savunma planı zekâna ve hilelerine dayanamaz. İstediğini alırsın; herkes bunu kimin yaptığını, hatta gerçekten olup olmadığını düşünüp durur.",
["bm_msk_fable_hare"] = "The Hare",
["bm_msk_fable_hare_desc"] = "Mart Tavşanı gibi deli. O çılgın sarı gözlerine bakarken parayı hemen verseler iyi olur. Sonra parayı al, kaç. Bir tavşanı kimse geçemez.",
["bm_msk_fable_mouse"] = "The Mouse",
["bm_msk_fable_mouse_desc"] = "Fare kadar sessizce girip çıkarsın, kimse farkına varmaz. Seni görseler bile böyle küçük bir yaratıktan böyle bir kötülüğü kim bekler? Ama evet, bunu yapabilirsin; hepsini.",
["bm_msk_falcon"] = "The Falcon",
["bm_msk_falcon_desc"] = "Hayat yalnızca hız ve koşmaktan ibaret değil! Hızlı bir kazayla geçim kaynağı yok olunca New Rush City’nin gerçekten hak ettiği kahramana dönüştü. Falcon, SpeedRunner’ı indirip şehri geri almaya ant içiyor. Çıldırmış dünyadaki tek aklı başında kişi Falcon mı, yoksa tavuk kostümlü bir adam mı?",
["bm_msk_famine"] = "Famine",
["bm_msk_famine_desc"] = "Kıyametin üçüncü atlısı Kıtlığın vücut bulmuş hâlidir. Öyle güçlüdür ki onu görenleri açlıktan ölüme sürükler.",
["bm_msk_fancy_goat"] = "Slick Goat",
["bm_msk_fancy_goat_desc"] = "Penguen, hayvanlar âleminin en havalı soyguncusudur. Her şeyi bilen tavırlarla dolaşır, acele etmez; istediğini istediği zaman alır, kimseyi umursamaz. Bu maskeyi takıp patronun kim olduğunu herkese göster.",
["bm_msk_fatboy"] = "Fatboy",
["bm_msk_fatboy_desc"] = "Bu dolgun yanaklı, pembe, sağlıklı yüz; Amerika’daki sinema lobilerinde bulunan kızarmış hamurla şekerin o harika, sihirli simyasını temsil ediyor.",
["bm_msk_fdm"] = "The Fedora",
["bm_msk_fdm_desc"] = "Fötr şapka, modanın ve zarafetin zirvesi. Çocuklarla yetişkin erkekleri ayıran çizgi. Bu klasik başlığı hak ettiği gurur ve kararlılıkla taşı. Çağlar boyunca fötr takmış milyonlarca beyefendinin ve gangsterin mirasını, geleneğini hisset.",
["bm_msk_female_ecp"] = "Hila",
["bm_msk_female_ecp_desc"] = "Bu maske sanki muzip bir kötülük yayıyor. Ona bakan çoğu kişinin içine anında bir huzursuzluk çöküyor; banka soyarken de tam böyle bir şeye ihtiyacın var!",
["bm_msk_finger"] = "The Griefer",
["bm_msk_finger_desc"] = "The Griefer, çok eski çağlarda bu dünyada yaşadığı bilinen efsanevi bir yaratıktır. Köylerde ve kasabalarda sıradan insanların peşine düşüp onları bilerek rahatsız eder, beklenmedik yollarla avlardı. The Griefer bu yaptıklarından zevk alıyordu. Kralın adamları sonunda onu bulup yok edene kadar huzuru tehdit etti.",
["bm_msk_firedemon"] = "Graug",
["bm_msk_firedemon_desc"] = "Efsanevi Graug’un başı. Kararmış demir zırha bağlı, ateşten ve tüten karanlıktan yapılmış dev bir varlık. İnsan biçimli ama boynuzlu, yüzü de acımasız bir iblis gibi. Bedeni Cehennem’den de sıcak bir fırın hararetiyle yanıyor. En iyi şarkıların hepsini biliyor.",
["bm_msk_firemask"] = "Firefighter's Helmet",
["bm_msk_firemask_desc"] = "Ekip, polis teşkilatına pek saygı göstermiyor olabilir ama arkalarında bıraktıkları yanan enkazları temizleyen kadınlara ve erkeklere büyük saygı duyuyor. Bu maske onların çabalarına bir saygı duruşu.",
["bm_msk_flapcapban"] = "Bad Cabbie",
["bm_msk_flapcapban_desc"] = "Bir anda, aptalları taşıyarak para kazanmaktan bıktığına karar veriyorsun. Şehrin sakin bir yerindesin; arka koltuğunda zengin bir pislik oturuyor. Cebinde rahat bin dolar nakit vardır. Seni durduracak kimse yok. Torpido gözünde saklı bir 9 mm olduğunu hatırlıyorsun. Bir ara sokağa gir ve taksi ücretini tahsil et.",
["bm_msk_flm"] = "PNV - BriteNite",
["bm_msk_flm_desc"] = "Bin birinci gecede ışık yoktu. Ama gereği de yoktu; efsaneler, her şeyi görmesini sağlayan bir çehre takmış dik başlı bir hayduttan söz eder.$NL;$NL;Ateş Modu düğmesini basılı tutarak Gece Görüşü Modunu etkinleştir.",
["bm_msk_foxfurhat"] = "Kitsune Kari",
["bm_msk_foxfurhat_desc"] = "Doğayla bağını koparmamak önemli; o zaman neden bir parçasını yanında taşımayasın? Gerçekten tilki avlamıyor olabilirsin ama ganimet peşinde olduğun kesin.",
["bm_msk_frank"] = "Frank",
["bm_msk_frank_desc"] = "Frank bir canavar ama sanılanın aksine hassas, duygusal bir yaratık. Tek amacı hayatını başka bir canavarla paylaşmak.$NL;$NL;Ama \"doğduğu\" andan itibaren, kendi yaratıcısının bile onun yanında durmaya katlanamadığını fark etti. Bunu anlayınca Frank banka soyguncusu olmaya karar verdi. Son.",
["bm_msk_franklin"] = "The First American",
["bm_msk_franklin_desc"] = "Dünyaca ünlü bir hezârfen, yazar, matbaacı, siyaset kuramcısı, posta müdürü, bilim insanı, mucit, yurttaş hakları savunucusu, devlet adamı, diplomat ve Kurucu Baba.$NL;$NL;\"İlk Amerikalı\" unvanına sahip ve 100 $ banknotun üzerindeki yüz.$NL;$NL;Suçlular arasında hâlâ son derece popüler.",
["bm_msk_funguy"] = "Funny Guy",
["bm_msk_funguy_desc"] = "Sana bir fıkra anlattığında gül. Katıla katıla gül, uzun uzun gül, ciğerlerinde hava kalmayana kadar gül, sonra gülmeye devam et. Çünkü durursan sinirlenir. Sinirlenince acıkır. Acıkınca da... Eh, fıkranın sonunu tahmin edebilirsin.",
["bm_msk_gagball"] = "The Gagball",
["bm_msk_gagball_desc"] = "Yüzüne bir ağız topu takıp itaatkâr tarafına bir yürüyüş yap.$NL;$NL;İnsanlar bunları pek çok nedenle takar; biri de bağlama içeren rol oyunlarıdır. Ama her zaman öyle olması gerekmez; belli ki ağız topları banka soygunlarında da kullanılabiliyor.",
["bm_msk_gage_blade"] = "The Gage Blade",
["bm_msk_gage_blade_desc"] = "The Gage Blade, Gage’in en sevdiği balistik yüz maskelerinden biridir. Kafan patlamadan önce yüzünü bir iki 9 mm mermiden korur.$NL;$NL;Bu maske olmasa Gage bugün olduğu harika insan olamazdı.",
["bm_msk_galax"] = "Professor Wrath",
["bm_msk_galax_desc"] = "Milhouse Anderson tehlikeli kimyasal atıklarla uğraştığı bir kimya tesisinde çalışıyordu. Arkadaşları, şaka olsun diye onu tehlikeli kimyasal atıkların tutulduğu odaya kilitlemenin iyi fikir olduğunu düşündü. Bilmedikleri şey, tehlikeli kimyasal atıkların tehlikeli olduğuydu. Saatlerce kilitli kalan Milhouse, yüksek düzeyde radyasyona ve başka kötü şeylere maruz kaldı.$NL;$NL;Sonunda çıkardıklarında bir süper kötüye dönüşmüştü. O günden beri çok öfkeli.",
["bm_msk_gasmask"] = "The Gas Mask",
["bm_msk_gasmask_desc"] = "Gaz maskesi eski çağların savaşlarına ait görünebilir ama gazın hâlâ kullanılabildiği şehir savaş alanında hayati bir ekipmandır. Ayrıca havalı, hırıltılı bir nefes sesi verir.",
["bm_msk_gcm"] = "Golden Chains",
["bm_msk_gcm_desc"] = "Dört yıl oldu. Dört yıl sıkı çalışma, pişirilen metamfetamin, atılan kurşunlar ve taşınan ganimet. Ama daha yeni başlıyoruz. Biraz nostalji de hissediyoruz. Washington’a gelip buradaki ilk soygunumuzu yapalı dört yıl oldu; artık profesyoneliz. Birinin doğum günüyse ona hediye almalısın. Bu yüzden Chains’in maskesini sıcak, göz kamaştıran 24 ayar altınla kapladık. İyi ki doğdun PAYDAY 2!",
["bm_msk_gentgla_brown"] = "Agent Brown",
["bm_msk_gentgla_brown_desc"] = "The Agency daha yumuşak bir dokunuş istediğinde Agent Brown’ı gönderir. Sorgudan önce sigara ikram eden türden bir adam. İnsan ilişkileri harika, mizahı kuvvetli. Seni öyle güldürür ki tabancasını karnına dayayana kadar fark etmezsin.",
["bm_msk_gentgla_dark"] = "Agent Black",
["bm_msk_gentgla_dark_desc"] = "Harika, Agent Black geliyor. Bu adam tam bir manyak. Elektrotla işkence, piyano teliyle boğma; hepsi onun işi. The Agency onu ancak ceset sayısı artık önemini yitirdiğinde salar. Yine de yaşlılara karşı inanılmaz tatlıdır. İnsanlar karmaşık galiba.",
["bm_msk_ggac"] = "The One Down Skull",
["bm_msk_ggac_desc"] = "İşte Harbinger geldi! İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta beyinde bunun için özel bir bölge bile var. Bu kesinlikle insan kafatası değil; bir katliam iblisine ait.$NL;$NL;Göğe bakın; cennetten ateş yağıyor, ardından erimiş altın geliyor. Toprak, soyguncu olarak büyüklüğünü aydınlatan, parıldayan, muhteşem bir metal örtüyle kaplanıyor. Çıta her yükseldiğinde meydan okumayı kabul ediyorsun; yine öyle yaptın. OVERKILL ofisinde bir taht yapılıyor. Böylece önüne ne atarsak atalım yenilmeyen o ilahi becerilerinin önünde eğilip tapınabileceğiz.",
["bm_msk_ghm"] = "Golden Houston",
["bm_msk_ghm_desc"] = "İşte geldik; hesaplaşma zamanı. Soyguncu ailemiz, sınırını henüz görmediğimiz bir güce karşı. Tek bir şey biliyorum: Ya buradan birlikte çıkacağız ya da denerken öleceğiz. Biz Palyaçolarız, hırsızlığın lanet tanrılarıyız ve kendi kurallarımızla oynarız. O yüzden sırada ne olursa olsun altın bir ihtişamla parlamaya hazırız.",
["bm_msk_ghost"] = "The Spectre",
["bm_msk_ghost_desc"] = "Bu Ghost maskesi gelecekten gelmiş gibi görünüyor; belki de gerçekten öyledir.$NL;$NL;Karbon fiber ve genetik mühendisliğiyle üretilmiş örümcek ipeğinden yapılmış tam baş koruması. Seni üst düzey bir Moto GP sürücüsü bile sanabilirler.$NL;$NL;Yapacakları son hata olur.$NL;$NL;Bu maske, Kötü Şöhret ağacı ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin. Ancak desen, renk veya malzeme ile bunları birleştirmek için ödediğin özelleştirme ücreti kaybolur.",
["bm_msk_ghx"] = "Golden Hoxton",
["bm_msk_ghx_desc"] = "İlk kez maske taktığım anı hatırlıyorum. Gerçekten yedi yıl önce miydi? Bir şeyi uzun süre yaptığında eninde sonunda bir yol ayrımına gelirsin. Bu işte ya bir silahın namlusuna ya da tatlı hayata bakıyorsundur. Herkes seçimini yapmalı. Herkes bu seçim uğruna neyi riske atacağına karar vermeli. PAYDAY için bu hep ya hep ya hiç oldu!",
["bm_msk_gladiator_helmet"] = "Murmillo Galea Helmet",
["bm_msk_gladiator_helmet_desc"] = "Gladyatörler, antik Roma’da tek görevi halka korkunç şiddet gösterileriyle eğlence sunmak olan acımasız bir sınıftı. Yüksek sorguçlu bu miğfer tarzı balığa benzer. Kılıç ve kule kalkanıyla dövüşen ağır gladyatör sınıfı Murmillo tarafından takılırdı. Roma ateş tanrısı Vulcan’ı simgeler, gücü ve onuru temsil ederler.",
["bm_msk_goat"] = "Dolph",
["bm_msk_goat_desc"] = "Dolph the Goat doğal gücü ve taşı temsil eder.$NL;$NL;İsveç’in en kuzeyindeki bir dağ mağarasında bir grup maceracı tarafından bulundu.$NL;$NL;Efsaneye göre gök gürültüsü tanrısı Thor’un, iki keçinin çektiği bir arabası vardı. Ama bu maskenin o efsaneyle muhtemelen ilgisi yok. Öyle olsa çılgınlık olurdu.",
["bm_msk_goat_goat"] = "Goat Goat",
["bm_msk_goat_goat_desc"] = "Keçi hayvanlar âleminde pek saygı görmez. Diğer hayvanlar sık sık onunla dalga geçer ama bu tam da işine yarar. Bu aptal maskeyi takmak sana da aynı avantajı sağlayabilir; polisler seni hafife alır.",
["bm_msk_goggles"] = "Cloaker-san",
["bm_msk_goggles_desc"] = "Sızma görevlerinde özel eğitimli ajanlar kullanan tek devlet Amerikan hükümeti değil. Japonya’nın Anbu adında kendi birliği var. Bu maske yalnızca bir prototip olsa da onların kullandığına çok benziyor.$NL;$NL;Ateş Modu düğmesini basılı tutarak Gece Görüşü Modunu etkinleştir.",
["bm_msk_grant"] = "The 18th",
["bm_msk_grant_desc"] = "Asker, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etti.$NL;$NL;Bir koruyucu ve savaşçı; hem de büyük bir koruyucu ve savaşçı.$NL;$NL;18. başkan, tarihin en sevilmeyen başkanlarından biriydi. Suçlular arasında ise hâlâ son derece popüler.",
["bm_msk_greedy_the_elf"] = "Greedy The Elf",
["bm_msk_greedy_the_elf_desc"] = "Noel Baba’nın elflerinin işi zor. Sağlık veya diş sigortası yok; Mrs. Claus’un kırbacına katlanıyorlar. Ama en azından şu müthiş şapkaları var. ",
["bm_msk_greek_tragedy"] = "Greek Tragedy",
["bm_msk_greek_tragedy_desc"] = "Bir Yunan tragedyasının bütün bölümlerini simgeleyen maske.$NL;$NL;Eski Yunan’da maskeler, törenlerde ve kutlamalarda tanrılara tapınmak için kullanılırdı.$NL;$NL;Bu maske her soygunu özetler: birinin alarmı çaldırmasına duyulan öfke, kasayı açmanın sevinci ve yakalanmanın trajedisi.",
["bm_msk_grendel"] = "Rad Mutant",
["bm_msk_grendel_desc"] = "Genetik mutasyon evrimimizin anahtarıdır. Tabii evrimimizin yeşil, pullu, katil ve radyasyonlu türden olduğunu varsayarsak.",
["bm_msk_grin"] = "The Grin",
["bm_msk_grin_desc"] = "Bir zamanlar bir adamla kardeşi varmış. Birlikte başarılı bir şirketin sahibiymişler. Bir gün, geçici olarak yalnızca tek müşterileri kalmış. Müşteri korkuya kapılıp ayrılmak istemiş. Ama doğrudan ayrılıp sözleşmeyi bozduğu için ceza ödemek yerine, adamla kardeşinin şirketini aç bırakarak öldürmüş.$NL;$NL;Adamla kardeşi her şeyini kaybetmiş. Bu maskenin, adamın aklını kaçırdığı gün yüzünde beliren ifadenin ta kendisi olduğu söylenir.",
["bm_msk_grizel_clean"] = "Clover Begins",
["bm_msk_grizel_clean_desc"] = "Bu, Clover’ın ikonik maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_groucho"] = "Groucho",
["bm_msk_groucho_desc"] = "Kusursuz kılık değiştirmek; saçını boyamak, irislerini değiştirmek, parmak izlerini yakmak demek değildir. Bazen açıkça tuhaf görünmek insanları bakışlarını kaçıracak, seni umursamayacak kadar rahatsız eder.",
["bm_msk_grv_01"] = "War Balaclava",
["bm_msk_grv_01_desc"] = "Yarım sokak, yarım sokak$NL;Yarım sokak ileri$NL;First World Bank’e$NL;Yürüdü dört soyguncu$NL;İleri Payday Gang$NL;Altına hücum, dediler$NL;First World Bank’e$NL;Yürüdü dört soyguncu",
["bm_msk_grv_02"] = "Matryoshka",
["bm_msk_grv_02_desc"] = "Her şey her zaman göründüğü gibi değildir. Maskenin arkasında bir yüz var, doğru. Peki yüzün arkasında ne var? Belki başka bir yüz. Gerçek kişinin nerede olduğunu nasıl bilirsin? Öze, içindeki benliğe ulaşmadan önce kaç katman kaldırmak gerekir?",
["bm_msk_grv_03"] = "Kokoshnik",
["bm_msk_grv_03_desc"] = "Şan için ince işlenmiş armasıyla bu gösterişli başlık etkileyici olacak. Güzel nakışlarını herkesi kıskandıracak şekilde gururla sergile. Ama alçak kapılara dikkat.",
["bm_msk_grv_04"] = "Red Machine",
["bm_msk_grv_04_desc"] = "Red Machine’i kimse durduramaz! Hızlı, buz gibi ve acımasızdır. Seri hareketler, yıldırım gibi darbeler ve kusursuz taktiklerle rakibini rezil eder; çaresizlik içinde ağlamaya bırakır. Tıpkı Payday Gang gibi.",
["bm_msk_gumbo"] = "Gumbo",
["bm_msk_gumbo_desc"] = "Yutan palyaço olarak bilinen adam hakkında pek az şey biliniyor. Ama uzun süre insanlar kırmızı gözlerinin kıyafetinin parçası olduğunu sandı. Elbette yanılıyorlardı. Artık insanlar, en tecrübeli belalıları bile korkudan titreten kötücül kahkahalı, kırmızı gözlü palyaçodan korkuyor.$NL;$NL;Söylentiye göre sokak aralarında şeytani bir surette bir şey... ya da birini arıyor. Tek bilinen, insanların sonunda öldüğü; mümkün sandığından çok daha ölü olduğu...",
["bm_msk_gwm"] = "Golden Wolf",
["bm_msk_gwm_desc"] = "Beş yıl oldu mu bile? Vay be. Bu hayatta bu kadar uzun süre dayanan pek olmaz. Son bir yıl zordu. Hem de çok zor. Aileyi en savunmasız yerimizden vurdular, polis her gün biraz daha yaklaşıyor ve neredeyse boyumuzu aşan işlere bulaştık. Çoğu soyguncu bu durumda ya ölür ya da ömrünün sonuna kadar hapsi boylardı. Ama biz sıradan üçkâğıtçılar değiliz. Biz PAYDAY’iz. İşi her zaman hakkıyla yaparız. Altını da her zaman alırız.",
["bm_msk_hatgla_dark"] = "Cool Beans Black",
["bm_msk_hatgla_dark_desc"] = "Bu benim berem. Ona benzeyen çok bere var ama bu benim. Berem en iyi dostumdur. Hayatımdır. Hayatıma hâkim olmam gerektiği gibi bereme de hâkim olmalıyım.",
["bm_msk_hatgla_green"] = "Cool Beans Green",
["bm_msk_hatgla_green_desc"] = "Bere takan insanların hiçbir zaman beresiz olmadığını fark ettin mi? On yıldır böyle bir bere takan birini tanıyorum; kafasının tepesini hiç görmedim. Bir kez bile.",
["bm_msk_heat"] = "Hockey Heat",
["bm_msk_heat_desc"] = "Klasik bir hokey maskesi.$NL;$NL;Bir adam bir keresinde bana şöyle demişti...$NL;$NL;\"Tehlikenin köşede olduğunu hissedersen 30 saniyede bırakıp gidemeyeceğin hiçbir şeye bağlanma.\"",
["bm_msk_hectors_helmet"] = "The Hard Hat",
["bm_msk_hectors_helmet_desc"] = "Payday Gang’i gammazlarsan bir misilleme beklemelisin. Ekip, parmak sallayıp sertçe azarlamakla yetinmez. Mermi bekleyebilirsin; hem de bolca. Bu baret, eski usul çevik kuvvet teknolojisi: Önü güçlendirilmiş camlı ağır demir. Delip geçmeye çalışana bol şans.",
["bm_msk_hockey"] = "Hockey Mask",
["bm_msk_hockey_desc"] = "Hokey maskesi, hokey kalecilerinin başlarını yaralanmadan korumak için taktığı maskedir.$NL;$NL;Aynı zamanda yalnızca yüksek kaliteli malzemelerle elde yapılmış ikonik soyguncu maskesidir. Seni paklardan değil, ortalıkta işini yaparken tanınmaktan korur.$NL;$NL;Hani şu çok iyi yaptığın işten. Çalmaktan.",
["bm_msk_hockeynermark"] = "Big Mike",
["bm_msk_hockeynermark_desc"] = "Gerçek bir soyguncu ve savaşçı. İşini bilmek. Asla vazgeçmemek. İşi bitirmek.$NL;Seni selamlıyoruz!",
["bm_msk_hog"] = "The Hog",
["bm_msk_hog_desc"] = "Yeni mesajınız var! *BİP*$NL;$NL;Selamlar, ben OVERKILL’den Almir. Sipariş ettiğiniz maske şimdiye kadar teslim edilmiş olmalı...$NL;$NL;İçinde bir talimat listesi var...$NL;$NL;Dikkatle okuduğunuzdan emin olun!$NL;$NL;Başkalarına zarar vermekten hoşlanır mısınız? Öyleyse bu maske sizin için.",
["bm_msk_homburg"] = "Family Man Dark",
["bm_msk_homburg_desc"] = "Asla aileye karşı taraf tutma.",
["bm_msk_homburg_grey"] = "Family Man Gray",
["bm_msk_homburg_grey_desc"] = "Unutma: Sevdiklerine hep zaman ayır ama işin hakkında soru sormalarına izin verme.",
["bm_msk_horned_king"] = "The Viking",
["bm_msk_horned_king_desc"] = "Vikingler olarak bilinen Cermen kökenli İskandinav denizciler, 8. yüzyıl sonlarından 11. yüzyıl sonlarına kadar yaşamış amansız savaşçılardı. Kudretli baltaları ve boynuzlu miğferleriyle savaşın ortasında gururla dimdik dururlardı. Bu eski savaşçıların ruhunu yakalamak istiyorsan bu maske işini görür.",
["bm_msk_horse"] = "Don Juan",
["bm_msk_horse_desc"] = "Don Juan kapıları vurarak açmayı sever.$NL;$NL;Tak tak. Kim o? Don Juan. Hazırlan.$NL;$NL;Usta ipucu: Hotline Miami’de bu maskeyi kullanırken duvar dibindeki yerde öldürmelerden 2200 puan kazanırsın.",
["bm_msk_hothead"] = "Hothead",
["bm_msk_hothead_desc"] = "Korkunç bir yanardağın öfkesiyle saldırgan Hothead, alev gibi hızıyla geceyi aydınlatır! Çılgın alevini ne tutuşturur? Öfkeli boğa neden kaçar? Soracak kadar yaklaşabilen pek az kişi oldu; tutarlı yanıt alabilenler daha da az!",
["bm_msk_hoxton"] = "Hoxton",
["bm_msk_hoxton_clean"] = "Hoxton Begins",
["bm_msk_hoxton_clean_desc"] = "Bu, ikonik Hoxton maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_hoxton_desc"] = "Hoxton’ın maskesi.",
["bm_msk_hoxton_glow"] = "Mega Hoxton",
["bm_msk_hoxton_glow_desc"] = "Mega Hoxton maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_hunter"] = "Mega Kevin",
["bm_msk_hunter_desc"] = "Kevin için omurgayı söküp gökyüzüne meydan okuyarak haykırmak asla yetmezdi. Her seferinde kafatasını da sikerdi.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_icedeer"] = "Deer of Winters Past",
["bm_msk_icedeer_desc"] = "O geyikli çizgi filmi hatırlıyor musun? Hani annesini öldürdükleri? Evet, yok; bunu takarken kimse sana veya ekibine bulaşmayacak. Aksine, sen onları avlıyor olacaksın.",
["bm_msk_iceskull"] = "PermaFrost",
["bm_msk_iceskull_desc"] = "Mermiler uçuşurken soğukkanlı kalmak hiç bu kadar korkunç görünmemişti. Bu, karşına çıkan herkesin ödünü koparacak. Belki silahından bile daha çok.",
["bm_msk_in31_cyberpunk_max"] = "The Max",
["bm_msk_in31_cyberpunk_max_desc"] = "Bu yüz korumasını takan soyguncudan kusursuz bir saat mekanizması gibi dijital hassasiyet akar. Karşısına dikildiğinde her düşman az da olsa ürperir.",
["bm_msk_in32_goldenbrute"] = "Vanity Gold",
["bm_msk_in32_goldenbrute_desc"] = "Altının varsa onu ne yapacağın hep bir sorudur. Kasaya koyabilir, nakde çevirebilir veya kendini daha belalı göstermek için kullanabilirsin. Elbette sonuncusunun pek çok yolu var. Birisi bu parıldayan yüzü dövmenin de onlardan biri olduğuna karar vermiş. İyi seçim mi? Karar senin.",
["bm_msk_in32_ingoldnito"] = "The Masquerade",
["bm_msk_in32_ingoldnito_desc"] = "Uyduruk dinler ve kadim silahlar, iyi bir hafif makineli silahla veya hiç bozulmayan bir kaçış minibüsüyle boy ölçüşmeyebilir. Ama nesiller boyu aktarılan tekniklerle bir zanaatkârın ince ince işlediği böyle bir maske, bir Bulldozer indirirken kendini gerçekten harika hissetmeni sağlar. Arada bir düzenlenen o tuhaf maskeli balo için de uygundur.",
["bm_msk_in33_overkillpunk"] = "Vile Carny",
["bm_msk_in33_overkillpunk_desc"] = "Hepimiz zaman zaman biraz delirebiliriz. Ama bu maske, ipleri tamamen kopardığın anlar için. Zaten soygunculukta bu seviyeye gelmek için aklını resmen kaçırmış olmalısın!",
["bm_msk_infamy_hood"] = "Kamul",
["bm_msk_infamy_hood_desc"] = "Dünyanın karanlık köşelerinde soygunculardan daha eski, daha iğrenç şeyler var. Biri de Kamul. Çoktan ölmüş bir adamın burada kalmış ruhu mu, gölgeler diyarından geçmiş bir şey mi, bilmiyoruz. Tek bildiğimiz, bu yüze bakıp da anlatacak kadar yaşayanın pek az olduğu.",
["bm_msk_infamy_lurker"] = "Lurker",
["bm_msk_infamy_lurker_desc"] = "Dişler korkutucudur. Büyük dişler daha korkutucudur. Karanlıkta pusuda beklerken birden gıcırdayan devasa, sivri, köpekdişi gibi dişler ise insanın altına etmesine yeter. Bütün bunları düşününce sivilleri hizaya sokmak için daha iyi bir maske aklına geliyor mu?",
["bm_msk_instinct"] = "The Intuition",
["bm_msk_instinct_desc"] = "Bu maske, uzak bir yerden gelen gizemli bir savaşçıya aitti. Sezgileriyle yol bulup dünyadaki kötücül güçleri avlayarak diyarları dolaşırdı. Zindanlara girip karşılaştığı binlerce kötü varlığı öldürdü. Sonunda gelecek neslin yolunu sürdüreceğini bilerek huzur buldu.",
["bm_msk_invader"] = "Invader",
["bm_msk_invader_desc"] = "İnanmak ist... CIZ! Güç senin... CIZ! Uzun yaşa ve... CIZ! Neden hepimiz geçinip gidemiyoruz? Çünkü CIZ! İşte o yüzden.",
["bm_msk_irondoom"] = "Doctor Crime",
["bm_msk_irondoom_desc"] = "Doctor Crime, OVERKILL Comics’in çizgi romanlarında yer alan Amerikalı kurgusal bir süper kötüdür.$NL;$NL;Karakteri yazar ve editör David Goldfarb yarattı, sanatçı Max Elmberg Sjöholm tasarladı.$NL;$NL;İlk kez The Amazing Career Criminals: The Payday Gang meets Doctor Crime! adlı eserde göründü.",
["bm_msk_ja21_biden"] = "The 46th",
["bm_msk_ja21_biden_desc"] = "Siyasetçi, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etmeyi amaçlıyor.$NL;$NL;Keskin görüşleri olan bir adam olduğuna şüphe yok.$NL;$NL;Bazılarına göre 46. başkan kaosa düzen getirecek; bazılarıysa tam tersini düşünüyor. Suçlular arasında ise hâlâ son derece popüler.$NL;$NL;Konsept: Roger Mata.",
["bm_msk_jake"] = "Jake",
["bm_msk_jake_desc"] = "İyi yılan diye bir şey yoktur ama ölümcül yılanlar arasında bile kobra başlı başına beladır. Açılmış boynunu görürsen bu bir tehdittir; kaç. Uzun dişleri fil derisini delebilir; kaç. Zehrinin tek damlası bir Bulldozer’ı devirebilir; yani... Kısacası bunu gördüğünde kaç. Çünkü tükürüyorlar da.",
["bm_msk_jaw"] = "The Jaw",
["bm_msk_jaw_desc"] = "Cam çeneni metal bir çeneyle koru.$NL;$NL;Bundan sonra çenenle çiğneyeceğin tek şey kolluk görevlileri olacak, değil mi?",
["bm_msk_jesterskulls"] = "Decennial Jester",
["bm_msk_jesterskulls_desc"] = "Bunu tak; Payday gang ekibini indirebileceğini sanan her kolluk görevlisinin yüzüne o küçük altın kafataslarını şıngırdat. Sonra burunlarının dibinden ganimet çantalarıyla kaçarken ölüleri uyandıracak kadar yüksek bir kahkaha patlat. Hadi, istediğini biliyorsun. ",
["bm_msk_jfr_01_desc"] = "Sterling’in bereyle armayı zorlu eğitim ve savaşla kazandığını düşünmek hoş olurdu. Ama gerçek şu ki Subaylar Kulübü’nde birkaç genç kısrağı ne kadar etkilediklerini gördü. Dışarı çıkma daveti, birkaç bel altı yumruk ve bayılan bir albayın ardından Sterling’in kendine ait kırmızı bir beresi oldu. Bir de birkaç kısrağı. Şahane!",
["bm_msk_jfr_02"] = "Wolfgang's Cap",
["bm_msk_jfr_02_desc"] = "Bu şapka normal, standart bir M43 arazi şapkası gibi görünebilir. Wolfgang kadar kendini beğenmiş bir adam için böylesine mütevazı bir başlığın tuhaf bir seçim olduğunu da düşünebilirsin. Ama bu şapkanın onun için özel bir anlamı var. Wolfgang’ın gerçekten sevebildiğine şaşırabilirsin. İçine, uğruna savaştığı sevgilisinin fotoğrafı iliştirilmiş.",
["bm_msk_jfr_03"] = "Kurgan's Gas Mask",
["bm_msk_jfr_03_desc"] = "Kurgan gaz maskesini savaş dumanını dışarıda tutmak için takmıyor. Öfke alevlerini içeride tutmak için takıyor. Kendi tarafının ihanetine uğrayan Kurgan, zırhlı alev askerlerinin pususundan zor kurtuldu. Maskenin içinde yalnızca kendi yanmış etinin kokusu var; kimseye güvenmemesini sürekli hatırlatıyor.",
["bm_msk_jfr_04"] = "Rivet's Bandana",
["bm_msk_jfr_04_desc"] = "Rivet Amerikalıdır; Amerikalılar geleneğe değer verir. Başkanlık makamından ülkenin en aşağılık pisliğine kadar gelenek önemlidir. O yüzden bir aptalın suratına silah dayayıp \"Sökül\" diyeceksen tarihini iyi bilsen iyi olur. Jesse James gibi, Billy The Kid gibi, bandana takarsın.",
["bm_msk_jig_01"] = "Garreth",
["bm_msk_jig_01_desc"] = "Uzayda güvenilir bir yoldaşa ihtiyacın var. Uzak gezegenlerdeki dev canavarlardan uzayın kendisine kadar her şey ölümcülken bir müttefik gerekir. Yalnızca kiralık bir silah değil. Senin hayatta kalmanı, başkalarınınsa kalmamasını sağlayan bir dost ve asker. Garreth ekibinde diye sevin. Sürüye çobanlık etmene yardım ediyor diye sevin.",
["bm_msk_jig_02"] = "The Judge",
["bm_msk_jig_02_desc"] = "\"Şu baş belası gençler canları ne isterse yaparak ortalıkta dolaşabileceklerini sanıyor. Anlamıyorlar mı? Benim var olmamın bir nedeni var. Bana itaat edilmeli; hükmüme de sözüme de. Dünyadan kaçıp sadece özgür hissetmek mi? O nasıl bir hayat öyle? Şu sarı kuş icatlarının üzerinde geziniyorlar. Ne imparatorluğa saygı var ne de imparatora. Rezalet!\"",
["bm_msk_jimmy"] = "The White Death",
["bm_msk_jimmy_desc"] = "Jimmy’nin ikinci maske denemesi çok daha iyi sonuç verdi; çünkü Gage’den yardım aldı. Maskede kokain çekmiş Grim Reaper’ın ta kendisi tasvir ediliyor. Jimmy’nin hem çılgın hem ölümcül yanını yansıtıyor, düşmanlarına korku salmayı amaçlıyor.",
["bm_msk_jimmy_duct"] = "Jimmy",
["bm_msk_jimmy_duct_desc"] = "Jimmy, kendine özgü maskesini yapmadan önce pek fazla maske yapmamıştı; belli de oluyor. Maske tasarımı özgür ruhunu, görünüş ve planlama gibi şeyleri umursamayışını yansıtıyor. Jimmy için iyi yeterince iyidir; ayrıntılara takılmaz, hep ilerlemek ister.",
["bm_msk_jiro"] = "Jiro",
["bm_msk_jiro_begins"] = "Jiro Begins",
["bm_msk_jiro_begins_desc"] = "Bu, Jiro’nun ikonik maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_jiro_desc"] = "Japonya gelenekler diyarıdır. Savaşçılar diyarı. Jiro’nun maskesi bunu yansıtır. Maske, Jiro’nun geleneksel Japonya’ya sevgisini anlatırken dişlerini açığa çıkaran hırlayış sarsılmaz kararlılığını temsil eder.",
["bm_msk_joy"] = "Joy",
["bm_msk_joy_begins"] = "Joy Begins",
["bm_msk_joy_begins_desc"] = "Gösterişin ve ışıltının da bir başlangıcı olmalı. Bazen bu başlangıç, tertemiz, soğuk ve harekete hazır, güçlü bir beyaz temeldir.",
["bm_msk_joy_desc"] = "Diskoyu şık bir dönüşle yeniden canlandır. Düşmanların o göz kamaştırıcı suratına bakarken akılları allak bullak olsun.",
["bm_msk_jw_shades"] = "Collateral",
["bm_msk_jw_shades_desc"] = "Bu gözlük, John’un öldürmek için tutulduğu bir meslektaşına aitti.$NL;$NL;Herhangi bir gece gibi başladı. Ama o gece, o gün iş peşinde dolaşan başka bir kiralık katili öldürmesi için sözleşme aldı. John onun beş yere uğrayacağını ve hepsine aynı taksiyle gittiğini biliyordu.$NL;$NL;Sonunda işi kendisi yapmasına bile gerek kalmadı; bulduğunda adam çoktan ölmüştü.",
["bm_msk_kage"] = "Kage",
["bm_msk_kage_desc"] = "Kage maskesinin lanetli olduğu söylenirdi. Osaka’daki bir kabuki tiyatrosundan geliyordu; oyuncu onu takarken sahnede ölüp yere yığılmıştı. Son sözleri \"Hayır, onları öldürmeyeceğim, öldürmeyeceğim\" olmuştu. Efsaneye göre kage maskesinin kana susamışlığı giderilmezse onu takanı öldürür.",
["bm_msk_kangee"] = "Apache Mystic",
["bm_msk_kangee_desc"] = "Beyaz adamın ayak bastığı Batı, gizemli bir diyardı. Kendilerini, topraklarını ve mitolojilerini bu kutsal oymalarla işaretleyen savaşçı uygarlıkların yaşadığı bir diyar.",
["bm_msk_kawaii"] = "Kawaii",
["bm_msk_kawaii_desc"] = "Sevimli, tatlı, şirin, havalı, gözde, çekici, zararsız, masum, kaygısız.$NL;$NL;Bunlar kriminolojide pek kullanılan sözcükler değil.$NL;$NL;Senin sayende artık öyleler.",
["bm_msk_king_of_jesters"] = "King of Jesters",
["bm_msk_king_of_jesters_desc"] = "Parlak renkli giysiler ve alacalı, tuhaf şapkalar giyen soytarıların bu topraklarda hep yeri oldu.$NL;$NL;İster tahta bacaklarla yürüsün, ister ateşle gösteri yapsın, ister şaka anlatsın; tek amaçları kalplerimize neşe yaymaktır.$NL;$NL;Ama şimdi parlama sırası sende. Neden maskeyi takıp biraz neşe yaymayasın?$NL;$NL;Silahını çıkar, misafirlerini soy ve hepsinin büyük bir oyun olduğunu söyle.",
["bm_msk_krampus"] = "Krampus",
["bm_msk_krampus_achievement"] = "Açmak için SANTA’NIN NOEL’İNİ İPTAL ETMEK başarımını tamamla!",
["bm_msk_krampus_desc"] = "Bu yıl yaramaz mıydın? O zaman Krampus’un ziyaretini bekleyebilirsin. Ya da Bain’den telefon.",
["bm_msk_kwm"] = "Rhubarb",
["bm_msk_kwm_desc"] = "Efsanevi maceracımız [MANY GUN] CLOVERAPTOR’a saygıyla; gizemlerin çözücüsü, The Mega Death’i getiren! Bankacı olma hayalini bırakıp kaderiyle yüzleşti ve Cop Wizard ile yardakçıları Law Elementals’ı yendi. Bunu kendi iradesiyle mi yoksa baskıcı Crime Dad’in iradesiyle mi başardı, kim bilir; ama hizmetine sonsuza dek minnettar kalacağız.$NL;$NL;OVERKILL Seni Selamlıyor!",
["bm_msk_lady_butcher"] = "Lady Butcher",
["bm_msk_lady_butcher_desc"] = "The Butcher’a çevresindekiler her \"cadı\", \"fahişe\" veya \"banshee\" dediğinde bir dolar alsaydın, bütün Hırvatistan’ı satın alacak kadar paran olurdu. Etrafındaki alaycı erkekler onun kadın olmasından yakınıyor; suç dünyasındaki baş döndürücü yükselişini gördükçe kendilerini tehdit altında ve huzursuz hissediyordu. Balkanlar’ın, herhangi bir yönden farklı insanlara hoşgörüsüyle tanınmadığını unutma. Hayatının her gününü en acımasız suçlulardan bazılarıyla çalışarak geçirirken ne kadar açık bir erkek şovenizmi ve kadın düşmanlığıyla uğraştığını ancak hayal edebilirsin. Bu maske, hem rakiplerinin hem de ortaklarının onu nasıl gördüğünü gösteriyor. İnsanları korkutuyor. Korkmalılar da.",
["bm_msk_lastlaugh"] = "Gangsta Pranksta",
["bm_msk_lastlaugh_desc"] = "Bu kabuğun altında delilik mi var? Takan kişiyi mi temsil ediyor, yoksa soyguncuların kanuna duyduğu küçümsemenin bir yansıması mı?",
["bm_msk_lcv"] = "Le Castle Vania",
["bm_msk_lcv_desc"] = "Modern, dinamik, kalabalıkları coşturan bir şey. Zarif, akıcı, tepeden tırnağa şık. Hem Le Castle Vania’nın müziği hem de maskesi.",
["bm_msk_leshy"] = "Leshy",
["bm_msk_leshy_desc"] = "Avın tanrısı, yabanın ruhu. Geçmişten gelen bu ilkel maskeyi takıp soygunu kasıp kavur.",
["bm_msk_lincoln"] = "The 16th",
["bm_msk_lincoln_desc"] = "Avukat, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etmeyi amaçlıyordu.$NL;$NL;Akademisyenler ve halk tarafından sürekli tüm zamanların en büyük ABD başkanlarından biri sayılır.$NL;$NL;16. başkan, tarihin en sevilen başkanlarından biridir. Suçlular arasında hâlâ büyük saygı görür.",
["bm_msk_lone"] = "Lone Heister",
["bm_msk_lone_desc"] = "İster katil bir kanun kaçağı ol ister yalnız, dalgın bir korucu; bazen kimliğini saklaman gerekir. Yüzünün üçte birini kapatan ince siyah bir göz maskesinden daha iyi ne olabilir?",
["bm_msk_lycanwulf"] = "Lycanwulf",
["bm_msk_lycanwulf_desc"] = "\"Lycanwulf, Lycanwulf!\" diye bağırdı korkmuş köylüler, Lycanwulf denen bu ucubeyi gördüklerinde. Zavallı insanlar artık canavarın esiriydi; duvarı, tavanı veya anahtarı olmayan, tek kaçışın ölüm olduğu bir hapishanede.",
["bm_msk_mad_mask"] = "Zero 68",
["bm_msk_mad_mask_desc"] = "Son derece popüler Zero 68 animesinden esinlenen bu maske, dizinin siborg ninja kahramanının miğferi örnek alınarak yapıldı.",
["bm_msk_male_ecp"] = "Ethan",
["bm_msk_male_ecp_desc"] = "Bu maske, onu takan adamın tam tersine güç ve kaba kuvvet saçıyor. Palyaçoya özgü hüzün ile gönülsüz öfkeyi eşit ölçüde taşıyarak, biraz istemeye istemeye soygunculuğu seçmiş birinin ruh hâlini kusursuzca yansıtıyor.",
["bm_msk_mandril"] = "John",
["bm_msk_mandril_desc"] = "Mandril maymunu John. Mandriller babunlara, daha da yakın olarak dril maymunlarına akrabadır. Banka soygununda kullanılan matkap değil, maymun olan dril, seni şapşal! John, \"tanımlanamayan maymun çığlığı\" gibi alaycı tek cümlelik laflarıyla tanınan bir maymundur.",
["bm_msk_mantis"] = "Sphodromantis",
["bm_msk_mantis_desc"] = "Bu sevimli küçük dostların yaygın adı \"peygamberdevesi\". Neden mi? Ön bacaklarını dua eder gibi katladıkları duruşlarından geliyor. Ama doğaları yüzünden avcı tarafları daha çok öne çıkar.$NL;$NL;Kısacası yakalayıp yiyebildikleri her şeyi yerler.",
["bm_msk_mason_knight_veteran"] = "Mason Knight Veteran",
["bm_msk_mason_knight_veteran_desc"] = "Masons’ın Knight Veterans üyelerinin miğferi, bu güçlü ve yeni türemiş tarikatın simgesiydi. Köylüler onu görünce Malric’in yeni düzeninin yakında olduğunu bilirdi.",
["bm_msk_mason_vanguard_veteran"] = "Mason Vanguard Veteran",
["bm_msk_mason_vanguard_veteran_desc"] = "Bu miğfer gösterişli bir mezar höyüğünden çıkarıldı. Bu da sahibinin Mason ordusunda saygın olduğunu gösteriyor. Bu büyük savaşçılar Malric’in seçkin birlikleri gibi görünüyor; belki başarısız Tenosian seferinde onunla hizmet ettiler.",
["bm_msk_maui"] = "Maui",
["bm_msk_maui_desc"] = "Gençliğinde Pasifik’in \"Ateş Çemberi\"ni gezen Bodhi şu gerçeği kavradı: Kendini onurlandırmak, mitleri onurlandırmaktır. Aklında kalan mitlerden biri Maui’ninkiydi. Maui de Bodhi gibi insanlığın yılmaz savunucusu, bir düzenbaz ve maceracıydı.",
["bm_msk_maw_01"] = "Omen",
["bm_msk_maw_01_desc"] = "Bu maske antik taştan yapılmış. Önceki sahiplerinin her birinden kalma oymalar ve muazzam güç yayan bir simge taşıyor. Kenarındaki yazının da söylediği gibi, onu takana karşı gelenler için sonun başlangıcıdır.",
["bm_msk_max"] = "Sangres",
["bm_msk_max_begins"] = "Sangres Begins",
["bm_msk_max_begins_desc"] = "Bu, ikonik Sangres maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_max_desc"] = "Kafatası, Sangres’in kariyeri boyunca sadık yoldaşı olan Death. Altın diş, ödenen sikke. Öldürme sayacı tetikçilik geçmişini, kan kırmızısı yakut ise ABD’de peşinde olduğu yeni serveti temsil eder. Sangres’in adı hayatındaki nice kanlı olayı anlatır; o kırmızı kan maskesinde de bulunur.",
["bm_msk_mdm"] = "Mega Death",
["bm_msk_mdm_desc"] = "Death bir son olabilir ama bir başlangıç, kendini aşma ve arınma da olabilir. Mega Death ise Death’in milyon katı güce sahiptir.",
["bm_msk_medusa"] = "Medusa",
["bm_msk_medusa_desc"] = "Çirkin bir çehre, saç yerine yılanlar, taşa çeviren bir bakış ve erkeklere duyulan nefret. Gözleri hâlâ insanı ürpertiyor... Ama bu sadece bir maske, değil mi?",
["bm_msk_mega_alien"] = "Mega Watcher",
["bm_msk_mega_alien_desc"] = "The Watchers, Dünya gezegeninde casusluk yapan bir dünya dışı türdür. Zihinleriyle iletişim kurar; büyük gözleriyle insanlığı izleyip hakkında bilgi toplar ve paylaşırlar. Böylece yaklaşan istilaya hazırlanırlar.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_mega_blade"] = "Mega Gage Blade",
["bm_msk_mega_blade_desc"] = "Orijinal Gage Blade, Gage’in en sevdiği balistik yüz maskelerinden biridir. Mega Gage Blade ile gözde balistik maskesini geliştirmeye karar verdi. Önceden yalnızca işlevseldi; şimdi şık da.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_mega_doctor"] = "Mega Doctor Crime",
["bm_msk_mega_doctor_desc"] = "The Amazing Career Criminals’ın 34. sayısında Doctor Crime’ın öldüğünü sanmıştık ama korkmayın; Doctor geri döndü! Yeni güç zırhı ve şık yeni maskesiyle, habersiz kahramanlarımızdan intikam almaya hazır.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_mega_grin"] = "Mega Grin",
["bm_msk_mega_grin_desc"] = "The Grin bir zamanlar yenilgiyi kabul etmek zorunda kalan bir adamın çöküşünü temsil eden yüzdü. Ama devir değişti; aynı adam şimdi her zamankinden güçlü döndü. Tazelenmiş, kararlı bir amansızlık ve kurnazlıkla dünyaya meydan okumaya hazır. Maske hâlâ bir delinin yüzünü temsil ediyor ama kazanan bir delinin.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_mega_mark"] = "Mega Mark",
["bm_msk_mega_mark_desc"] = "Bu maske, çok uzak bir Doğu diyarında insanlara ve diğer hayvanlara dehşet saçtığı bilinen efsanevi bir ayıdan esinlendi. Hikâyesi suç dünyasında çok popülerdir. O amansız yaratığa benzetilmek, yalnızca en büyük ve en acımasız suçlulara layık büyük bir onur sayılır.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_mega_sydney"] = "Mega Sydney",
["bm_msk_mega_sydney_desc"] = "Mega Sydney maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_megacthulhu"] = "Mega Cthulhu",
["bm_msk_megacthulhu_desc"] = "Bir yerlerde, okyanusun karanlık derinliklerinde efendimiz ve kurtarıcımız Cthulhu yaşar. Bizi dev gazabından esirgeyen ve zihin denetleyen şefkatiyle kutsayan O’na övgüler olsun. Kalamar yemeyin, yoksa sonsuz lanet sizin olur.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_megaskulldia"] = "Nine Hundred Degrees",
["bm_msk_megaskulldia_desc"] = "Blerrie! Görünüşe göre o maskeyi yapmak için kullandığım elmaslara bir tür mistik enerji işlemiş! Geleceğe dair görüntüler falan görüyor musun? Belki tanrısal yeni güçler? Hayır mı? Sadece yanan gözler mi? Eh, yine de havalı görünüyor!",
["bm_msk_metalhead"] = "Metalhead",
["bm_msk_metalhead_desc"] = "Metalhead’in kökeni belirsiz.$NL;$NL;Maskeden çok miğfere benziyor. Dışarı uzanan dikenleri var; süslenip püslenmiş, demirden bir gaz maskesini andırıyor. Ama takanı gazdan veya yakın dövüş silahlarından koruyup korumadığı belirsiz.$NL;$NL;Yine de çok havalı görünüyor.$NL;$NL;Bu maske bir Poetry Jam maskesidir. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_mmh"] = "Mega Duke",
["bm_msk_mmh_desc"] = "Aristotle, Plato, Confucius, Michelangelo, DaVinci, Newton, Galileo... Tarihe sonsuza dek kazınmış sanatçılar ve düşünürler. O tarihin bir yerinde bir soyguncunun yeri de hazır. Özleri burada bir arada; birleşimleri öyle muhteşem ki maskenin yüzeyi onları zar zor içinde tutuyor.",
["bm_msk_mmj"] = "Z.A.M.S Helmet",
["bm_msk_mmj_desc"] = "Klasik ekipman harika olabilir. 200 beygirlik çelik ata binen kahraman bir heyecan avcısının zihniyeti, ilk bakışta belli olmasa da bir soyguncuyla pek çok ortak nokta taşır. Özel yapım bir başlığın estetik değeri bunlardan yalnızca biridir!",
["bm_msk_monkeybiss"] = "Monkey Business",
["bm_msk_monkeybiss_desc"] = "Hayatı o kadar da ciddiye almayan biri takar.$NL;$NL;Çünkü bu bir maymun maskesi.",
["bm_msk_moon"] = "Mask of the Moon",
["bm_msk_moon_desc"] = "Efsaneler, Ay’ı Dünya’ya çarptırmaya çalışacak kadar kötücül bir varlıktan söz eder. Dört maskeli savaşçı tarafından yenilse de varlık kaçıp... bir şeye yerleşmiş. Umarız bir daha dönmez ama unutma: Bazen insan maskeyi takar, bazen de maske insanı.",
["bm_msk_mp2_01"] = "Fluffedup",
["bm_msk_mp2_01_desc"] = "Sevgili Fluffedup’ımız kayıp. 95 yaşında, ailemizin bir parçası. Fluffedup mutlu bir ufaklık; kesinlikle kendini birkaç kez blendere veya çatıdan aşağı atmaya çalışmadı. Onu sonsuza kadar tutmak, hiç bırakmamak istiyoruz. Bu yüzden bize, yaşayıp sevdiği ve kesinlikle nefret etmediği evimize dönmesi çok önemli!",
["bm_msk_mp2_02"] = "Stoibs",
["bm_msk_mp2_02_desc"] = "Stoibs biraz telaşlı ve \"hızlı\". Geçen salı gecesi kaçtı, onu geri alırsak seviniriz. İyi soy kütüğü olan bir çinçilla bulmakta zorlandık. O yüzden yenisiyle baştan başlamak, semiz ve körpe olsun diye mısırla beslemek sıkıcı olacak. Bulursanız Stoibs’in tadını çıkaracağımız akşam yemeğine sizi de çağırırız!",
["bm_msk_mp2_03"] = "Byrne",
["bm_msk_mp2_03_desc"] = "Byrne gitti. O bizim koalamız, \"ev hayvanımız\". Ama geri istemiyoruz. Sıkıcı ve bunaltıcı; tek yaptığı okaliptüs yaprağı yemek. Hem de BÜTÜN gün. Ona dokunmandan, hatta onunla konuşmandan bile hoşlanmıyor. Artık gitti ve öyle kalsın istiyoruz. Bulursanız (sevimsiz bir ev hayvanına benziyor) sizde kalabilir, ne yaparsanız yapın. Bunu sıkıntıdan patlamamak için bir uyarı sayın.",
["bm_msk_mp2_04"] = "Tempy",
["bm_msk_mp2_04_desc"] = "Tempy bizim evcil aslanımız. 2 haftadır kayıp, onu özlüyoruz. Tempy her türlü sevilmeye bayılır; yeter ki biz sevelim. Tempy’yi görürseniz hiçbir şekilde yaklaşmayın. Lütfen nerede gördüğünüzü bize söyleyin. Yakınına gelirseniz sizi parçalar. Bunun dışında çok tatlıdır, güneşte uyumayı sever. Bir de çocukları görmesine izin vermeyin... Sonu iyi bitmiyor.",
["bm_msk_mr_sinister"] = "Blackhearted",
["bm_msk_mr_sinister_desc"] = "Ürkütücü biçimde kötücül ve hain olan bu maskenin, takan kişiyi gizemli şekillerde değiştirdiği söylenir.$NL;$NL;Yeterince uzun süre takıldığında kişinin yüreğini kararttığı, onu karanlık işlere duyduğu arzuyla doldurduğu anlatılır.",
["bm_msk_mrm"] = "Mega Rust",
["bm_msk_mrm_desc"] = "Mega Rust maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_mrs_claus"] = "Mrs. Claus",
["bm_msk_mrs_claus_achievement"] = "Açmak için VLAD'IN KÜÇÜK YARDIMCILARI başarımını tamamla!",
["bm_msk_mrs_claus_desc"] = "Santa aralık göklerinde uçarken birinin evde kalıp elfleri hizaya sokması gerekir. Bunu Claus hanesinin kırbaç şaklatan, puro tüttüren komutanından daha iyi kimse yapamaz.",
["bm_msk_msk_grizel"] = "Clover",
["bm_msk_msk_grizel_desc"] = "Clover’ın maskesi, Clover’ın hem en çok korktuğu hem de en çok nefret ettiği şeyi temsil ediyor: Normal yüzün olarak maske takmak. Ameliyatla küçültülmüş burun, botokslu dudaklar, her şeyi yutan kibir ve kendine hayranlık ifadesi; hepsi korkunun ve zayıflığın, korkunç bir parodiye dönüştürülmüş simgeleri.",
["bm_msk_mts_trol"] = "Lars the Troll",
["bm_msk_mts_trol_desc"] = "Bazıları senden zaten eski çağların trolü veya devi gibi korkuyor olabilir. Öyleyse kalelerinin kasasını boşaltırken neden o role de bürünmeyesin?",
["bm_msk_mummy"] = "The Mummy",
["bm_msk_mummy_desc"] = "Derisi ve organları korunmuş bir mumyanın yüzü. Aşırı soğuğa (buz mumyaları!), düşük neme, havasızlığa veya kimyasallara kasıtlı ya da tesadüfi maruz kalma buna yol açmış olabilir.$NL;$NL;Dünyanın neresinden geldiğini kim bilir? Uzun zamandır korunmuş hâlde, artık dünyaya yeniden çıkmaya hazır.",
["bm_msk_myh"] = "Duke",
["bm_msk_myh_begins"] = "Duke Begins",
["bm_msk_myh_begins_desc"] = "Bu, ikonik Duke maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_myh_desc"] = "Duke kültürlü, erdemli ve taş gibi soğukkanlı bir adamdır. Bu yüzden maskesi, kişiliğini yansıtması için tarihin büyük heykellerinden esinlenerek tasarlanmıştır. Bu maske, her soygunda zarif ve sarsılmaz kalan, incelikli suçun kararlı temsilcisinin zihnine ve kalbine açılan bir penceredir.$NL;$NL;Duke’u çeken şeylerden biri gizem sevgisidir. Kasayı açmadan içinde ne olduğunu, tabloyu çerçevesinden çıkarmadan arkasında ne bulunduğunu asla tam bilemezsin. Payday Gang ile en büyük gizem hemen köşenin ardında olabilir...",
["bm_msk_ninja_hood"] = "Kuro Zukin",
["bm_msk_ninja_hood_desc"] = "Başına bağlanan basit bir kumaş parçası; dilenciyi, çiftçiyi, sıradan insanı, herkesi ninjaya dönüştürebilir. Gölgeler arasında bir gölge, karanlıkta bir hançer. Amansız veya sinsi olabilir; kalabalıktaki herhangi biri olabilir. Yapmaya geldiği işi bitirir, sonra kaybolur.",
["bm_msk_nixon"] = "The 37th",
["bm_msk_nixon_desc"] = "Siyasetçi, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etmeyi amaçlıyordu.$NL;$NL;Kesinlikle bir sahtekâr değildi.$NL;$NL;37. başkan, görevinden istifa eden tek başkandı. Suçlular arasında ise hâlâ son derece popüler.",
["bm_msk_nomegusta"] = "No Me Gusta",
["bm_msk_nomegusta_desc"] = "Banka soyarken kiralık kasadan yalnızca bir tost çıktığında.",
["bm_msk_nun_town"] = "The Nun",
["bm_msk_nun_town_desc"] = "Gerçek bir Katolik rahibe tanımıyorsan Katolik rahibe maskesi korkutucu bir seçim gibi gelmeyebilir. Tanıyorsan da sevecen, büyükanne gibi penguen düşüncesinin ne kadar yersiz olduğunu bilirsin. Bu acımasız kocakarılar kötülüğün ta kendisidir; ellerinin eriştiği her genç popoyu pataklarlar.",
["bm_msk_nutcracker"] = "Hans",
["bm_msk_nutcracker_desc"] = "Hans insanlardan nefret eder, karşısına çıkanın kafatasını kırar. Ama korkutucu görünümünün altında iyi bir çocuktur. Neredeyse kılık değiştirmiş bir prens denebilir. Ona iyi davranırsan seni Tatlılar Ülkesi’ne götürebilir.",
["bm_msk_obama"] = "The 44th",
["bm_msk_obama_desc"] = "Siyasetçi, başkomutan, baba. Bu büyük ulusa 8 yıl hizmet etti. Umut dolu bir adam olduğuna şüphe yok.$NL;$NL;44. başkan, tarihin en iddialı başkanlarından biriydi. Suçlular arasında ise hâlâ son derece popüler.",
["bm_msk_oilbaron"] = "Texas Tea",
["bm_msk_oilbaron_desc"] = "Milyonlarca yıl bekledi.$NL;$NL;Bir zamanlar pek çok şeydi; ölüp toprağa gömülmüş sayısız küçük organizma. Zamanın altında ezilip gezegenin sıcağında pişerek tek bir kara kütleye dönüştüler. Kendi değerinden habersiz, çalkalanan bir sıvı. Adsız bir şey. Bekleyen bir şey.$NL;$NL;Binyıllar dakikalar gibi geçti; sonunda bekleyiş sona erdi. Sağır edici bir uğultu, adsız şeyi Dünya’nın karanlık rahminden fırlattı. Topraktan yukarı, metal bir kulenin içinden geçip bir yanardağ gibi Teksas güneşine doğru püskürdü. Coşkulu alkışlarla, sevinç ve açgözlülük gözyaşlarıyla karşılandı. Hayranlarının üzerine yağarken, sırıtan bir yüz ona adını verdi:$NL;$NL;\"Eh çocuklar, galiba petrol bulduk.\"$NL;",
["bm_msk_old_hoxton"] = "Hoxton Reborn",
["bm_msk_old_hoxton_begins"] = "Hoxton Reborn Begins",
["bm_msk_old_hoxton_begins_desc"] = "Bu, ikonik Hoxton Reborn maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_old_hoxton_desc"] = "Hoxton Reborn, Hoxton’ın hapiste yaptığı maskedir. Payday Gang onsuz devam ederken geçen yıllarda yaşadığı her şeyin simgesidir. Hapishane deneyimlerinin onu nasıl değiştirdiğini kimse bilmiyor; sorulduğunda da konuşmuyor.$NL;$NL;Tek varsayabildiğimiz, sonsuza dek değiştiği ve... başka bir şeye yeniden doğduğu.",
["bm_msk_oliver"] = "Oliver",
["bm_msk_oliver_desc"] = "\"Dünyanın En Büyük Soyguncuları ödülünün adayları.....\"",
["bm_msk_onebelow"] = "The One Below",
["bm_msk_onebelow_desc"] = "Bu baş, karanlık lordların diyarlara hükmettiği, iyi insanların yalnızca ölmek için büyüdüğü eski günlerin su dehşetinden geriye kalan tek şey. Yazın kısa, kışın sonsuz geldiği; One Below’un okyanustan çıkıp yeryüzünde yürüdüğü günlerden.",
["bm_msk_oni"] = "Oni",
["bm_msk_oni_desc"] = "Oni, bir Japon şeytanıdır.$NL;$NL;Keskin pençeli, başından iki boynuz çıkan, çirkin ve devasa, deve benzer yaratıklardır.$NL;$NL;Derileri pek çok renkte olabilir ama en yaygınları kırmızı ve mavidir.",
["bm_msk_optimist_prime"] = "The Optimist",
["bm_msk_optimist_prime_desc"] = "\"Dünyada görmek istediğin değişimin kendisi ol.\"$NL;$NL;The Optimist’in inandığı şey bu.$NL;$NL;Barışçıl bir robot grubunun lideri olarak, olumsuzluk ve yok etme saplantılı rakip robot çeteleriyle savaşmanın sorumluluğu olduğunu düşünüyor. Başlıca silahı, yapıcı akıl yürütme ve tarafsız mantıkla olumlu düşünceyi yaymak.$NL;$NL;Ya da zorla yükseltme yapmak. Bunlar zorunlu.$NL;$NL;Bu maske bir Poetry Jam maskesidir. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_orangutang"] = "Rutger",
["bm_msk_orangutang_desc"] = "Rutger, o lanet orangutan. Ormanda gezerken birden bir orangutanla karşılaşırsan başın belada. İstatistikler, bir orangutanın pompalı tüfekli on serseri kadar tehlikeli olduğunu gösteriyor. Hani sonunda büyük dinozorun çocukları kurtardığı o dinozor filmi var ya? Jenerikten sonra dinozoru kim öldürdü, biliyor musun? Çocuklar. Peki çocukları kim öldürdü? Rutger, o lanet orangutan.",
["bm_msk_oro"] = "Oro",
["bm_msk_oro_desc"] = "Bodhi, Fransız Polinezyası adalarını keşfederken savaş tanrısı Oro’nun takipçileriyle karşılaştı. Genç maceracı, mücadele sanatı kadar güzel zanaat işlerini de takdir eden bu tanrıya hızla hayran oldu.",
["bm_msk_outlandish_a"] = "The Cannula",
["bm_msk_outlandish_a_desc"] = "Bu maske tuhaf malzemelerden yapılmış; elde tutması rahatsız hissettiriyor. Takmasıysa daha da tuhaf.$NL;$NL;Maskeyi takınca kendini bir yabancı, bir dışarlıklı gibi hissediyorsun. Sürekli yer değiştiren, uzak duran, kimsenin tanımasını istemeyen biri.",
["bm_msk_outlandish_b"] = "The Outlander",
["bm_msk_outlandish_b_desc"] = "Hiç ağzın yokken çığlık atmak istediğin oldu mu?$NL;$NL;Bu maskeyi takmış, sana silah doğrultup yere yat diye bağıran bir suçluya bakan bir sivilsen işte böyle hissedeceksin.",
["bm_msk_outlandish_c"] = "The Perfect Stranger",
["bm_msk_outlandish_c_desc"] = "Yabancı diyarlardaki bir yabancının maskesi.$NL;$NL;Böyle maskeler kayıp bir uygarlıkta savaşta askerler tarafından, cenaze törenlerinde ve kötü ruhları kovmak için yapılan şaman ayinlerinde kullanılırdı.",
["bm_msk_owl"] = "Rasmus",
["bm_msk_owl_desc"] = "Rasmus’un sırları fark eden bir gözü var.$NL;$NL;Baykuşlar gece avlanan yırtıcı kuşlardır. Kafataslarına göre iri gözleriyle tanınırlar. Aslında gözlerini hareket ettiremezler; onun yerine başlarını çevirirler ve bunu 270 derece yapabilirler. Bunu bilmiyordun, değil mi?$NL;$NL;\"Seni tanımıyorum!\" \"Benim misafirim değilsin!\"",
["bm_msk_pachy"] = "Pachy",
["bm_msk_pachy_desc"] = "Adı kalın kafalı kertenkele anlamına gelen Pachy the Pachycephalosaurus aslında o kadar da kalın kafalı değildi. Bu adı kendisi seçmedi; diğer dinozorlar, zekâ, ruh ve bilgelik zarlarındaki yüksek sonuçlarını kıskandıkları için ona taktı. Yerel tarih öncesi heceleme yarışmasında ikinci olup cübbe ve büyücü şapkası kazanması da durumu düzeltmedi.",
["bm_msk_pain"] = "Venger",
["bm_msk_pain_desc"] = "League of Darkness’ın çılgın liderinden esinlendi. Bunun bir solunum cihazı mı, ses aygıtı mı olduğu belirsiz. Bazıları, Nemesis’e hem insanüstü güç hem de psikotik öfke veren uyuşturucuları aktarmak için tasarlanmış bir sistem olduğunu düşünüyor.",
["bm_msk_panda"] = "Jean-Claude",
["bm_msk_panda_desc"] = "Jean-Claude the Panda eskiden çok havalıydı, türlü çılgın işte başrol oynardı.$NL;$NL;Ne yazık ki sonra uyuşturucu bağımlısı oldu ve havasını kaybetti. Ama antrenman sayesinde toparlanmayı başardı.$NL;$NL;Son olarak onu iki kamyonla acayip bir şey yaparken görmüş olabilirsin. Manyakça bir şeydi. Görmediysen bir bakmalısın.",
["bm_msk_panther"] = "Brandon",
["bm_msk_panther_desc"] = "Brandon gerçekten çok ama çok hızlı yürümeyi sever.$NL;$NL;Brandon bir panterdir, panterler de büyük kedilerdir. İlginç bir nokta: Yalnızca kaplan, aslan, leopar ve jaguarın anatomisi kükremeye uygundur. Zavallı panter.",
["bm_msk_patton"] = "Old Blood and Guts",
["bm_msk_patton_desc"] = "Afrika harekâtında gördüğüm en cesur adamlardan biri, Tunis’e ilerlerken yoğun ateşin ortasında bir telgraf direğinin tepesindeydi. Durup orada ne halt ettiğini sordum. \"Kabloyu onarıyorum komutanım,\" dedi. \"Şu anda orası biraz sağlıksız değil mi?\" diye sordum. \"Evet komutanım ama bu lanet kablo onarılmalı.\" \"Yolu tarayan şu uçaklar seni rahatsız etmiyor mu?\" diye sordum. \"Hayır komutanım ama siz kesinlikle ediyorsunuz,\" dedi.$NL;$NL;İşte gerçek asker oydu. Gerçek adam. Koşullar ne kadar zor, görevi o an ne kadar önemsiz görünürse görünsün sahip olduğu her şeyi görevine adayan adam.",
["bm_msk_pazuzu"] = "Pazuzu",
["bm_msk_pazuzu_desc"] = "Antik Babil mitolojisine göre Pazuzu, rüzgâr iblislerinin kralıydı. Efsanelerde uzak diyarlarda maceracı gruplarıyla savaşan vahşi, devasa bir yaratık olarak da anlatılır. Hatta bazıları, insan suretinde ölümsüz bir savaşçı olarak yeryüzünde dolaştığını söyler.",
["bm_msk_pbm"] = "Simon",
["bm_msk_pbm_desc"] = "Soyguncu özentisinin biri bir içki dükkânını soymaya kalktı ama kimliğini doğru dürüst gizlemeyi ihmal etti. Bunun yerine oradan son alışverişinde aldığı kâğıt poşeti kullandı! Elbette aptalın kimliği hemen saptandı ve gözaltına alındı. Özgürlüğüyle takas edecek rehinesi olmayınca suç kariyeri kısa kesildi. Yerel haberlere başlık bile olmayan olay, bazı işlerin profesyonellere bırakılmasının en iyisi olduğunu sertçe hatırlatıyor.",
["bm_msk_pig"] = "Aubrey",
["bm_msk_pig_desc"] = "Aubrey gerçek bir silah tutkunudur.$NL;$NL;İri başlı, uzun burunlu Aubrey bir silah ustasıdır; güzel silahlarla öldürmekten daha iyi bir şey bilmez.$NL;$NL;Ama domuzların ciğerleri epey küçüktür, o yüzden Aubrey çok uzağa koşamaz.",
["bm_msk_pim_daisy"] = "Daisy",
["bm_msk_pim_daisy_desc"] = "Ne yaptıklarını ve kime yaptıklarını bilmiyor olabilirlerdi ama bunun önemi yok. Hak ettiklerini, hatta fazlasını aldılar. John geri döndü.",
["bm_msk_pim_dirty_russian"] = "Zashchita",
["bm_msk_pim_dirty_russian_desc"] = "Kafandan vurulmamanın iyi bir yolu kask takmaktır ama yalnızca yüzünü mermilerden ve tanınmaktan korumak istiyorsan bu yeter. Gerçekten kurşungeçirmez gibi mi görünüyor? Sen nesin, korkak mı? Korkunu taşaklarından yakala, bu maskeyle suratına kafa at.",
["bm_msk_pim_hotelier"] = "Hotelier",
["bm_msk_pim_hotelier_desc"] = "The Continental yalnızca suikastçıların sığınağının kurallarına saygı duyanlara hizmet verir. Burası bir tarikat veya gizli cemiyet değil; herkesin para için öldürmeye hazır olduğu ve içerideki herkesin birinin hedef listesinde bulunduğu bir işte gerekliliktir.",
["bm_msk_pim_mustang"] = "Mustang",
["bm_msk_pim_mustang_desc"] = "Kendini araba mı sanıyorsun? Ha? Peki kendini GÜÇLÜ BİR AMERİKAN arabası mı sanıyorsun? Hayır mı? Soygunculuk hızlı ve zarif görünmek değil, öfkeli ve tehlikeli görünmektir. Vın vın, dallamalar!",
["bm_msk_pirate_skull"] = "Pirate Skull",
["bm_msk_pirate_skull_desc"] = "Buccaneers Ahoy!’da bu kılıç sallayan yaşayan ölü soyguncular, yıllarca Karayipler’in hazine dolu kalyonlarına dehşet saçtı. Böylece korsanların sonsuza dek çooook havalı olduğunu kanıtladılar.",
["bm_msk_pitbull"] = "Arnold",
["bm_msk_pitbull_desc"] = "Arnold the Bulldog hep büyük hayalleri olan bir doge’du.$NL;$NL;Çok kas yapmak istedi; yaptı da. Küçük dağ kasabasının en büyük doge’u oldu, öyle ödül aldı.$NL;$NL;Sonra Amerika’ya taşındı, siyasete atıldı, The Dogenator ve The Dogenator II - such judgement adlı birkaç tuhaf doge filminde oynadı.",
["bm_msk_plague"] = "The Plague Doctor",
["bm_msk_plague_desc"] = "Beyin için bir veba doktoru maskesi.$NL;$NL;Bhagavad-Gita’nın sözleriyle: \"Şimdi ben Ölüm oldum, dünyaların yok edicisi.\"$NL;$NL;En azından sanatsal yönlendirme buydu.$NL;$NL;Bu maske, Kötü Şöhret ağacı ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin. Ancak desen, renk veya malzeme ile bunları birleştirmek için ödediğin özelleştirme ücreti kaybolur.",
["bm_msk_pokachu"] = "Electarodent",
["bm_msk_pokachu_desc"] = "Eğitilmemiş Electarodent’i tatlı havuçları kemirirken ya da Alp çayırlarında koşup oynarken bulabilirsin. Ama tam eğitimli bir Electarodent genellikle Bernetti 9’ları kuşanıp Skulldozer’ların yüz siperlerini kemirirken görülür.",
["bm_msk_primtime"] = "Prime Time",
["bm_msk_primtime_desc"] = "BU GECE! Finalistlerimiz Kuantum Maskelerini takıp 21. Yüzyıla dönüyor! Yalnızca o dönemin ilkel silahlarıyla, süre bitmeden olabildiğince çok servet çalmalılar! $NL;$NL;Kim hayatta kalacak? Kim en çok ganimetle dönecek? Kim efsanevi Payday Gang ile el sıkışacak? Bu gece... GELECEĞE SOYGUN’da öğrenin!",
["bm_msk_pumpkin_king"] = "Pumpkin King",
["bm_msk_pumpkin_king_desc"] = "Efsaneye göre Jack adlı bir çocuk, mallarını çaldığı köylülerden kaçarken birden Devil’a çarpmış.$NL;$NL;Jack zeki küçük bir soyguncuymuş; taşıdığı ganimeti paylaşmaya değer olduğuna Devil’ı ikna etmiş. Devil kabul etmiş, ikisi kaçış atlarına koşup uzaklaşmış.",
["bm_msk_punk"] = "The Being",
["bm_msk_punk_desc"] = "Bu maske, tuhaf Dr Rudolf Mastaba’nın deneylerine dayanıyor. Çağdaş bir Prometheus olan doktor, Sanayi Devrimi teknolojisini kullanarak ölüleri diriltmeye çalıştı. Söylentiye göre kısmen başardı da: Ölüler dirildi ama buğdaya, arpaya ve mısıra karşı doymak bilmez bir iştahları vardı.",
["bm_msk_rabbit"] = "Graham",
["bm_msk_rabbit_desc"] = "Graham güneş altında uzun yürüyüşleri sever.$NL;$NL;Tavşanlar, neredeyse her yerde bulunabilen küçük memelilerdir. Olası bir tehditle karşılaştıklarında anında donup kalır ve yere kuvvetle vurarak yuvadakileri uyarırlar.$NL;$NL;Kaçarken pek çok Counter-Strike oyuncusu gibi zikzak çizerek zıplarlar.",
["bm_msk_rage_demon"] = "Flaming Skull",
["bm_msk_rage_demon_desc"] = "Kafatası bir simge olarak ölümü veya faniliği anlatabilir; biz insanlar ona hep hayranlık duyduk. Bu motosiklet kaskını takmak güçlü ve korkutucu görünür.",
["bm_msk_rageface"] = "Rageface",
["bm_msk_rageface_desc"] = "Cloaker tekmesinden sıyrıldın, arkadaşın yedi. Haha.",
["bm_msk_railhat"] = "Highball",
["bm_msk_railhat_desc"] = "Tam yol ileri ekip! Demiryollarını gideceğimiz yere yarın varalım diye yapmadık! Oraya DÜN varmış olmak istiyorum! Çuf çuf, dallamalar!",
["bm_msk_rambo"] = "The Troubled War Veteran",
["bm_msk_rambo_desc"] = "Vietnam Savaşı’nda kaslı bir adam kafayı sıyırıp modern silahlar yerine yay kullanmaya başladı. Sonu iyi bitmedi.",
["bm_msk_ranchcap_emblem"] = "Speedway",
["bm_msk_ranchcap_emblem_desc"] = "Yarış takımının pit ekibinde çok şey öğrenebilirsin. Fırtınanın gözünde şimşek gibi hareket edebilir misin? Motorlar etrafında silah gibi patlarken işini yapabilir misin? Evet mi? O zaman banka soyacak yeteneğe sahipsin.",
["bm_msk_ranchcap_plain"] = "Blood Money",
["bm_msk_ranchcap_plain_desc"] = "Bu şapkada ilk bakışta görünenden fazlası var. Başta iddiasız görünür ama zihnin gerisinde şiddetli bir iz bırakır. Bunca kırmızı... Kanlı bir alamet. Yoluna çıkana Tanrı yardım etsin.",
["bm_msk_ranchcap_texas"] = "Don't Mess With Texas",
["bm_msk_ranchcap_texas_desc"] = "Evin başının olduğu yerdir. Neden herkesten daha iri, daha iyi ve daha belalı olduğunu dünyaya göster. Teksas’a kimsenin bulaşmamasının sebebi sensin.",
["bm_msk_ranger"] = "Heister Sentry",
["bm_msk_ranger_desc"] = "Bu maske baştan ayağa tam bir soygun kıyafetinin parçası olarak tasarlandı. Ama saha testleri, gösterişli spandeks kıyafetin mermiye, bıçağa veya el bombasına karşı koruma sağlamadığını ortaya koydu. Maskeyse hafif, dayanıklı ve şık bulundu. Soygun zamanı!",
["bm_msk_red_hurricane"] = "The Red Bear",
["bm_msk_red_hurricane_desc"] = "\"Sovyet Rusya’da Red Bear seni öldürür.\" Red Bear’ın kim olduğunu kimse tam bilmiyor. Kimileri onun yalnızca bir efsane olduğunu, vatanın ve güçlü olan her şeyin tek bir varlıkta birleşmiş simgesi olduğunu söylüyor. Sadece hikâyeleri biliniyor, tekrar tekrar anlatılıyor. Bir sürü ayıyı öldürüp eve kanlar içinde, kıpkırmızı döndüğü o sefer gibi.",
["bm_msk_richard_begins"] = "Richard Returns Begins",
["bm_msk_richard_begins_desc"] = "Bu, ikonik Richard Returns maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_richard_returns"] = "Richard Returns",
["bm_msk_richard_returns_desc"] = "Bu maske derinlere kök salmış bir psikolojik sorunun yansıması mı? Belki çoklu kişilik bozukluğu? Şizofreni? Bozulmuş bir ruhun travması? Yoksa bunların yansıması değil de doğrudan sebebi mi?",
["bm_msk_richter"] = "Richter",
["bm_msk_richter_desc"] = "Richter da sıçan gibi sessiz bir katildir. En güvenli bankalara ve dairelere, hemen her yere girebilir. İstediğinde fark edilmez ve içeri girdikten sonra veba gibi ölüm saçar. Pişmanlık duymadan öldürür. Kişisel bir mesele değil.",
["bm_msk_robberfly"] = "Asilidae",
["bm_msk_robberfly_desc"] = "Haydut sinek veya katil sinek olarak da bilinen Asilidae, saldırgan avcılık alışkanlıklarıyla tanınan, güçlü yapılı, kıllı sineklerdir. Diğer böceklerle beslenirler; genellikle pusuya yatıp avlarını uçarken yakalarlar.",
["bm_msk_robo_arnold"] = "Robo-Arnold",
["bm_msk_robo_arnold_desc"] = "Exterminator film serisinin zaman yolculuğu yapan ikonik siborg yıldızı. İlk filmde, gelecekteki isyanın liderinin annesini öldürmek için gönderilmişti; kadın, aynı zamanda kendi babası da olan oğlunun bıraktığı çipi çalmadan önce... Geçmişte. \"Dönüşümü bekleyin\" repliğini ifadesiz bir suratla söylemesiyle tanınır.",
["bm_msk_robo_santa"] = "Mechanical Santa",
["bm_msk_robo_santa_achievement"] = "Açmak için Klostrofobi başarımını tamamla!",
["bm_msk_robo_santa_desc"] = "Bu neşeli, bayramlık otomat Santa’nın kalbine sahip. Onu bir kutuda, elf cesetlerinden bir yığının altında, kesik rengeyiği başlarıyla çevrili tutuyor.",
["bm_msk_roman"] = "Hippika",
["bm_msk_roman_desc"] = "En büyük imparatorluktan bir savaşçının soğukkanlı ve asil çelik yüzü, en büyük düşmanla karşılaşıldığında geleneği ve değerleri temsil eder. Crime.net’in bir yüzbaşısı, bu metal sanat eseriyle antik Roma’nın kuvvetine ve kudretine bürünebilir.",
["bm_msk_rooster"] = "Richard",
["bm_msk_rooster_desc"] = "Richard farklı kişiliklerle vakit geçirmeyi ve soru sormayı sever.$NL;$NL;Başkalarına zarar vermekten hoşlanır mısın?$NL;$NL;Telesekreterine kim mesaj bırakıyor?$NL;$NL;Şu anda neredesin?$NL;$NL;Bu konuşmayı neden yapıyoruz?",
["bm_msk_rubber_female"] = "Mrs. Mannequin",
["bm_msk_rubber_female_desc"] = "The Female Mannequin.$NL;$NL;Terzilerin, giysi dikenlerin, sanatçıların, vitrin tasarımcılarının ve artık banka soyguncularının kullandığı eklemli bir bebeğin yüzü.$NL;$NL;Çoğunlukla giysileri sergilemek veya prova etmek için kullanılırlar. Ama ilk yardım, kalp masajı, soluk borusuna tüp takma ve artık banka soygunu öğretiminde canlandırma için de kullanılırlar.",
["bm_msk_rubber_male"] = "Mr. Mannequin",
["bm_msk_rubber_male_desc"] = "The Male Mannequin.$NL;$NL;Terzilerin, giysi dikenlerin, sanatçıların, vitrin tasarımcılarının ve artık banka soyguncularının kullandığı eklemli bir bebeğin yüzü.$NL;$NL;Çoğunlukla giysileri sergilemek veya prova etmek için kullanılırlar. Ama ilk yardım, kalp masajı, soluk borusuna tüp takma ve artık banka soygunu öğretiminde canlandırma için de kullanılırlar.",
["bm_msk_rudeolph"] = "Rudelf",
["bm_msk_rudeolph_desc"] = "Houston bunları Payday ekibinin Noel partisinde, Hoxton \"Tam bir salak gibi görünüyorsun\" diyene kadar taktı. Hox’u boş ver. Noel ruhunu kucakla.",
["bm_msk_rus_hat"] = "Russian Hat",
["bm_msk_rus_hat_desc"] = "Uğuldayan, dondurucu Rus kışı olmasaydı dünya çok farklı olurdu. Napoleon da Hitler de bunu öğrendi. Yanlarına sıcak bir şapka alsalardı tarih çok farklı olabilirdi.",
["bm_msk_rust"] = "Rust",
["bm_msk_rust_begins"] = "Rust Begins",
["bm_msk_rust_begins_desc"] = "Rust’ın ikonik maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin görünüşünü hiç beğenmedin mi? İşte tarihi değiştirme fırsatın.",
["bm_msk_rust_desc"] = "The Devil, Rust’ın hayatının büyük bölümünde peşini bırakmayan bir lakap. Bu yüzden Rust’ın maskesi, alnından uğursuz boynuzlar çıkan sırıtan bir palyaço. Herkese Devil’ın burada olduğunu anlatıyor.",
["bm_msk_rvd_01"] = "The Dons",
["bm_msk_rvd_01_desc"] = "Hem haydutların hem de kahramanların kabul ettiği gerçek zarafet ölümsüzdür.",
["bm_msk_rvd_02"] = "Futuras",
["bm_msk_rvd_02_desc"] = "Minigun kargaşası dondurmanın üstüne koyacak belalı bir kiraz için daha fazla arama.",
["bm_msk_rvd_03"] = "Producers",
["bm_msk_rvd_03_desc"] = "Bu çerçeveler, Ay’a inişin hayal edildiği, bütün hayallerin mümkün olduğu ve herkesin biraz daha şık giyindiği zamanları hatırlatıyor.",
["bm_msk_saloondarklea"] = "El Capitan",
["bm_msk_saloondarklea_desc"] = "Koyu deri, kovboy görünümüne sert bir hava katıyor. Adını aldığı dağ gibi bu şapka da heybetli duruyor; taş gibi bakışın etkiyi artırıyor.",
["bm_msk_saloonlightlea"] = "Open Plain",
["bm_msk_saloonlightlea_desc"] = "Bazen bir klasiğin üstüne çıkamazsın. \"Deh kovboy!\" diyen bir şapka mı istiyorsun? Daha fazla arama.",
["bm_msk_saloonshade"] = "Lone Star",
["bm_msk_saloonshade_desc"] = "Dallas, Houston... Teksas’ın Payday Gang’de derin kökleri var. Tam kararında gösterişli bir şapkayla ailenin bu geçmişini onurlandır. Eyaletin renklerini belirgin ve gururlu taşı.",
["bm_msk_saloonstar"] = "Triggerman",
["bm_msk_saloonstar_desc"] = "Tetik parmağı kaşınan bir keskin nişancısın. Hiç mermi yağmuruna yakalanmadın; çünkü mermi yağmuru SENSİN. Düşmanların şapkandaki o kara yıldızın parladığını görünce topuklamaları gerektiğini anlar. Eski Batı efsanevi silahşorlarla dolu; sen de efsanelerin efsanesisin.",
["bm_msk_samurai"] = "Somen Mempo",
["bm_msk_samurai_desc"] = "Eski Japonya’da samuray savaşçıları, savaşta korunmak ve düşmanlarını korkutmak için somen maskeleri takardı. Demir ve deriden yapılan somen maskeleri büyük kabuto miğferlerine bağlanır, samurayları jigoku’dan gelen iblislere benzetirdi.$NL;$NL;Geçmişte bu korkutucu maskeyi hangi amansız, acımasız savaşçının taktığını kimse bilmiyor. Ama artık bir kez daha savaşa hazır.$NL;$NL;\"Boku no ikari wo osoreru\"",
["bm_msk_santa_drunk"] = "Tipsy Santa",
["bm_msk_santa_drunk_desc"] = "Santa Claus, Saint Nicholas, Father Christmas ve Kris Kringle (?) adlarıyla da bilinen Santa, destansı boyutlarda bir adamdır. Efsanevi, mitolojik, tarihî ve folklorik gibi sözcükler bu adam azmanını en iyi anlatır.$NL;$NL;Bu, Tipsy Santa maskesi. Hani hafif çakırkeyif olduğunda bir şeyler döndüğünü hissedersin ama daha zilzurna olmamışsındır ya. İşte çakırkeyiflik bu.",
["bm_msk_santa_happy"] = "Happy Santa",
["bm_msk_santa_happy_desc"] = "Santa Claus, Saint Nicholas, Father Christmas ve Kris Kringle (?) adlarıyla da bilinen Santa, destansı boyutlarda bir adamdır. Efsanevi, mitolojik, tarihî ve folklorik gibi sözcükler bu adam azmanını en iyi anlatır.$NL;$NL;Bu, Happy Santa maskesi. Kocaman gülümsemesi, kırmızı yanakları ve neşesiyle bunu taktığında en huysuz Bulldozer’ı bile keyifle gülümsetirsin.",
["bm_msk_santa_mad"] = "Furious Santa",
["bm_msk_santa_mad_desc"] = "Santa Claus, Saint Nicholas, Father Christmas ve Kris Kringle (?) adlarıyla da bilinen Santa, destansı boyutlarda bir adamdır. Efsanevi, mitolojik, tarihî ve folklorik gibi sözcükler bu adam azmanını en iyi anlatır.$NL;$NL;Bu, Furious Santa maskesi. Öfkeli internet kullanıcıları ve istedikleri hediyeyi alamayan yaramaz çocuklar takar.",
["bm_msk_santa_surprise"] = "Surprised Santa",
["bm_msk_santa_surprise_desc"] = "Santa Claus, Saint Nicholas, Father Christmas ve Kris Kringle (?) adlarıyla da bilinen Santa, destansı boyutlarda bir adamdır. Efsanevi, mitolojik, tarihî ve folklorik gibi sözcükler bu adam azmanını en iyi anlatır.$NL;$NL;Bu, Surprised Santa maskesi. Neden şaşırmış, kim bilir? Biri kızağını mı çaldı? Rengeyiklerini mi çaldı? Yoksa az önce birinin banka soyduğunu mu gördü?",
["bm_msk_satan"] = "Satan",
["bm_msk_satan_desc"] = "Şeytanın yaptığı en büyük ikinci numara, kocaman boynuzlu ve kırmızı tenli bir iblis olarak resmedilmesiydi. Artık metroda telefonunun hoparlöründen müzik dinleyen kişinin gerçekte kim olduğunu kimse bilmiyor.",
["bm_msk_scarecrow"] = "Mr. Sackcloth",
["bm_msk_scarecrow_desc"] = "Kargaları, serçeleri ve kolluk kuvvetlerini dehşet tarlana girmekten caydır.$NL;$NL;Efsaneye göre uzak diyarlarda her şeyi bilen ama yürüyemeyen bir tanrı yaşarmış. Açgözlü insanlar tanrıyı bulup bilgeliğini kazanabileceklerini düşünerek başını kesmiş.$NL;$NL;Ama bunun yerine dehşetle lanetlenmişler.",
["bm_msk_scm_01"] = "Guardian of Watchers",
["bm_msk_scm_01_desc"] = "Yeraltı dünyasının savaşçı muhafızı, Bast’ın eşi Anubis; zamanın şafağında doğmuş kadim bir güç. Gözcünün Ahdi’nin Muhafızları, layık olmayan hiçbir ruhun geçemeyeceği kapıları kapalı tutarken onun bilgeliği ve vahşetiyle güçlenir. Bu kadim savaşçıyı yenecek kadar güçlü ölümlüler onun maskesini takabilir, belki de barındırdığı güce bir anlığına tanık olabilir.",
["bm_msk_scm_02"] = "Guardian of Kings",
["bm_msk_scm_02_desc"] = "Anubis’in eşi Bast, eski Mısırlıların kedi savaşçı olarak taptığı ama aslında dünyada çok daha eski bir güçtür. Gücüyle kutsanan Guardians of The Ark of the Watcher, bitmeyen görevlerini yerine getirirken saygı göstermek için onun maskesini takar. Yüzünü taşıyan ölümlülerin olağanüstü şansla kutsandığı ve kapıya geldiğinde ölümü kandırabildiği söylenir.",
["bm_msk_sdm_01"] = "Klaus",
["bm_msk_sdm_01_desc"] = "Klaus pek zeki bir köpek sayılmaz ama akıl eksiğini koca yüreğiyle kapatır. Kemiklerini sürünün geri kalanıyla paylaşmaya her zaman hazırdır.",
["bm_msk_sdm_02"] = "Boxey",
["bm_msk_sdm_02_desc"] = "Burada eski usul sokak zekâsı ve sert bir dayanıklılık var. Lafı uzatmadan işi bitiren bir kişilik. Ganimetine bundan daha sadık bir bekçi bulamazsın.",
["bm_msk_sdm_03"] = "Frou Frou",
["bm_msk_sdm_03_desc"] = "Sevimli, sarkık kulaklı Frou Frou hiç de ürkek bir Afgan tazısı değil. Zeki ve kıvrak zekâlı bu dost, kurnazlığın yanı sıra akıl da isteyen soygunlarda yüzünü örtmek için ideal.",
["bm_msk_sdm_04"] = "Crazy Lou",
["bm_msk_sdm_04_desc"] = "Küçük cüssesine, darmadağınık tüylerine aldanma. Bu ufaklığın delici bakışları hemen herkesi sindirebilir. O nöbetteyken bir şey çalmaya kalkışanın vay hâline.",
["bm_msk_sdtp_azuredragon"] = "Azure Dragon",
["bm_msk_sdtp_azuredragon_desc"] = "Dört uğurlu hayvanın bu simgesini tak ve baharın gelişini getirmek için doğunun büyük gücünü kullan!",
["bm_msk_sdtp_blacktortoise"] = "Black Tortoise",
["bm_msk_sdtp_blacktortoise_desc"] = "Uğurlu dört yaratığın en karanlığı, kuzey topraklarından kışı çağırır!",
["bm_msk_sdtp_vermilionbird"] = "Vermilion Bird",
["bm_msk_sdtp_vermilionbird_desc"] = "Uğurlu dört yaratığın bu simgesi güneyden gelir; yanında yaz alevinin parlak, kavurucu sıcağını taşır.",
["bm_msk_sdtp_whitetiger"] = "White Tiger",
["bm_msk_sdtp_whitetiger_desc"] = "Sokaklara düşen yapraklar, batının bu uğurlu yaratığına ve sonbaharın gelişine tanıklık ediyor.",
["bm_msk_shirai"] = "Shirai",
["bm_msk_shirai_desc"] = "Gel buraya! Sana duyduğun en baba ninjalardan bahsedeyim. Onlar dünyamızın koruyucuları ve aralarına yalnızca en iyi savaşçıları alıyorlar. Herkesten üstün oldukları belli olsun diye onlara en fiyakalı maskeler veriliyor. İşte senin masken, klana hoş geldin.",
["bm_msk_shogun"] = "The Shogun",
["bm_msk_shogun_desc"] = "Maskeyi tak ve kendini uzak geçmişten bir Japon generali gibi hisset.$NL;$NL;Bu maskenin, rütbeleri birer birer aşıp pek çok savaş kazanan büyük bir generale dönüşmüş çılgın ve gözü kara bir savaşçıya ait olduğu söylenir.$NL;$NL;Sağduyuyla büyük işler başarılmaz. Bunun için çılgın ve gözü kara olmalısın.",
["bm_msk_shrunken"] = "The Shrunken Head",
["bm_msk_shrunken_desc"] = "Törenle hazırlanmış; kafatası başın içinden çıkarılmış, gözlerle ağız dikilip kapatılmış. Sıcak suda kaynatılıp sıcak taşlar ve kumla kurutulmuş, insan yüzünün hatlarını koruyacak şekilde biçim verilmiş.$NL;$NL;Uzun zaman önce Batılılar tarafından gemiyle Amerika’ya götürülmüş. Şimdi bir şekilde senin eline geçti.",
["bm_msk_silverback"] = "Steven",
["bm_msk_silverback_desc"] = "Gümüş sırtlı goril Steven. Sadece dev gibi değil, fena hâlde güçlü de. Sana bakarak bile belini kırabilir. Haftalarca hastanede kalırsın. Üstüne aylarca tedavi de var. Yeniden yürümeyi öğrenmek ne kadar zor, biliyor musun? Başka ne sert, biliyor musun? Steven’ın kasları. 22 yıl önce bir askerî gemide aşçıydı. 103 dakikada herkesi öldürdü.",
["bm_msk_simpson"] = "The Tids",
["bm_msk_simpson_desc"] = "Bazıları yarış tulumunun ağartılmış yunus derisinden yapıldığını, yağlı salgılarının Çin tıbbında değer gördüğünü söylüyor. Tek bildiğimiz... Adı The Tids.",
["bm_msk_skm_01"] = "Fancy Top Hat",
["bm_msk_skm_01_desc"] = "Herkesin içinde seçkin soyguncuya hitap eden bir şey vardır. New York’un ünlü şapkacılarının yaptığı bu klasik şapka, her kolluk görevlisinin bakışını üzerine çeker.",
["bm_msk_skm_02"] = "The Super Villain Moustache",
["bm_msk_skm_02_desc"] = "Cilayı sür, cilayı sil. Ganimetinle sisli geceye karışıp gülerken onu gönlünce bur.",
["bm_msk_skm_03"] = "Classy Monocle",
["bm_msk_skm_03_desc"] = "Keşke şu muhteşem gözlükte bir holografik mercek de olsaydı. Ama ne yazık ki yalnızca kasaya doğru tuş birleşimini girerken klasik bir şıklık sergilemeni sağlayacak.",
["bm_msk_skm_04"] = "The Classically Fancy Super Villain",
["bm_msk_skm_04_desc"] = "Eski usul kötülüğün zirvesi. İster frakla ister zırhla tamamla; bu takım herkese ciddi olduğunu, hem de en suçlu anlamıyla ciddi olduğunu anlatır.",
["bm_msk_skm_05"] = "Mega Optimist Prime",
["bm_msk_skm_05_desc"] = "Gelecekten Gelen Robot Efendiler, sevinin! Lideriniz geldi; yanında da bolca pozitif yüklü parçacık getirdi.",
["bm_msk_skm_06"] = "Mega War",
["bm_msk_skm_06_desc"] = "Bu miğferle polislere, 80’lerin Bütün Metal Gruplarının Tanrısı tarafından saldırıya uğradıklarını düşündür!",
["bm_msk_skm_07"] = "Mega Pirate",
["bm_msk_skm_07_desc"] = "Korsan Kralları’nın en gizemlisi Korkunç Skulltooth, ortalıktaki tüm kolluk kuvvetlerine titreme getirecek. Yarr!",
["bm_msk_skm_08"] = "Mega Vlad Armor",
["bm_msk_skm_08_desc"] = "Söylentiye göre bu miğfer terk edilmiş bir Rus nükleer tesisinde bulunmuş. Takan kişi zamanla süper güçler kazanacakmış. Ama sadece söylenti.",
["bm_msk_skull"] = "The Skull",
["bm_msk_skull_desc"] = "Ölümü ve faniliği temsil eden özel bir maske.$NL;$NL;Tanrılar tarafından göklerde yaratılıp onlara en başından inanan, tapınaklarını kuran ve inançlarını diyar diyar yayan kadınlarla erkeklere armağan edildi.$NL;$NL;Bize inandığınız için teşekkürler! Sizi selamlıyoruz!",
["bm_msk_skulldia"] = "Nine Lives",
["bm_msk_skulldia_desc"] = "Hakkınızı vereyim dostlar. Şu kısacık dokuz yılda az iş başarmadınız. Kaç yer soydunuz? Kaç kilit açtınız? Kaç herifi, dişçiyi, kendini beğenmiş, iktidar delisi kaypak pisliği yaradanına kavuşturdunuz? Başlangıcımızın sarsıntılı olduğunu biliyorum ama şimdi hâlimize bakın! Beni çetenize kabul ettiniz. Bu benim için dünyalara bedeldi dostlar.$NL;Teşekkürümün küçük bir göstergesi olarak bu maskeyi yaptırdım. Bu arada, bunlar gerçek Güney Afrika elmasları!",
["bm_msk_skullhard"] = "The Hard Skull",
["bm_msk_skullhard_desc"] = "İnsan kafatası tuhaf bir şey. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var.",
["bm_msk_skullhard_desc_WIN32"] = "İnsan kafatası tuhaf bir şey. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var.$NL;$NL;Bütün soygunları Zor zorlukta bitirdin mi? Sen nesin, profesyonel falan mı? Belki de bu maske sana yakışır.",
["bm_msk_skullmonkey"] = "Clint",
["bm_msk_skullmonkey_desc"] = "Siyah başlıklı sincap maymunu Clint. Adsız bir maymun değil yani. Gerçek Clint gibi bu maymun da boş işlerle uğraşmaz. Kendi işine bakar. Kendisine konuşulmadan konuşmaz; az söyledikçe güçlendiğini bilir. Gerçekten bir şey söylemeye kalkıştığında ise çığlık atar; çünkü LANET OLASI BİR MAYMUNDUR.",
["bm_msk_skulloverkill"] = "The OVERKILL Skull",
["bm_msk_skulloverkill_desc"] = "Hassiktir, bu yeni şeytanlık da ne? İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu insan kafatasına benzemiyor.",
["bm_msk_skulloverkill_desc_WIN32"] = "Hassiktir, bu yeni şeytanlık da ne? İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu insan kafatasına benzemiyor.$NL;$NL;Bütün soygunları OVERKILL zorluğunda bitirdin mi? Sen nesin, cehennem zebanisi falan mı? Belki de bu maske sana yakışır.",
["bm_msk_skulloverkillplus"] = "The Death Wish Skull",
["bm_msk_skulloverkillplus_desc"] = "OVERKILL seni selamlıyor; ölümü getiren, kolluk kuvvetlerini katleden, tüm zorlukları tamamlayan kişi. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu bir insan kafatası değil, bambaşka bir şey.",
["bm_msk_skulloverkillplus_desc_WIN32"] = "OVERKILL seni selamlıyor; ölümü getiren, kolluk kuvvetlerini katleden, tüm zorlukları tamamlayan kişi. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu bir insan kafatası değil, bambaşka bir şey.$NL;$NL;Bütün soygunları Death Wish zorluğunda bitirdin mi? Sen nesin, iblis falan mı? Belki de bu maske sana yakışır.",
["bm_msk_skullveryhard"] = "The Very Hard Skull",
["bm_msk_skullveryhard_desc"] = "İnsan kafatası tuhaf bir şey. Gerçi bu kafatası artık pek insana benzemiyor. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu kafatasında tuhaf bir şeyler var.",
["bm_msk_skullveryhard_desc_WIN32"] = "İnsan kafatası tuhaf bir şey. Gerçi bu kafatası artık pek insana benzemiyor. İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Ama bu kafatasında tuhaf bir şeyler var.$NL;$NL;Bütün soygunları Çok Zor zorlukta bitirdin mi? Sen nesin, canavar falan mı? Belki de bu maske sana yakışır.",
["bm_msk_slicer"] = "Slicer",
["bm_msk_slicer_desc"] = "Kardeşinin öldürülmesinden sonra Ikas, eğitim alıp en ölümcül savaşçıları olmak için gizli bir ninja klanına katıldı. Ikas kendini çabucak kanıtladı ve klanın bütün Amerika kolunun başına getirildi. Kendine özgü maskesi artık korku ve saygı uyandırıyor; böyle maske takan herkes Achilles Clan’in kardeşi sayılır.",
["bm_msk_slimy_goat"] = "Mastermind Goat",
["bm_msk_slimy_goat_desc"] = "Yunus, hayvanlar âleminin en sinsi ve acımasız soyguncusudur; dost canlısı ve sevimli görünümüyle herkesi kandırır. Ama hepsi bir aldatmaca! Yunus yalnızca kendini ve ganimeti düşünür, birini geride bırakmakta bir saniye bile tereddüt etmez. Bu maskeyi takan bir soyguncuyla karşılaşırsan dikkatli ol.",
["bm_msk_smiley"] = "Smiley",
["bm_msk_smiley_desc"] = "Bir zamanlar gülümseyemeyen bir palyaço vardı. Diğer palyaçoların gence yaşlıya neşe ve mutluluk verdiğini izledi. Kıskançlığı ve öfkesi büyüdü; sonunda geniş bir sırıtış elde etmek için dudaklarını yanaklarına zımbaladı. Ama herkesi mutlu etmek yerine korkuttu. Nedenini anlayamadı.$NL;$NL;Belki de görevinin bu olduğuna karar verdi; insanları korkutmak... Hem de çok korkutmak.",
["bm_msk_smo_01"] = "Chibi Kitteh",
["bm_msk_smo_01_desc"] = "Bir soyguncu sokakta bu maskeyle yürüyorsa dünya onun hiçbir şeyden korkmadığını anlar. Dokuz canın da canı cehenneme!",
["bm_msk_smo_02"] = "Spirit Fox",
["bm_msk_smo_02_desc"] = "Efsanelere göre Okinawa ormanlarında alev başlı bir tilkinin ruhu yaşar. Bu tilkinin seni görmesi bir nimet sayılır ama bu maskeyi takmış bir soyguncunun seni görmesi muhtemelen öyle değildir!",
["bm_msk_smo_03"] = "Poly Goat",
["bm_msk_smo_03_desc"] = "1990’ların bir video oyunundaki Şeytan’a tapanlar aradı; düşük poligonlu keçilerini geri istiyorlarmış. Verecek misin, yoksa onları boş mu çevireceksin?",
["bm_msk_smo_04"] = "Jamaican Nightmare",
["bm_msk_smo_04_desc"] = "Bazı Vudu rahipleri sonsuz yaşamın sırrını bildiklerini iddia eder. Bu maskeyi takmanın onu sağlayacağının garantisi yok ama düşmanlarının ödünü muhtemelen koparır. Belki bir Jamaika barbeküsüne davet edilmeni de sağlar.",
["bm_msk_smo_05"] = "Arcade Simian",
["bm_msk_smo_05_desc"] = "Bu maskeyi takarken polislere attığın el bombalarını fıçı sayabilirsin. Onlar hoşlanmaz ama bir şeyleri patlatmanın tekdüzeliğini belki bozar!",
["bm_msk_smo_06"] = "Black Bird",
["bm_msk_smo_06_desc"] = "Ah, ne düşüncelere dalabilirsin; zengin ve küfürbaz hâlinle, unutulmamış paranın o tuhaf, merak uyandıran yığını üzerinde. Böyle buyurdu Soyguncu.",
["bm_msk_smo_07"] = "Mega Biker",
["bm_msk_smo_07_desc"] = "1980’lerin her çocuğu bu maske için adam öldürür. Neon otoyolların gerçek hâkimi kimmiş, herkese göster.",
["bm_msk_smo_08"] = "Mega Krampus",
["bm_msk_smo_08_desc"] = "Şeytanlar da iblisler de bu maskeyi takan soyguncunun ihtişamını gördüklerinde hayranlıkla titreyecek.",
["bm_msk_smo_09"] = "Mega Smiley",
["bm_msk_smo_09_desc"] = "Tragic Clown’a bu en büyük saygı gösterisinin işkence edercesine mutlu sırıtışına, çürüyen altın dişlerine ve derinden büyüleyen bakışına bir bak.",
["bm_msk_smo_10"] = "Mega Tiara",
["bm_msk_smo_10_desc"] = "Mezuniyet balosu kraliçeleri, alnına bu parlak süsü takan bir soyguncunun yanında hiç kalır. Söylentiye göre taşların hepsi 1800’lerde Dünya’ya düşen bir Perseid göktaşından gelmiş.",
["bm_msk_smo_11"] = "Mega Anubis",
["bm_msk_smo_11_desc"] = "Bir Mısır tanrısı gibi havla; ganimet yığınlarını koruyup kollarken sonsuza dek nöbet tut.",
["bm_msk_smo_12"] = "Mega Robber Fly",
["bm_msk_smo_12_desc"] = "Bu maskenin dehşetini salıp hem polislere hem sivillere 1960’ların bir korku filminde olduklarını düşündür.",
["bm_msk_smoker"] = "The Specialist",
["bm_msk_smoker_desc"] = "Böyle bir maskeyi ancak gerçek bir Teknisyen tasarlayabilir.$NL;$NL;Son teknoloji hava filtreleme sistemi sayesinde, o pek olası olmayan \"metamfetamin pişirmem gerek\" durumlarında kimyager başlığı olarak da kullanılabilir.$NL;$NL;Bu maske, Kötü Şöhret ağacı ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_sms_01"] = "Secret Dallas Mask",
["bm_msk_sms_01_desc"] = "Dallas bazen Bain’in Secret’ın bazı ayrıntılarını ondan sakladığını hissediyordu. First World Bank’teki işten sonra Bain, Maya altınının neden bu kadar önemli olduğunu hiç açıklamadı. The Payday Gang bir aile ve güven her zaman kurşungeçirmez değil. Ama Dallas artık, yolun sonunda, Bain’in gizlilik ihtiyacını anlıyor. Onun bilgeliği sayesinde ikisi de kendi istediğini aldı.",
["bm_msk_sms_02"] = "Secret Chains Mask",
["bm_msk_sms_02_desc"] = "Chains, Secret arayışını hiç fazla ciddiye almadı; sık sık bir sürü \"tuhaf zırva\" derdi. Ama ayakları yere basan pratik bir adam olarak Bain ile ilişkisine güvenerek kararlı ve sadık kaldı.",
["bm_msk_sms_03"] = "Secret Hoxton Mask",
["bm_msk_sms_03_desc"] = "Hoxton, yeni ülkede vurgununu yapmak için Eski Ülke’yi geride bıraktı. Bain ona Secret’ı ilk anlattığında kadim eşyaların olası değeri için peşlerine düşme fikri hoşuna gitmişti. Bain’in sözünü ettiği efsanevi gücün gerçek olup olmadığınıysa pek umursamıyordu.",
["bm_msk_sms_04"] = "Secret Wolf Mask",
["bm_msk_sms_04_desc"] = "Wolf hep şiddete meyilli, öngörülemez bir müttefikti. Bu yüzden Bain, Secret arayışının ne kadarını ona anlatacağından başta emin değildi. Sonunda değeri ortaya çıktı ama Bain arayışını nihayet açıkladığında Wolf aklını kaçıracak kadar heyecanlandı. Hem altın kazancından payını alacaktı hem de iyi bir komploya bayılırdı.",
["bm_msk_sms_05"] = "Mesoamerican Dallas Mask",
["bm_msk_sms_05_desc"] = "Bir lider olarak kariyeri boyunca çok şeyden vazgeçmek zorunda kaldı. İşler, ekip üyeleri, kişisel hedefler; işi bitirmek için ne gerekiyorsa. Mezoamerika kültürleri tanrıları hoşnut etmek için nasıl kurban verdiyse Dallas da soygun tanrılarına, yani işverenlere öyle kurbanlar verdi.",
["bm_msk_sms_06"] = "Egyptian Wolf Mask",
["bm_msk_sms_06_desc"] = "Vahşilik, ölüme meydan okuma ve altın; eski Mısırlıların her şeye karşı koyarak gelişip fethetmesinin unsurları. Bu kadim kültürü onurlandıran maskeyi Wolf’un takması da bu yüzden bir bakıma yerinde.",
["bm_msk_sms_07"] = "Summerian Chains Mask",
["bm_msk_sms_07_desc"] = "Sümerler bilgelik, müzik ve ruhsal güç çağını başlattı; dünyanın nasıl başladığına dair fikirler kuracak hayal gücüne sahiplerdi. Chains dışarıdan profesyonel bir silah ustası olabilir ama içinde hayattan bile büyük bir ruh taşır. Bu yüzden bu maskenin temsil ettiği kültürü onurlandırır.",
["bm_msk_sms_08"] = "Watchers Hoxton Mask",
["bm_msk_sms_08_desc"] = "İnsanlığa en büyük armağanı verenler, uygarlıkları toprağın ve suyun altında yatıyor olabilecek olanlar nereden geldi? Kim olurlarsa olsunlar, varlıklarının izlerinin çoğu zamanla silindi. Yeni bir gelecek arayan gezgin Hoxton gerçeği bilmiyor olabilir ama Secret’ın kökenini onurlandırmak için yine de onların maskesini takıyor.",
["bm_msk_sokol"] = "Sokol",
["bm_msk_sokol_begins"] = "Sokol Begins",
["bm_msk_sokol_begins_desc"] = "Bu, Sokol’un ikonik maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_sokol_desc"] = "St Petersburg Bombers hokey takımında mücadeleci bir oyuncu olmak Sokol’a bir şeyin değerini öğrettiyse o da yakışıklı Rus yüzünü koruyan korkutucu bir maskenin önemiydi.",
["bm_msk_solus"] = "Planetary Tomb Guardian",
["bm_msk_solus_desc"] = "Gezegen Mezarı Muhafızlığı yalnız bir iştir. Ama yapılması gereken bir iştir. Görünürde tek bir canlı bile olmadan çağlar geçer. Yıldızlar ve güneşler gündüzle geceyi aydınlatır. Ama yalnızlık korkunçtur. Derken bir gün bir uzay aracı sessizliği bozar; artık yalnız değilsin. Biri, evim dediğin bu gezegeni ziyaret ediyor.",
["bm_msk_sombrero"] = "The Sombrero",
["bm_msk_sombrero_desc"] = "Bunu takan soyguncuya gülen kişi, yüzündeki kocaman mermi deliğiyle gülemiyorsa son kez güldüğünü yakında anlayabilir.",
["bm_msk_spa_01"] = "Captain",
["bm_msk_spa_01_desc"] = "Kaptan köprüde! Mürettebatını bankalarda sağ salim gezdir; elverişli bir rüzgâr seni büyük maceralara taşısın. Kıyıyı vurup hazinelerini al, sonra ufukta kaybol.",
["bm_msk_spa_02"] = "Sailor",
["bm_msk_spa_02_desc"] = "Hazine filosunda denize açıl. Batık altını ararken armaya tırmanıp peşindeki gemilere göz kulak ol. Yetişirlerse olduğun sıçan gibi gemiyi terk et ama altını almayı unutma.",
["bm_msk_spa_03"] = "Bird of Prey",
["bm_msk_spa_03_desc"] = "Yükseklerde süzül, aşağı dalıp avına acımasız, ölümcül pençelerle saldır. Sonra yükseklerdeki yuvana uç, avının nimetlerini tat. Besin zincirinin tepesindeki yırtıcı sensin ve her şeyi silip süpüreceksin.",
["bm_msk_spa_04"] = "Lady Liberty",
["bm_msk_spa_04_desc"] = "Özgürlük. Yakalanıp hapse atılmış tüm soygunculara özgürlük. Bankaların karanlık bodrum kasalarında hüzünle bekleyen tüm altınlara özgürlük. Girişim ruhuna, istediğini alma iradesine, silahın hükmüne özgürlük. Daha büyük bir vurgun arayanlara özgürlük.",
["bm_msk_spackle"] = "Spackle",
["bm_msk_spackle_desc"] = "Bir zamanlar ünlü bir sirk palyaçosu olan Spackle, camianın en iyi makyaj sanatçısıydı. İnsanları kendilerine hiç benzemez hâle getirme becerisiyle tanınıyordu; bu sanata saplantılı hâle geldi.$NL;$NL;Kendi yüzünü tuval yapıp yorulmadan kat kat makyaj sürdü. Her katman daha çarpıktı. Makyajlarını yaparken beş kişiyi öldürdükten sonra akıl hastanesine gönderildi.",
["bm_msk_speed_demon"] = "Speed Devil",
["bm_msk_speed_demon_desc"] = "Motorcu yaşamının hiçbir şeyi umursamayan tavrını simgelemek için Devil’ın yüzünü takmaktan daha iyi ne olabilir? Kanunu çiğnemenin nihai simgesi.",
["bm_msk_speedfreak"] = "Speed Freak",
["bm_msk_speedfreak_desc"] = "Kafandaki sesler seni delirtmek istiyorsa önce yakalamaları gerekecek.",
["bm_msk_speedrunner"] = "SpeedRunner",
["bm_msk_speedrunner_desc"] = "Hızlı bir koşunun zamanı geldi! SpeedRunner, New Rush City halkının şampiyonu. Suça ve yardıma muhtaçlara doğru koşarak, kayarak, salınarak ilerler; birincilikten azını kabul etmez. SpeedRunner’ın ihtiyacı... koşmak!",
["bm_msk_spider"] = "Tarantula",
["bm_msk_spider_desc"] = "Sekiz güçlü bacaklı tarantulaların boyu, bacakları tamamen açıldığında tırnak kadar küçükten tabanca kadar büyüğe kadar değişir. Adı aslında bir kurt örümceği türü olan Lycosa tarantula’dan gelir. Tarantulalar genellikle ağaçlarda, yerde veya yere yakın avlanır. Ev hayvanı olarak da popülerdirler.",
["bm_msk_sports_utility_mask"] = "Sports Utility Mask",
["bm_msk_sports_utility_mask_desc"] = "Hantal ve demode kaskları unut; bu muhteşem şey her adrenalin tutkununun en iyi dostu. Sert ABS plastikten yapılmış yüz koruması kara, kum savrulmalarına ve doluya karşı sağlam koruma sağlar. Yeter ki kafana ağır darbe alma. Airboard yapan arkadaşların sana gıpta etsin dostum!",
["bm_msk_sputnik"] = "Sputnik",
["bm_msk_sputnik_desc"] = "Orijinal Sputnik yalnızca bipleyen küçücük bir küre olmasına rağmen 1950’lerin Washington’ında siyasi şok dalgaları yarattı. Bu klasik ama süslenip püslenmiş sürümle başkentte suç dalgaları yarat.",
["bm_msk_starvr"] = "StarVR",
["bm_msk_starvr_desc"] = "Gerçek hayat kirli, rahatsız, yapışkan, terli, pis kokulu; tadı kötü, sonunda seni yaşlı ve kırık dökük bırakıyor. Boş ver gitsin. StarVR Headset, inanılmaz gerçekçi bir sanal dünyanın içine dalmanı sağlar.",
["bm_msk_stoneface"] = "Terminator",
["bm_msk_stoneface_desc"] = "Bu gözlük, uzak bir diyardan bir suikastçıya aitti. John’un öldürmeye gönderildiği suikastçı makine gibiydi. Bu zorlu bir iş olacaktı. Özelleştirilmiş bir Geliştirilmiş Birleşik Taktik Yelek kullanıyordu. Baştan aşağı zırhlıydı, çok sağlamdı. Ama John bütün o zırhın altında yalnızca et ve kemik olduğunu biliyordu.$NL;$NL;Sonunda John onu öldürmeyi başardı. Ama onu yerinden ettiğinde yerine bir başkasının geleceğini biliyordu.",
["bm_msk_stonekisses"] = "The Pout",
["bm_msk_stonekisses_desc"] = "Dudak büzmek, insanların yapabildiği bir yüz ifadesidir.$NL;$NL;Özellikle somurtkan bir hoşnutsuzluğu anlatmak için dudakların dışarı uzatılmasıdır.$NL;$NL;Boynuzları öyle testereyle kesilse kim hoşnutsuz olmaz ki?",
["bm_msk_strinch_achievement"] = "Açmak için Noel'i Çalmak başarımını tamamla!",
["bm_msk_surprise"] = "War Face",
["bm_msk_surprise_desc"] = "Savaş suratın var mı! AAAAAAAAHH! İşte savaş suratı budur, hadi seninkini göreyim!$NL;$NL;...$NL;$NL;Saçmalık. Beni ikna etmedin. GERÇEK savaş suratını göreyim!$NL;$NL;...Aslında bu fena değil...$NL;$NL;Bu maske bir Poetry Jam maskesidir. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_sweettooth"] = "Sweet Tooth",
["bm_msk_sweettooth_desc"] = "Asıl adı Marcus \"Needles\" Kane olan Sweet Tooth, Twisted Metal video oyunu serisinin bir karakteridir. Sweet Tooth en çok savaş donanımlı bir dondurma kamyonu süren katil palyaço olarak tanınır.$NL;$NL;Bir zamanlar akıl hastanesinden kaçtığı söylenir. Şimdi suç dolu bir hayat sürüyor.",
["bm_msk_sydney"] = "Sydney",
["bm_msk_sydney_begins"] = "Sydney Begins",
["bm_msk_sydney_begins_desc"] = "Bu, Sydney’nin ikonik maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_sydney_desc"] = "Sırıtış, tebessüm, alaycı gülüş; ne dersen de. Bu sırıtan punk maskesinin yaklaştığını gördüğünde kafandan eş anlamlı sözcükler geçmeyecek, mermiler geçecek. Sydney bunu garanti eder.",
["bm_msk_tall_goat"] = "Scout Goat",
["bm_msk_tall_goat_desc"] = "Zürafa hiçbir şeyi kaçırmaz; çevresinin hep tamamen farkındadır. Hayvanlar âleminde soygun için kusursuz bir \"gözcü\" yoldaşıdır. Ne geliyorsa kilometrelerce öteden görürsün, polisler de seni hazırlıksız yakalamayı unutsun.",
["bm_msk_tam"] = "The Great Immortal",
["bm_msk_tam_desc"] = "Yolcu bin yıl uyudu; yıldızlar hizalanıp yeterince yetenekli bir ölümlü onu o kutsal olmayan hapishaneden çıkarana dek bekledi. Sevinin! O gün geldi. Bu gücü... akıllıca kullan.",
["bm_msk_tane"] = "Tane",
["bm_msk_tane_desc"] = "Tane, muazzam gücüyle anne babası olan yeri ve göğü birbirinden ayıran orman tanrısıydı. Efsaneler ilk insan Tiki’yi de onun yarattığını söyler. Böylece bildiğimiz dünyayı ve içindeki insanları yarattı.",
["bm_msk_tcn"] = "Criminal Ambitions",
["bm_msk_tcn_desc"] = "Yalnızca en hırslı soyguncuya layık bir maske.$NL;$NL;Bütün ganimeti al, hiçbir şey bırakma.$NL;Gerçek suç dehasının işareti budur.$NL;Bütün elmasları, küçük kazançları topla.$NL;Artık suçla dolu büyük hayallerin var.$NL;$NL;Bu maske bir Poetry Jam maskesidir. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_tech_lion"] = "Tech Lion",
["bm_msk_tech_lion_desc"] = "Bu maske, Mısır savaş tanrısı Maahes’in modern bir yorumu. \"Bıçağı Taşıyan\", \"Katliamın Efendisi\" ve \"Haksızlıkların Öcünü Alan\" olarak bilinen Maahes, düzenle dengenin kişileşmiş hâli Ma`at’ın kurallarını çiğneyenleri cezalandırırdı. Güneşin yakıcı sıcağının vücut bulmuş hâli sayılır, savaşta firavunu savunan koruyucu bir tanrı olarak da görülürdü.$NL;$NL;Genellikle bıçak taşıyan, Atef tacı veya Güneş Diski takan aslan başlı bir adam ya da bir kurbanı yiyen aslan şeklinde tasvir edilir.",
["bm_msk_the_king_mask"] = "The King",
["bm_msk_the_king_mask_desc"] = "İnsaf! O havalı pilot gözlükleri, belalı pompadur saç ve taktik favorilerden oluşan kraliyet üçlüsünü taşıyacak kadar fena bir delikanlı ya da kız mısın? Vegas’ın dört bir yanında bunu takıp başarıya ulaşan ikinci el otomobil satıcılarının ve apar topar nikâh kıyan din adamlarının yılmaz ruhunu çağır. Ya da en azından toplum içinde hafif bir mahcubiyete ulaşanların. Kralı selamlayın!",
["bm_msk_the_overkill_mask"] = "General OVERKILL",
["bm_msk_the_overkill_mask_desc"] = "Hazır ol! Pekâlâ dinleyin, sizi soyguncu piçler. Savaşa gidiyorsunuz. Çatışmanın acısını hissedeceksiniz. Savaşta da lider gerekir. General OVERKILL’le tanışın. O polis pisliklerini kazdan bok geçer gibi geçmenizi sağlayacak. Dağılın!",
["bm_msk_the_strinch"] = "The Strinch",
["bm_msk_the_strinch_desc"] = "Bayram döneminin tecrübeli soyguncusu Strinch, 1957’den beri Noelleri çalıyor. 1972’deki Halloween Heist ile de bağlantılı.",
["bm_msk_threap"] = "The Reaper",
["bm_msk_threap_desc"] = "Onu on arabalık zincirleme kazaların fotoğraflarında, kamyon çarpışmalarının haber görüntülerinde gördün; hep korkunç bir kazanın yanından geçerken. Tepeden tırnağa siyaha bürünmüş bir motosikletli, hızdan bulanıklaşan solgun bir yüz. Sana onun sıradan bir motorcu olduğunu söylüyorlar. Milyonlarcasından biri. Ama onu daha önce gördüğünü biliyorsun. Şimdi de bu buzlu, kardan göz gözü görmeyen otoyolda hemen önünde sürdüğünü görür gibi oluyorsun...$NL;Frenlerinin çalışmadığını işte o an fark ediyorsun.",
["bm_msk_tiara"] = "Tiara",
["bm_msk_tiara_desc"] = "Tamam, yüzünü gizlemiyor ve sana doğru vızıldayan mermileri de kesinlikle durdurmaz... Ama vay be. Mrs Volkov’un gelin tacını taktığında balonun en güzeli sen olacaksın.",
["bm_msk_tiger"] = "Tony",
["bm_msk_tiger_desc"] = "Tony kendisine bulaşan herkesi öfke dolu yumruklarıyla pataklar.$NL;$NL;Tony, 1970’lerde doğmuş İtalyan asıllı bir Amerikalıdır. Pek çok kişi Tony’yi kolayca tanır. Muhtemelen hem Tiger maskesi hem de sevmediği insanlara karşı fiziksel vahşeti sayesinde.",
["bm_msk_tinted_love"] = "Tinted Love",
["bm_msk_tinted_love_desc"] = "Cinayet, haraç, şiddet, yıkım, uyuşturucu, silah ve hırsızlık. Bunların hepsi Vlad’la ilişkilendirilen suçlar ama hiçbiri onun moda anlayışı kadar büyük değil.",
["bm_msk_titan"] = "Titan",
["bm_msk_titan_desc"] = "Bir zamanlar aramızda yürürlerdi. Kuleler kadar uzun, devasa varlıklar. Primat atalarımız ateşe ulurken onlar zaten yaşlıydı. Artık yoklar; yalnızca gölgeleri, yarı düşlenmiş tür hatıralarında bize ulaşıyor.",
["bm_msk_tonys_revenge"] = "Tony's Revenge",
["bm_msk_tonys_revenge_desc"] = "Neredeyse kusursuz yırtıcı. Kaplanlar son derece güçlü, bir o kadar da hızlıdır. Vahşi ama sabırlıdırlar. Sessizce sokulup bir anda şiddetle saldırabilirler. Kusursuz bir ölüm makinesi. Buna rağmen kaplanların sayısı azalıyor. Kaçak avcılar, geleneksel tıp için kaplan penisine değer biçiyor. O yüzden sakın canlı ele geçme.",
["bm_msk_toon_01"] = "Dallas, The Chief",
["bm_msk_toon_01_desc"] = "Bazıları hayatta bedavadan yol almak, yakışıklılıkla ve şansla ilerlemek ister. Bazen öyle görünse de dünya öyle işlemez. Yetenek yalnızca başlangıçtır; eğitim, adanmışlık, kararlılık gerekir. Lider olarak kendi kararını vermelisin. Kararlarına saygı duyarsan başkaları da duyar.",
["bm_msk_toon_02"] = "Wolf, The Maniac",
["bm_msk_toon_02_desc"] = "Ne zaman bırakmamak gerektiğini bilmek, ne zaman havlu atacağını bilmekten zordur. Kibir veya aptalca gurur seni yoldan çıkarmasın. Bazen bir soruna öyle kapılırsın ki asıl sorunun ne olduğunu göremezsin. Bu, herkesin başını büyük belaya sokar. Çok kötü belaya. O yüzden doğru olanı yap, yanlış yola sapmazsın.",
["bm_msk_toon_03"] = "Chains, The Weapons Expert",
["bm_msk_toon_03_desc"] = "Dünyada bir şeyin yalnızca tek örneği kaldığında o şey paha biçilmez olur. Neyi yapabildiğini, başkalarının neyi daha iyi yapabildiğini bil. İşi bitir. Kıskançlığa kapılma; o konuşan korkudur. Korku seni aşağı çeker. Sevgiden doğmaz. Birini gerçekten sevdiğinde ona güvenirsin. Paha biçilmez şeyler yüzünden kötüleşmeyecek kadar güvenirsin.",
["bm_msk_toon_04"] = "Hoxton, The Infiltrator",
["bm_msk_toon_04_desc"] = "Şu anki dostların, hayatın boyunca ihtiyaç duyacağın bütün dostların olmayabilir. Yeni dostları uzak tutarak gelecekteki bir kazancı kaçırma. Çölde kaybolmak kolaydır; tek yanlış dönüş yeter. Kaybolduğunda o yeni dostlar bir vahaya çıkış biletin olabilir.",
["bm_msk_tormentor"] = "Tormentor",
["bm_msk_tormentor_desc"] = "Bir gülümseme en ölümcül düşünceyi saklayabilir ama gözler asla yalan söylemez. Birini okumak, çoğunlukla doğrudan gözlerine bakmaktır. Asıl korkunç olan, düşünceleri yüzüne yansıyan insanlardır; bakan kişi bir saniye içinde çığlığını bastırmakta zorlanır.",
["bm_msk_tounge"] = "Mr. Smooth",
["bm_msk_tounge_desc"] = "Bu maske bir şekilde birbirine zıt veya çelişkili duyguları, inançları ve güdüleri aynı anda anlatıp yansıtıyor.$NL;$NL;Efsaneye göre dört yaratık birleşerek yüzü bu maskeye benzeyen daha büyük bir varlık oluşturmuş.$NL;$NL;Özetle, fena hâlde korkutucu bir maske.",
["bm_msk_trex"] = "The Tyrannosaurus ",
["bm_msk_triceratops"] = "Timothy",
["bm_msk_triceratops_desc"] = "Timothy the Triceratops, Jurassic High’ın en popüler dinozorlarından biri. Ama Teddy the Tyrannosaurus’a büyük bir kini vardı. İri olmalarına ve dinozorlar çağının son döneminde birlikte yaşamalarına rağmen bir türlü dost olamadılar. Özellikle de bahar tatilinde kulübeye gittikleri o seferden sonra. Teddy ve arkadaşları, o korku filmiyle ve göktaşının çarpmasına yedi gün kaldığını söyleyen telefon aramasıyla Timothy’ye şaka yapmıştı. Timothy bunu hiç komik bulmadı.",
["bm_msk_trik_tophatske"] = "Boney Black Top",
["bm_msk_trik_tophatske_desc"] = "İyi giyimli her iskeletin görünümünü tamamlayacak iyi bir şapkaya ihtiyacı vardır. Kemikler moda, renk de siyah. Ekim ayı boyunca 18. yüzyıl tarzında soygun yap.$NL;$NL;Yaratıcı: Luke Millanta.",
["bm_msk_trik_tophatskeblue"] = "Deadhead Blues",
["bm_msk_trik_tophatskeblue_desc"] = "Keyfin mi yok? Bataklık tarafında soygun işin mi var? Mavi doğru seçim. Bu iskelet sırıtışı onları kaçırırken sen ortadaki tüm ganimeti çalarsın!$NL;$NL;Yapım: Luke Millanta.",
["bm_msk_trik_tophatskered"] = "Red Dead Bonehead Fred",
["bm_msk_trik_tophatskered_desc"] = "Yeni bir görkemli soyguna hazırlanırken etrafını kükreyen, iblis özentisi parti canavarları mı sardı? Bunu tak, sonra durup onlara bak. Çocukların da polislerin de ödünü koparacağı garantili!$NL;$NL;Yaratıcı: Luke Millanta.",
["bm_msk_troll"] = "The Troll",
["bm_msk_troll_desc"] = "İşte köprü altında saklanmaktan bıkmış bir trol.$NL;$NL;Onun yerine neden dünyayı görmesin, köy yağmalamasın, halkın altın hazinelerini alıp öfkeli kalabalıklardan kaçmasın?",
["bm_msk_tstp_daemon"] = "Mahakala",
["bm_msk_tstp_daemon_desc"] = "Muhtemelen bir yerlerde bu maskenin adından esinlenmiş bir şarkı vardır. O düzenli heceler akılda kalan bir ritim oluşturuyor, değil mi?",
["bm_msk_tstp_dragon01"] = "Laughing Dragon",
["bm_msk_tstp_dragon01_desc"] = "Ejderhalar güler mi? Gerçekten mi? Bazıları terbiyeli olsa da genelde huysuz piçlerdir. Bir de bunu takıp kocaman bir el topuyla sana ateş eden bir soyguncunun karşısında olduğunu düşün.",
["bm_msk_tstp_dragon02"] = "Shouting Dragon",
["bm_msk_tstp_dragon02_desc"] = "Ejderha bağırıyorsa kaplan kükrer mi? Genellikle soygunda yüksek sesle kendini belli etmek başarıya zarar verir. Ama bazen sırf havalı olduğu için akışına bırakmalısın. O yüzden hadi... Kendini şımart.",
["bm_msk_tstp_godess"] = "Serenity",
["bm_msk_tstp_godess_desc"] = "Etiketinde, stresliyken ve kendini toparlamak için biraz Feng Shui’ye ihtiyaç duyduğunda harika olduğu yazıyor. Ama küçük yazıyı unutma: \"Üretici, kullanımından, yanlış kullanımından veya bunun sonucunda hapse girilmesinden sorumlu değildir!\"",
["bm_msk_twitch_orc"] = "The Orc",
["bm_msk_twitch_orc_desc"] = "Kaba, saldırgan ve genel olarak itici orklar her zaman nefret edilen bir ırk olmuştur. Goblin kuzenlerinden daha iri ve güçlü, ogre kardeşlerinden ise daha küçük ve zayıftırlar. Bu mor tenli ork, vahşi savaşçıları ve aşırı güçlü melez şamanlarıyla tanınan Stonetremble klanından gelmiştir.",
["bm_msk_twitch_orc_desc_WIN32"] = "Kaba, saldırgan ve genel olarak itici orklar her zaman nefret edilen bir ırk olmuştur. Goblin kuzenlerinden daha iri ve güçlü, ogre kardeşlerinden ise daha küçük ve zayıftırlar. Bu mor tenli ork, vahşi savaşçıları ve aşırı güçlü melez şamanlarıyla tanınan Stonetremble klanından gelmiştir.$NL;$NL;Bu bir Humble Bundle E3 maskesidir. Payday sırasında kazanılamaz ve satılamaz. Bunun yerine ücretsiz olarak maske zulana geri konabilir ama yapılan özelleştirmeler ve bunlara ödenen ücret kaybolur.",
["bm_msk_unborn"] = "Unborn",
["bm_msk_unborn_desc"] = "Bir zamanlar büyük bir oyuncu, içine şeytani bir ruh girdiğini iddia edip deforme olmuş görünümünü saklamak için maske takmaya başladı. Bir gün maske kırıldı; altında gizlenen şey bir daha asla hapsedilemedi.",
["bm_msk_unforsaken"] = "The Unforsaken",
["bm_msk_unforsaken_desc"] = "Bu efsanevi maske, topluluğumuzun bağlılığına, anlayışına ve sürekli desteğine minnettarlığımızın bir göstergesi. OVERKILL ekibi olarak sizi selamlıyoruz.$NL;$NL;İyi günde de kötü günde de miğferleri uçurmaya devam.",
["bm_msk_unic"] = "Unic",
["bm_msk_unic_desc"] = "Tak tak, kim o? Unic! New Rush City’nin karanlık sokaklarında içten bir gülümsemeden daha parlak ne olabilir? Çayırlarda dört nala koşup arkadaşlarıyla vakit geçiren Unic, dünyanın güzel yanlarını göstermeye kendini adamış. Pembe mayosu ve mor çizmeleri bu hızlı koşucuyu gerçekten eşsiz kılıyor!",
["bm_msk_unicorn"] = "Peter",
["bm_msk_unicorn_desc"] = "Peter gerçek bir efsanedir; hem de sanki ezelden beri. Alnından uzun, sivri, sarmal bir boynuz çıkan bu yaratığı bütün insanlık, gökkuşağına dokunmak istediğinde gidilecek kişi olarak tanır. Hayır, dokun. O lanet gökkuşağına dokun. Şimdi tadına bak.$NL;$NL;Şşş. Sorun yok. İyi yaptın.",
["bm_msk_uno_01"] = "Dead Man's Eyes",
["bm_msk_uno_01_desc"] = "Cesedi kıyafetleriyle birlikte yakmanı söylüyorlar. İz bırakma. Fırına atıyorsun. En yüksek ısı. Hiçbir şey kalmayacak... Gözlük hariç. Onu neden sakladığından emin değilsin. Dürtüsel değilsin, genellikle hatıra almazsın. Ama bundan fazlası var, değil mi? Bir adam bu camlardan suçla siyasetin, sadakatle ihanetin dünyasını gördü ve hepsini kendi lehine bükmeyi öğrendi.$NL;Bu gözlüğün sahibi, en çılgın hayalinin ötesinde bir komplo ördü. Belki yanında tutarsan onun gördüğünü görebilirsin.",
["bm_msk_vampire"] = "The Vampire",
["bm_msk_vampire_desc"] = "Vampir, yaşayanların kanıyla beslendiği söylenen mitolojik bir yaratıktır; yaşayan ölülerdendir.$NL;$NL;Vampirler normal insan gibi görünebilir.$NL;$NL;Saldırıya uğradıklarında yüzleri değişir, uzun ve sivri dişleri çıkar; vampir çehreleri ortaya çıkar.",
["bm_msk_velociraptor"] = "Vincent",
["bm_msk_velociraptor_desc"] = "Vincent the Velociraptor ve en iyi dostu Protoceratops Andreas Häll Penninger, bir gün ormanda dolaşırken kavga etti. Aslında büyük bir mesele değildi ama Vincent peşini bırakmadı. İnatçı Protoceratops Andreas da Vincent’a laf atmayı sürdürdü. Şiddetli bir dövüş çıktı; bugün bile kimin kazandığı bilinmiyor.",
["bm_msk_venomorph"] = "Venomorph",
["bm_msk_venomorph_desc"] = "Venomorph’u gördüğünde oyunun bittiğini bilirsin dostum. OYUN BİTTİ!$NL;Belki ateş yakıp birkaç şarkı söylemeyi deneyebilirsin.$NL;$NL;Aslında geri dönüp saklansan iyi olur. Yakında karanlık olacak ve bu yavrular çoğunlukla yalnızca geceleri çıkar... Çoğunlukla.",
["bm_msk_viking"] = "The Dragon Head",
["bm_msk_viking_desc"] = "Viking gemilerinin pruvasına takılan ejderha başı, deniz canavarlarını ve kötü ruhları korkutmak için kullanılırdı. Bulldozer’lar ve Cloaker’lar kötü, değil mi? İşe yarayıp yaramadığını neden denemeyesin? Ama ne olur ne olmaz silahın hazır olsun. Güvenlik için.",
["bm_msk_visor"] = "Safety First",
["bm_msk_visor_desc"] = "Demolition Man’deki sanal gerçeklik seks sahnesinden esinlenen bir bilim insanı, cinsel ilişki sırasında fiziksel temasa gerek bırakmayacak bir cihaz yapmayı denedi. Deney tam bir başarısızlıktı ama ilk prototiplerden birkaçı hâlâ mevcut.",
["bm_msk_vlad_armor"] = "Vlad Armor",
["bm_msk_vlad_armor_desc"] = "\"Hey! Payday palyaçoları! Vlad burada, Ana Vatan’dan ufak bir şey getirdi. Donetsk’teki bütün günlerimde bu güzel, ağır mereti taktım. Sizin narin Amerikan maskeleriniz gibi güzel değil ama beni korudu!\"",
["bm_msk_volt"] = "Volt",
["bm_msk_volt_desc"] = "Meraklı bir aşağılık olan hademe David Davidson, çalıştığı askerî araştırma tesisinde çalması kolay bir şey arayarak gizlice dolanıyordu. Anahtarının olmadığı bir kapı buldu. Merakına yenilip kapıyı tekmeleyerek açtı ve bir tür parlak ışığın saldırısına uğradı. Bir şekilde hayatta kaldı, insanüstü güçler kazandı.$NL;$NL;Yeni güçleriyle kendine Volt adını verdi.",
["bm_msk_voodoo"] = "The Voodoo",
["bm_msk_war"] = "War",
["bm_msk_war_desc"] = "Mahşerin ikinci atlısı Savaş’tır; insanlığın şiddet dolu ruhudur. Savaş, insanların doğuştan vahşi olduğuna, dövüşmek veya öldürmek için gerçek bir nedene ihtiyaç duymadıklarına inanır. Ateş kırmızısı bir ata binerdi; gittiği her yerde kan akacağını anlatıyordu.",
["bm_msk_washington"] = "The 1st",
["bm_msk_washington_desc"] = "Ordular generali, başkomutan, Kurucu Baba. Bu büyük ulusa 8 yıl hizmet etti.$NL;$NL;İlk başkan; hem de büyük bir başkan.$NL;$NL;1. başkan, tarihin en sevilen başkanlarından biriydi ve 1 $ banknotun üzerindeki yüzdü. Suçlular arasında hâlâ son derece popüler.",
["bm_msk_wasp"] = "Vespula",
["bm_msk_wasp_desc"] = "İki çift kanat, bir yumurta borusu veya iğne, kalın tüylerden yoksun bir beden ve bir çift pençe. İşte sana yaban arısı. Neredeyse her zararlı böcek türünü avlayan veya ona asalaklık eden en az bir yaban arısı türü var. Bu da sayılarını doğal yoldan denetlemede yaban arılarını çok önemli kılıyor.",
["bm_msk_water_spirit"] = "Tawhiri",
["bm_msk_water_spirit_desc"] = "Tane’nin kardeşi Tawhiri, havanın, özellikle de şiddetli fırtınaların ve şimşeklerin tanrısıdır. Bodhi ikisinden de bolca nasibini aldı. Tuvalu’da resif dalışı sırasında yaşanan özellikle şiddetli bir patlama, Bodhi’nin bu güçlü tanrının kıymetini gerçekten anlamasını sağladı.",
["bm_msk_wayfarer"] = "Reservoir Dog",
["bm_msk_wayfarer_desc"] = "Bu gözlük beş yabancıya aitti. John, kusursuz suçu işlemeye hazırlanan bir grup insanı öldürmek için tutulmuştu. Hepsi aynı giyiniyor, kod adları kullanıyordu; bu yüzden tanımaları kolaydı.$NL;$NL;Ama John olay yerine çok geç geldi. Polis çoktan oradaydı. Gitmeden önce yabancıların hepsinin öldüğünden emin oldu.",
["bm_msk_waytexase"] = "Way of the Texan",
["bm_msk_waytexase_desc"] = "Dayanıklı ol. Gururlu ol. İnatçı ol. Dost canlısı ol. Altıpatlarla çok iyi nişan al.$NL;En çok da sonuncusu.",
["bm_msk_welder"] = "The Butcher",
["bm_msk_welder_desc"] = "Gerçekten efsanevi bir İnfazcı maskesi.$NL;$NL;Söylentiye göre yıllar önce Pink Panther ekibinin en iyi tetikçilerinden biri için yapılmış ama takmaya cesaret edememiş. Fazla dikkat çekermiş.$NL;$NL;Senin derdin değil.$NL;$NL;Bu maske, Kötü Şöhret ağacı ödülüdür. Soygun sonu ödüllerinden çıkmaz ve satılamaz. Bunun yerine maske depona ücretsiz iade edebilirsin ama tüm özelleştirmeler ve bunlar için ödediğin ücret kaybolur.",
["bm_msk_white_wolf"] = "Dennis",
["bm_msk_white_wolf_desc"] = "Dennis bıçakları sever.$NL;$NL;Bozkurt, gezegendeki en iyi bilinen ve en çok araştırılan hayvanlardan biridir. İnsanların evcilleştirdiği ilk hayvan ve tek büyük etoburdur.$NL;$NL;Bugün insanların zulmü yüzünden nüfusunun yalnızca üçte biri kaldı.",
["bm_msk_witch"] = "Witch",
["bm_msk_witch_desc"] = "Cadı, çoğu zaman bir şeytanın veya yardımcı ruhun desteğiyle kara büyü yapan kişidir.$NL;$NL;Çirkin yaşlı bir acuzeden çekici bir kadına kadar her şey olabilir.$NL;$NL;Sonra süpürgesi, şapkası falan var. Bö!",
["bm_msk_wmp_01"] = "The Survivor's Pilot Hat",
["bm_msk_wmp_01_desc"] = "Kraliyet Hava Kuvvetleri’nden bir pilot, 2. Dünya Savaşı sırasında Polonya’nın Bialystok şehrinin birkaç mil dışında düştü. Çatışmada öldüğü sanılıyordu ama yıllar sonra Bialowieza Ormanı’nın derinliklerinde bulundu. Balık, kök ve yakalayabildiği hayvanlarla hayatta kalmıştı. Sağdı, sağlıklıydı ama delilik pençelerini ona geçirmişti. Sol bacağını kesmek zorunda kalmıştı. Yine de enfeksiyon kapmadan yaşamayı başarmıştı. Uçağından kurtardığı parçalarla birlikte küçük bir kulübe de bulundu. Bulunduğunda yıl 1978’di.",
["bm_msk_wmp_02"] = "The Trophy Helmet",
["bm_msk_wmp_02_desc"] = "Küçük Pomtsburg köyünde küçük bir anıt bulunur. Yosun tutmuş levhayı pek az kişi okur ama üzerinde genç bir çocuğun hikâyesi yazılıdır. Almanlar Pomtsburg’a yürüdüğünde direnişe cesaretle ve kararlılıkla önderlik etti. Pomtsburg onun doğduğu yerdi ve kimse onu yok edemeyecekti. Pomtsburg Savaşı tarih kitaplarına hiç girmedi; nasıl bittiğini bile pek az kişi hatırlıyor. Ama çocuk bu hatırayı çalmayı başardı. Ona ve başkalarına zulme her zaman karşı durmak gerektiğini hatırlatacak bir şey.",
["bm_msk_wmp_03"] = "A Proud Pilotka",
["bm_msk_wmp_03_desc"] = "Bu pilotka, Almanya’daki Müritz Gölü yakınında bir cesedin üzerinde bulundu. Zavallı ölü askerin başına iple bağlanmıştı. Adsız adamın yanında başka ceset yoktu. Pilotka Rus yapımı olduğundan onun da aynı ülkeden geldiği varsayılabilir. Pek çok tahmin vardı, hiçbiri doğru değildi. Ama en ilham verici hikâye, vatanıyla öylesine gurur duyan bir askerin ölmeden önce pilotkasını başına bağlamasıydı.",
["bm_msk_wmp_04"] = "The Officer's Hat",
["bm_msk_wmp_04_desc"] = "Bu eşya 1990’larda Kuzey Fransa’daki bir açık artırmada ortaya çıktı. Katılanlar arasında ellili yaşlarında bir kadın vardı. Onu tanıdı; takan subayın adını hatırlamasa da yüklü bir para ödedi. Genç bir kızken sebze almak için meydana gitmişti. Derken paraşütçüler inmeye başladı. Silah sesleri, patlamalar, korku ve acı çığlıkları havayı doldurdu. Subay onu bir devlet binasındaki sığınağa götürdü. Onu kurtarmak için iyilikten başka nedeni yoktu. Ama kendi canı tehlikedeyken bile onun canını kurtarmak için riske girdi. Kadın o zaman küçücük bir kızdı ama şapkayı yine de tanıdı.",
["bm_msk_wolf"] = "Wolf",
["bm_msk_wolf_clean"] = "Wolf Begins",
["bm_msk_wolf_clean_desc"] = "Bu, ikonik Wolf maskesinin boyanmadan önceki temiz hâli.$NL;$NL;Orijinalinin son hâlini hiç beğenmedin mi? İşte tarihi değiştirme şansın.",
["bm_msk_wolf_desc"] = "Wolf’un maskesi.",
["bm_msk_wolf_glow"] = "Mega Wolf",
["bm_msk_wolf_glow_desc"] = "Mega Wolf maskesi, orijinal maskenin gelişmiş bir sürümüdür. Kendini aşmayı ve arınmayı simgeler.$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_xm20_dog"] = "Hyena Two-Face",
["bm_msk_xm20_dog_desc"] = "Bu maskenin yanında, yapımcısı Eduardo Maquevera’nın el yazısıyla yazdığı bir mektup vardı. Maskenin ilhamını, ormanda yolculuk ederken yaşadığı ve karşılaştığı hayvanların kendisiyle konuştuğu bir peyote rüyasından aldığını anlatıyordu.",
["bm_msk_xm20_jaguar"] = "Mad Cat",
["bm_msk_xm20_jaguar_desc"] = "Buluc’un adamları bu maskeyi yapmak için gerçek leopar derisi kullanılmasını istedi ama usta maske yapımcısı Eduardo Maquevera onun yerine sahtesini yapmak için fazladan uğraştı. Aradaki farkı hiç anlamadılar!",
["bm_msk_xm20_mega_max"] = "Mega Sangres",
["bm_msk_xm20_mega_max_desc"] = "Sarhoş hikâyesine göre tanrıların kendileri Xibalba’da bir araya gelip bu maskeyi dövdü. 1000 savaşçının kanında sertleştirildi, 1000 bakirenin gözyaşından yapılan tekilayla arındırıldı. Sangres böyle diyor. Onunla kim tartışacak?$NL;$NL;Desteğin için teşekkürler.$NL;$NL;OVERKILL seni selamlıyor!",
["bm_msk_xm20_msq_01"] = "Relic Mask of the Will",
["bm_msk_xm20_msq_01_desc"] = "Mucho Mike bu maskeyi Buluc’un 40. doğum günü için karaborsadan aldı. Setini tamamlamak için gereken son maskeydi. Buluc, nadir görülen içten bir minnettarlık anında Mike’a terfi verdi; onu dördüncü kişisel koruması ve sırdaşı yaptı.",
["bm_msk_xm20_msq_02"] = "Relic Mask of the Body",
["bm_msk_xm20_msq_02_desc"] = "Bu maske, ailesinde nesillerdir saklanan yaşlı bir çiftçide bulundu. Adam satmayı reddedince Buluc’un adamları büyük bir zalimlikle çiftliğini ve geçim kaynağını yakıp onu mecbur bıraktı. Umarız bu tarihî eserin gelecekteki sahiplerinin talihi daha iyi olur ve daha az barbarca davranırlar.",
["bm_msk_xm20_msq_03"] = "Relic Mask of the Soul",
["bm_msk_xm20_msq_03_desc"] = "Bu, Buluc’un maske koleksiyonunda Maya kökenli su altı harabesinden çıkarılan ikinci maske. O da ağır bedellerle bulundu; onu getiren keşif ekibinin tek sağ kalanı, lanetli olduğunu söylüyor. Buluc bu tür düşünceleri de emrindeki insanların kaybını da umursamıyor. Onu getirmek için kullanılan küçük ahşap teknenin enkazı, Buluc’un malikanesi yakınındaki bir kumsalda çürüyor.",
["bm_msk_xm20_msq_04"] = "Relic Mask of the Mind",
["bm_msk_xm20_msq_04_desc"] = "Buluc’un adamları, koleksiyonuna değerli kalıntılar ararken Meksika kıyısı açıklarındaki bir su altı Maya harabesine dalıp bu maskeyi buldu. Söylentiye göre teknedeki adamı Raul dalgıçları öylesine zorladı ki birkaçı öldü.",
["bm_msk_xm20_owl"] = "Bird Brain",
["bm_msk_xm20_owl_desc"] = "Bu maskenin içinde imza yok. Demek ki Eduardo Maquevera’nın kendisi değil, çıraklarından biri yapmış.",
["bm_msk_xm20_serpent"] = "Mayan Mosaic Death ",
["bm_msk_xm20_serpent_desc"] = "Bu maskeyi usta maske yapımcısı Eduardo Maquevera, San Diego’daki atölyesinde yaptı. Gerçekten ünlü bir zanaatkâr olarak film sektörünün büyük bölümüne maske ve aksesuar sağlıyor.",
["bm_msk_yor"] = "Fire Rooster",
["bm_msk_yor_desc"] = "Güvenilir bir kundakçısın; hep dakik, hep hedefte. Yeni yıl başlarken gözünü en soylu metal olan o parıldayan altına dikeceksin. Niyetlerin karanlık olabilir ama yedi muhteşemdir ve daha farkına varmadan kusursuz soygunu kutlamak için çak yapıyor olacaksın. Belki sonunda o sekiz numaralı bilardo topu dövmesini de yaptırırsın.",
["bm_msk_yufuhelmet"] = "Mountain Master Crown ",
["bm_msk_yufuhelmet_desc"] = "Wang gerçekten de ateş püskürten zorlu bir düşmandı. Mountain Master’ın elde dövülmüş bu tacı, zaferinin etkileyici bir simgesi olacak.",
["bm_msk_zipper"] = "The Zipper",
["bm_msk_zipper_desc"] = "Fermuar maskesi, aralarındaki sürgü çekilerek birbirine geçirilebilen veya ayrılabilen iki paralel diş dizisinden oluşur.$NL;$NL;İletişim kurman gerektiğinde fermuarı aç.",
["bm_msk_zombie"] = "The Zombie",
["bm_msk_zombie_desc"] = "Zombi, bir şekilde yeniden canlanmış hareketli bir cesettir.$NL;$NL;Beyin?",
["bm_msk_ztm"] = "The Almir",
["bm_msk_ztm_desc"] = "Bu maske bazılarına dehşet, bazılarına hayranlık verecek. Bu başlığı takmak için eşit ölçüde sakinliğe ve kaosa sahip olmalısın; suç çevrelerinde nadiren görülen biçimde bir araya gelen iki uç.$NL;$NL;The Almir, pek çok kişinin bir ekibe salmaya çekineceği bir maske. Onu takacak kadar çılgın biri bir gün büyük işler başarabilir, ertesi günse psikotik bir katliama girişebilir. Ama bazen zor durumdan çıkıp soygunu tamamen batırmamak için böyle birine ihtiyacın olur.$NL;$NL;Böyle birinin başarı getirme şansı kadar başarısızlık getirme şansı olduğunu bilerek, ekibine bir Almir almaya cesaret eder misin?$NL; ;)",
["bm_msl_sds_01"] = "Lust",
["bm_msl_sds_01_desc"] = "Gözlerin yaşarana kadar ödülüne kilitleniyorsun. Sahip olma ihtiyacı benliğini ele geçirirken gevşemiş çenenden yere bir damla salya düşüyor. Özlediğin kişi bir nesne, nesne bir kişi. Körleşmiş duyuların için hiç fark etmiyor.",
["bm_msl_sds_02"] = "Sloth",
["bm_msl_sds_02_desc"] = "Ne diye uğraşasın? Evren genişlesin, ölsün, kararsın. En ufak çaba göstermen gereken her anlamsız angaryayı protesto etmek için parmağını kıpırdatmaya sonsuz zamanın var. Sen sürekli hırstan yoksun kalırken yaşam enerjin ruhundan sızıp boşlukta eriyerek ziyan oluyor.",
["bm_msl_sds_03"] = "Envy",
["bm_msl_sds_03_desc"] = "Haksızlık, değil mi? Hayattaki her şeyi hak etmiş hâlde orada duruyorsun ama evren sana vermeyi reddediyor. Başkaları gülüp oynarken sen içine kapanıyor, herkese bedavadan verilen başarıyı neden kimsenin sana armağan etmediğini düşünüyorsun. Ah, öyle çok istiyorsun ki; ama almaya nasıl cesaret edebilirsin?",
["bm_msl_sds_04"] = "Wrath",
["bm_msl_sds_04_desc"] = "Kalbinde soğuk bir ateş var. Sana haksızlık eden herkes bedel ödeyecek. Yangında onlarla birlikte yanman gerekse bile sana yapılmış gerçek ya da hayalî her hakaretin hesabını soracaksın. Öfkenin mantığı yok; sadece doyurulmalı.",
["bm_msl_sds_05"] = "Pride",
["bm_msl_sds_05_desc"] = "Sen kırılmazsın. Gemi su alıyor ama kıpırdamayı reddediyorsun. İlkelerin öyle sağlam ki hatanı ve herkes kadar yanılabilir olduğunu kabul etmek yerine çöken bir kurumla derinlere inmeyi seçiyorsun. Adalet senin tanımladığın şeydir; haklı bilgeliğine karşı gelenlere de lanet olsun.",
["bm_msl_sds_06"] = "Gluttony",
["bm_msl_sds_06_desc"] = "İşte yine o bitmek bilmeyen, sürekli açlıktan ölüyormuşçasına vahşi bir hırsla tıkınıp karnını doyurma ihtiyacı. Durduğundaysa midende doyurulmayı bekleyen koca bir boşluk açılıyor sanki.",
["bm_msl_sds_07"] = "Greed",
["bm_msl_sds_07_desc"] = "Daha fazlası asla yetmez. Hiçbir altın veya hazine miktarı seni doyuramaz. Tek amaç, ister maddi ister manevi olsun, şişkin sandıklarına ekleyeceğin bir sonraki gereksiz servet yığınını elde etmektir. Acılarından kazanç sağlayabiliyorsan başkalarının çilesinin önemi yoktur.",
