["bm_mtl_wicker1"] = "Hasır",
["bm_paycheck_chains"] = "Paycheck Chains",
["bm_paycheck_chains_desc"] = "Paycheck Chains kafayı tamamen sıyırmak istiyor. Ama doğrusu, maskenin ardında ahlaksız yollardan geçinmeye çalışan sıradan bir adam var. Sıradanlığını deliliğe çevirmek için, bir soygunda polis gelince bir kanişi rehin aldı. Bunu ancak bir deli yapar, öyle değil mi? Ama bulaşmak için yanlış azgın iti seçmişti. Ekip bu yaratıktan kaçmayı başarana kadar köpek hepsini ısırdı. Soygunun ardından çıkan haberlerde köpeğin kuduz belirtileri gösterdiği söylendi. Belki de Paycheck Chains sonunda olmak istediği kadar delirir...",
["bm_paycheck_dallas"] = "Paycheck Dallas",
["bm_paycheck_dallas_desc"] = "Paycheck Dallas sonunda gizlenmek için siyah çöp poşeti kullanmaktan vazgeçti. Cesaretini toplayıp idolünü onurlandırmak için gerçek bir Dallas maskesi sipariş etti ama internetteki baskı hizmetinin gönderdiği şey pek aslına benzemiyordu... Yine de maskesiyle işi büyütmeye çalıştı ve Paycheck çetesini bir porselenci dükkânını basmaya ikna etti. Güvenlik kamerası görüntülerinde Paycheck Dallas’ın içeri dalarken en büyük vazoyu yanlışlıkla kırdığı görülüyor. Bunun üzerine dükkân sahibinden özür dileyip kasadaki bütün bozuklukları kaptı ve kapıya koştu. O sırıtan neon maskenin altında muhtemelen domates gibi kızarmıştı.",
["bm_sad_seal"] = "The Awkward Seal",
["bm_sad_seal_desc"] = "Bir Bulldozer’ın işini bitirmek üzereyken tetiği çekip mühimmatının bittiğini fark ettiğin o an. Ya da son çantayı doğruca denize attığın an. Ya da hiç uğraşmadığın maskene diğer soyguncuların iltifat ettiği an. Ya da seninle aynı anda birinin matkabı onardığı an.",
["bm_sfm_01"] = "Exalted",
["bm_sfm_01_desc"] = "Soğuk ve kıpırtısız, onları yukarıdan izliyorsun. Altın bakışın o zavallı yumuşakların üzerine hak etmedikleri bir lütuf gibi düştüğünde ihtişamını kıskanacaklar. Gecenin sert soğuğuyla güneşin göz kamaştıran ışıltısını birleştiriyorsun. Görkemli, altın ve güzel; arzuyla akıllarını başlarından alacak, sonlarını getireceksin.",
["bm_sfm_02"] = "Golden Hour",
["bm_sfm_02_desc"] = "Timothy Miller büyüyünce sinema ışıklandırmasında çalışmayı hayal ediyordu. Bir Cadılar Bayramı partisi için Golden Hour maskesini yaptı. Ama takıp aynaya baktığında gözleri, gün batımının kusursuz yumuşak kırmızı parıltısıyla çevriliydi. O an yeni bir hayal doğdu. İnsanların gün batımının huzurunu yakından görmesini, sonsuza dek retinalarına kazınmasını istedi. Adli tabibin doğrulayabildiği tek şey, tüm kurbanların gün batımından az önce öldüğü ve gözlerinin daima açık bırakıldığıydı.",
["bm_sfm_03"] = "Barrori Flex",
["bm_sfm_03_desc"] = "Chad’in Barrori Flex güneş gözlüğünü aldığı gün her şey değişti. Hayatta neyin önemli olduğuna yepyeni bir açıdan bakmasını sağladı. Havalı ve umursamaz görünmek amacı, yaşama nedeni oldu. İtalyan spor ceketi, bej keten pantolonu ve mokasenleriyle gittiği her yerde kıskanç bakışlar topluyor, başları döndürüyordu. Ama bu süremezdi. Chad’in güzelliği solunca yaşama isteği de soldu. En iyi kıyafetleriyle bir kutu diyet hapını yuttuğunda iyi görünümlü bir ceset oldu.",
["bm_sfm_04"] = "Panthera Tigris",
["bm_sfm_04_desc"] = "Kaplanın öfkesi dillere destandır; ormanın kralı kendi isteğiyle tutsak olmaz. Seni denetim altında tuttuklarını sanabilirler ama kafese kapatılmış bir kaplanın hiddetine hiçbir şey benzemez. Zincirlerini kırdığında bunu anlayacaklar. Krallığını geri alırken pençeler parçalayacak, dişler eti kemikten ayıracak.",
["bm_sha_01"] = "Ameonna",
["bm_sha_01_desc"] = "Kudretli boynuzlu iblis. İntikamcı, ağlayan yok edici. Onu öfkelendirme.",
["bm_sha_02"] = "Co-Cop Ninja",
["bm_sha_02_desc"] = "Hızlı vur, sert vur, sessiz vur. Cloaker’ları bile utanç içinde surat asar hâlde bırakacaksın.",
["bm_sha_03"] = "Thorntail",
["bm_sha_03_desc"] = "Saldırgan, acımasız, her yanı saran bir tehdide dönüş. Şehre girdiğinde ölüm seni ateş biçiminde izler.",
["bm_sha_04"] = "Hata Mari",
["bm_sha_04_desc"] = "Bıçakları havada uçuran hızlı ve çevik bir katil. Her an vurmaya hazır. Çok hayranı olan popüler bir katil.",
["bm_sm_wish"] = "The Death Sentence Skull",
["bm_sm_wish_desc"] = "İBLİS! İnsanlar yalnızca bir kısmını görseler bile bir insan kafatasını çoğu zaman tanıyabilirler. Hatta insan beyninde bunun için özel bir bölge bile var. Bu artık kesinlikle insan kafatası değil. İyi olmak için şeytani güçlerini çağırdığında böyle olur.$NL;$NL;Biz OVERKILL olarak şaşkınız, afalladık ve gerçekten etkilendik. Başardın. Vazgeçmeyip düşünebildiğimiz en zor zorluğu gerçekten tamamlayan az sayıda kişiden birisin. Savaştın, acı çektin ve direndin. Sonsuz saygımız seninle, iblislerin hükümdarı.",
["bm_sparkle_party"] = "Party Hat",
["bm_sparkle_party_desc"] = "Parti şapkalarının modası geçmez. İster suç dolu bir şenlik ister yeni eve taşınma kutlaması olsun, eğlenceli her etkinliğin vazgeçilmez aksesuarıdır. Birini tak, kravatını gevşet. Parti zamanı. Mükemmel.",
["bm_suit_badsanta"] = "Dirty Santa",
["bm_suit_badsanta_desc"] = "Kabul edelim millet; Santa bacanızdan bunu giyerek iniyorsa size güzel bir şey getirmeyecek. Üstelik sütle kurabiyeden fazlasını da götürebilir. Ama Bain’in eskiden dediği gibi: \"Almanın mevsimi geldi!\"",
["bm_suit_baron"] = "The Grand Octennial",
["bm_suit_baron_desc"] = "Kaç soyguncu işte sekiz başarılı yıl geçirdiğini söyleyebilir? Evet, sayı pek büyük değil. Ama sen hâlâ buradasın, değil mi? Hâlâ en iyiler gibi kasa açıp ganimet taşıyorsun. O yüzden bu anı tarzla, gösterişle kutla!",
["bm_suit_bikerjacket"] = "Hell on Wheels",
["bm_suit_bikerjacket_desc"] = "Kalın bir egzoz dumanı sisinden çıkıyorlar; sıcakta titreşen kâbus gibi bir serap. Metal ve kauçuktan kükreyen atlara binmişler, hızla geliyorlar. Sayılamayacak kadar çoklar. Karşı durulamayacak kadar güçlüler. Yolu aç, yoksa seni yolda ezilmiş leşe çevirirler.",
["bm_suit_bikerjacket_gray"] = "Bad to the Bone",
["bm_suit_bikerjacket_gray_desc"] = "Kötü olmak iyiyse sen en iyisisin.",
["bm_suit_bikerjacket_green"] = "Black Magic",
["bm_suit_bikerjacket_green_desc"] = "Kazadan sağ çıkmana mucize diyorlar ama doğrusu biraz daha ölü diriltmeye yakındı.",
["bm_suit_bikerjacket_red"] = "Fast Lane",
["bm_suit_bikerjacket_red_desc"] = "Tabii ki işaretleri görmedin! Çok hızlı gidiyordun.",
["bm_suit_bikervest"] = "Road Rage",
["bm_suit_bikervest_camo"] = "Royal Pain",
["bm_suit_bikervest_camo_desc"] = "Tahtın sahibine bulaşanın başı ağır gelir.",
["bm_suit_bikervest_desc"] = "Çoğu insan bunun hızla geçen bir tır gibi kaybolan şiddet dürtüsü, geçici bir durum olduğunu sanır. Ama sen yol öfkesinin gerçeğini biliyorsun: Bu bir yaşam biçimi. Senin için dünya on şeritli kocaman bir otoyol, trafik de kilitlenmiş. Sürüyle birlikte ağır ağır mı ilerleyeceksin? Yoksa dişini sıkıp gaza basacak, dövüşerek öne mi geçeceksin? Unutma: Biri yaralanırsa araba kullanmayı daha iyi öğrenmeliydi.",
["bm_suit_bikervest_red"] = "Arsonist",
["bm_suit_bikervest_red_desc"] = "Ateş seninle yürür.",
["bm_suit_bikervest_white"] = "Screw Loose",
["bm_suit_bikervest_white_desc"] = "Motosikletini tamir edebilirsin ama kendini edemezsin. Ne olmuş? Sen tamircisin, lanet bir psikiyatrist değil.",
["bm_suit_boss"] = "Saints & Sinners",
["bm_suit_boss_desc"] = "Düşününce Payday Gang’in işi biraz kolay. Soygunculukta büyüklüğe ve ganimete giden yollarındaki polisle, federallerle ve koyun sürüsüyle savaşmaları yeterli. Ara sıra tuhaflıkla karşılaşıyorlar elbette ama Saint's Row ekibinin uğraştığı türden değil. Cidden; uzaylılar, komplolar, cehenneme açılan geçitler mi? Bunca şeyle uğraşırken bir işi nasıl bitiriyorsun? Bu yüzden bir ünlü ekipten diğerine saygı göstergesi olarak bu kıyafetleri giyebilir, suç dünyasına iyi duygular yayabilirsin.",
["bm_suit_boss_suit"] = "Master's Mantle ",
["bm_suit_boss_suit_desc"] = "Geleneksel Zhongshan takımından esinlenen bu seçkin kıyafet, gerçek bir liderin havasını yayar.",
["bm_suit_bullranch_suit"] = "Trailblazer",
["bm_suit_bullranch_suit_desc"] = "Tarihi öncüler yazar. Şıklığı ve kullanışlılığı eşit ölçüde taşıyan bir kıyafetle yol açan kişi gibi görün. Büyük Bilinmez’de hava soğur; doğru ceket büyük fark yaratır. Bazen tek ihtiyacın üzerindeki kıyafetlerdir.",
["bm_suit_bunny"] = "Pink Hopper  ",
["bm_suit_bunny_desc"] = "Pembe bir tavşan kostümü mü? Neden olmasın? Kıyafetinle silahının tezatı göz kamaştıracak!",
["bm_suit_cable_guy"] = "Cable Guy",
["bm_suit_cable_guy_desc"] = "Belki \"birinin çocuk bakıcısını öldürmesi gerek\" diye düşünen türden biri olmak istiyorsun. Belki de yalnızca yönetim kurulu odasına fark edilmeden girip sabitlenmemiş her şeyi çalmak istiyorsun. Her iki durumda da bu takım işini görür.",
["bm_suit_candycane"] = "Ho Ho Heister",
["bm_suit_candycane_desc"] = "Noel Baba’nın elfleri greve çıktı! Bu yıl Kuzey Kutbu’nda oyuncak yapılmıyor! Hiçbir küçük soyguncunun çorabına kömür girmesin diye Noel Baba’nın kıyafetini giy, ülkenin dört bir yanındaki uslu bankalardan, kuyumculardan ve kasa depolarından \"bağış\" toplarken neşe yay ve ona yardım et!",
["bm_suit_cargocasual"] = "Urbanite",
["bm_suit_cargocasual_cassette"] = "Press Play",
["bm_suit_cargocasual_cassette_desc"] = "İyi bir müzik olmadan soygun olur mu?",
["bm_suit_cargocasual_desc"] = "Havalı ve rahat görünümün özü; şehirdeki soygunların keşfi için kusursuz bir kıyafet. İnsanlar seni görünce şöyle düşünecek: \"Şu adama bak! Banka kasasının tuş takımıyla bayağı ilgileniyor gibi. Kıyafetleri de müthiş! Acaba o gömleği nereden aldı? Keşke benim de böyle kıyafetlerim olsa...\"$NL;\"Banka kasası\" kısmının nasıl arada kaynadığını gördün mü?",
["bm_suit_cargocasual_monke"] = "Here First",
["bm_suit_cargocasual_monke_desc"] = "İlk insanlar Dünya’yı soymadan önce o muz çalıyordu.",
["bm_suit_cargocasual_texas"] = "State of Things",
["bm_suit_cargocasual_texas_desc"] = "Ee, nerelisin sen- Ha.",
["bm_suit_cartelboss"] = "Impresario",
["bm_suit_cartelboss_desc"] = "Bu kıyafetin beyaz ipliklerinin simgelediği ölüm, günahları peşlerine düştüğünde bütün kartel liderlerinin varacağı yerdir.",
["bm_suit_classyske"] = "The Skeletal Heister",
["bm_suit_classyske_desc"] = "Evet millet, yine yılın o zamanı geldi. Sıradan insanlar, bütün yıl giymeyi diledikleri çılgın kostümleri giyebiliyor! Ama biz soyguncuların böyle dertleri yok, değil mi? İstediğimizi istediğimiz zaman giyeriz. Yine de bayramın havasına kemikli bir şıklıkla katılmakta bir sakınca yok.$NL;$NL;Yaratıcı: Luke Millanta.",
["bm_suit_clown"] = "The Showman",
["bm_suit_clown_2"] = "The Decennial Celebration",
["bm_suit_clown_desc"] = "Dikkat dağıtmak soyguncunun en iyi aracı olabilir. Doğru kıyafet de bunu sağlayıp düşmanı ne olup bittiğini düşünmeye iter. \"Sirk mi gelmiş? Ne biçim palyaço silah taşır?\" Böyle düşününce bunu biraz tarz ve renkli gösterişle yapmaman için neden yok. Bu yüzden bu pek şık kıyafet var; sana kendini suçun prensi gibi hissettirecek.",
["bm_suit_clown_desc_2"] = "On yıllık soygunculuk. On. Yıl. Müthiş bir suç serisi. Bir on yıl daha gitmesine karşı bahis oynamazdık. Sen oynar mıydın?$NL;$NL;Konsept: Angusburgers.",
["bm_suit_contintental"] = "The Prime",
["bm_suit_contintental_desc"] = "Hoxton, New York’ta gece yaptığı bir infaz ters gidince üç polis arabasından kaçmak zorunda kalmıştı. Düşman kanına bulanmış hâlde maskesini ve silahını oluğa atıp saklanmak için en sevdiği gece kulübüne yöneldi. (Acilen içkiye de ihtiyacı vardı.) Yolda bu takımı bir mağazanın vitrininde gördü. O hâliyle gizlenemeyeceğini anlayan Hox içeri girip üstünü hızlıca değiştirdi. İlk polis arabası köşeyi döndüğünde Hoxton her zamanki zarafetiyle kulüp kuyruğundaki kadınlarla sohbet ediyordu. Araba yanından geçerken doğrudan projektöre baktı... Sürücü avını hiç tanımadı.",
["bm_suit_corl"] = "Crime Lord",
["bm_suit_corl_desc"] = "Gücün pek çok biçimi var. Düşmanlarına üstün gelmeni sağlayan kuvvet. Tek sözle başkalarını yönetecek nüfuz. Beş adım sonrasını düşünecek kurnazlık. Birinde ustalaşmak seni doğrudan zirveye taşıyabilir. Hepsinde ustalaşmaksa orada kalmanı sağlar.",
["bm_suit_cyberhoodie"] = "Cyberhoodie",
["bm_suit_cyberhoodie_desc"] = "Elektronik müzik havası taşıyan modern bir kapüşonlu yorumu.",
["bm_suit_cybertrench"] = "Cybertrench",
["bm_suit_cybertrench_desc"] = "Trençkotun kara film tarzını modern bir teknoloji havasıyla birleştirir.",
["bm_suit_darkprince"] = "Prince of Darkness",
["bm_suit_darkprince_desc"] = "The Devil için ayakkabı üretilmiyor. Asırlardır arıyor ama toynaklarına uyacak, Cehennem’deki uzun yürüyüşlerinin yakıcı sıcağına dayanacak bir marka yok. O şık yeleği ve ceketi bu yüzden giyiyor; umudu, yalınayaklığının utancından dikkatini başka yöne çekmek!",
["bm_suit_desperado"] = "The Avenging Gunman",
["bm_suit_desperado_desc"] = "Müzisyen kılığında dolaşan silahşorların hikâyeleri anlatılır. Adaletsizliğe karşı savaşan, bunu kendi yapamayan insanların yaşadığı trajedilerin intikamını alan silahşorlar. Evet, bu tanım Payday Gang’e pek uymuyor, değil mi?",
["bm_suit_dodsuit"] = "Pistolero Muerto",
["bm_suit_dodsuit_desc"] = "Bu kadar gösterişli bir silahşor toprağın altını hak etmez! Sombrerona toprak bulaşır! Düellolarla ilgili küçük bir sır: Vurulmak kaybettiğin anlamına gelmez. Yalnızca yeniden kalkamazsan kaybedersin.",
["bm_suit_elegantscarf"] = "Discerning Dandy",
["bm_suit_elegantscarf_desc"] = "Tarzı ve biraz gösterişi asla küçümseme. Bu haute couture parçası zarif bir izlenim bırakmanı sağlayacak. Planın ne olursa olsun onu uygularken muhteşem görüneceksin.",
["bm_suit_elfsuit"] = "Santa's Little Heister",
["bm_suit_elfsuit_default"] = "Evergreen",
["bm_suit_elfsuit_default_desc"] = "Noel ağaçları asla pes etmez.",
["bm_suit_elfsuit_desc"] = "Muhtemelen Naughty Elves’i hiç duymadın. Timmy de duymamıştı. Çok istediği model treni alabilmek için bütün yıl uslu durdu ama hediyeyi açar açmaz evin içine tükürmeye ve çöl farelerini mikrodalgaya koymaya geri döndü. Sistemi alt ettiğini sandı ama kimse Santa’yı alt edemez. Böyle saçmalıklar yaparsan Santa, oyuncaklarını geri çalmaları ve belki ibret olsun diye başparmaklarını kırmaları için Naughty Elves’i gönderir. Unutma: Uslular Listesi’ndeysen orada kal; yoksa Naughty Elves seni mahveder. Timmy’ye sor yeter.",
["bm_suit_elfsuit_red"] = "Holiday Spirit",
["bm_suit_elfsuit_red_desc"] = "Çobanpüskülüyle süslen, neşeyi eksik etme.",
["bm_suit_elfsuit_violet"] = "Naughty List",
["bm_suit_elfsuit_violet_desc"] = "Üzülme. En havalı insanlar hep bu listeye girer.",
["bm_suit_elfsuit_yellow"] = "Winter Sun",
["bm_suit_elfsuit_yellow_desc"] = "O sıcak kakaoyu bir piña colada ile değiştir!",
["bm_suit_enforcer_suit"] = "Red Pole",
["bm_suit_enforcer_suit_desc"] = "Golden Dagger’ın Red Poles üyelerinin giydiği, geleneksel öğeler taşıyan modern kesimli bir takım.",
["bm_suit_esport"] = "Track Suit",
["bm_suit_esport_desc"] = "İki parçalı takım elbise soyguna profesyonellik katar, korkmuş sivillere sakin bir otorite hissi verebilir ama pek kullanışlı veya rahat değildir. Bankayı kurşunlamak ya da kasa açmak gibi yorucu işlerde rahatlığın kıymeti büyüktür. Nice çetenin yüksek veya düşük rütbeli mafya üyelerinin, resmî ve törensel bir yanı gerekmeyen işleri yürütürken eşofmanı tercih etmesinin bir sebebi var.",
["bm_suit_fighterpilot"] = "Dive Bomber",
["bm_suit_fighterpilot_desc"] = "Pek bilinmeyen bir gerçek: Bile, 1. Dünya Savaşı’nın hava muharebelerine hayran! Dikkatli gözler, soygunlarda onu sık sık aslına uygun avcı pilotu üniformasıyla, helikopter yerine bir Avro 504 uçurduğunu hayal ederken yakalar. Gökten ölüm yağdırmak isteyen?",
["bm_suit_gangstercoat"] = "The Executor",
["bm_suit_gangstercoat_desc"] = "Bazı şeyler resmen \"gangster\" diye bağırır, değil mi? Bu tarz takım elbisenin tam doğru paltoyla birleşmesinde bir şey var. Parlak ve dayanıklı; soygunla geçen günün ya da gecen ne getirirse getirsin seni atlatmaya hazır. ",
["bm_suit_general"] = "The General",
["bm_suit_general_desc"] = "Surlardan dışarı bakıyorsun; bir elin kılıcında, diğeri kusursuz dikilmiş paltunun göğsünde. Adamların sana saygı duyuyor, düşmanların senden korkuyor. Dinle! Borular çalıyor! Haykırış yükseliyor! SAVAŞA! Ve... ÇATIRR! Ne? YİNE Mİ! Siktiğimin bozuk, işe yaramaz matkabı soyguncuyu huzur içinde hayal kurmaya bile bırakmıyor! Ama vay be... Ne şıksın.",
["bm_suit_gentleman"] = "The Long Gentleman",
["bm_suit_gentleman_desc"] = "Bazıları uzun paltoların 1990’larda demode olduğunu söyler. Ama Payday Gang modaya uymaz. Her şeyi havalı gösterebilirler.",
["bm_suit_ghostly"] = "Haunted",
["bm_suit_ghostly_desc"] = "Şunu söyleyeyim, hayalet kostümüne bayıldım. Uçuşan kumaşlar, sis bulutu falan, harika. Benim gibi akıllı birini kandırmaya yetmez ama polislerin ödü kopacak! Yalnız, sormadan edemeyeceğim... Yerden nasıl böyle yükseliyorsun? Adın neydi senin? Bu iş için beşinci birini tuttuğumuzu hatırlamıyorum.$NL;Hop, dostum! Gözlerin parlıyor! Nasıl... Şey... Aa... Hassiktir...",
["bm_suit_gunslinger"] = "Duelist",
["bm_suit_gunslinger_desc"] = "Yirmi adım mesafede düelloya tutuşma ihtiyacı hisseden soyguncu için kusursuz bir takım.",
["bm_suit_highinttech"] = "Ripstop Tactical",
["bm_suit_highinttech_desc"] = "Asya’da muhafızların, paralı askerlerin ve triad üyelerinin gözdesi bu hafif, taktik takım, Batılı benzerlerinden biraz daha iyi hareket kabiliyeti sunar.",
["bm_suit_hiphop"] = "The Boom Bap",
["bm_suit_hiphop_desc"] = "Ezilenlerin ritmi. Şehir içinin gürültüsünde sesini duyurmaya çalışan sokak şairlerinin düşüncelerinden doğan vahşi bir öfke. Gettonun sesleri sonsuza dek yankılanacak; toplumsal hapishanenin duvarları yıkılıp yeni bir günün kapılarını açacak.",
["bm_suit_hippie"] = "The Altamont",
["bm_suit_hippie_desc"] = "Bu modayken soygunculuk çok daha basitti. Ağlar değil, bıçaklarla insanlar kesilirdi; silahşorun, kasa hırsızının veya kaçış şoförünün saf becerisi daha da önemliydi.",
["bm_suit_jail_pd2_clan"] = "The Striped Troublemaker",
["bm_suit_jail_pd2_clan_desc"] = "Nasıl olduğunu biliyorsun. Bir kez söyle, iki kez söyle; üçüncüde olur. Ve unutma... çalmasını istediğin her şeyi çalar, hacklemesini istediğin her şeyi hackler. Adını söyle; seni gözaltından takasla çıkarır. Bain! Bain! B...",
["bm_suit_jumpsuit"] = "The Classic",
["bm_suit_jumpsuit_desc"] = "Kariyerini değiştiren bazı soygunlar, yanında getirdiğin ekipmandan çok daha fazlasını ister. Hareket kabiliyeti ve dayanıklılık, bir soyguncuyu kelepçeden kurtaran şeyler olabilir. Bu kıyafet de tam bunun için yapıldı. Güçlendirilmiş bir taktik yelekle tamamlanan tek parçalı temeli, çeşitli arazilerde rahatça hareket etmeni sağlar ve bolca taşıma olanağı sunar.",
["bm_suit_jun21_thug_black"] = "Dragon Bomber Black",
["bm_suit_jun21_thug_black_desc"] = "Bulutlu göğü yaran güneş gibi, küçük bir renk kıvılcımıyla ağırbaşlı.",
["bm_suit_kungfumaster"] = "Laohu Dashi",
["bm_suit_kungfumaster_desc"] = "Bu kıyafet, dövüş tarzını uygularken hız ve hareket özgürlüğü sağlar. Belalı zarafeti de inkâr edilemez.",
["bm_suit_leather"] = "The Unimatrix",
["bm_suit_leather_desc"] = "Daha masum bir zamana, 90’ların sonuna dönelim. Aksiyon kahramanları ekranda taklalar atarak uçuşur, mermi yağdırır ve her yana beton tozu saçardı. O günleri özlüyorsan bu takım tam sana göre.",
["bm_suit_leatherfluff"] = "Rough Streets",
["bm_suit_leatherfluff_bats"] = "Batty",
["bm_suit_leatherfluff_bats_desc"] = "Hafifçe ürpertici.",
["bm_suit_leatherfluff_desc"] = "Böyle bir ceketin fazla süse ihtiyacı yok. Ovaların bütün sertliğini, şehrin bütün tarzını taşıyor. Ama sen işi bir adım ileri götürmeyi seversin. Gösterişli bir şey değil; dünyaya kim olduğunu anlatacak küçük bir amblem. Sonuçta bir simge bin söze bedeldir.",
["bm_suit_leatherfluff_dots"] = "Lock & Stock",
["bm_suit_leatherfluff_dots_desc"] = "İyi avlar!",
["bm_suit_leatherfluff_lightning"] = "Thunderbolt",
["bm_suit_leatherfluff_lightning_desc"] = "Sisteme elektrik gibi çarp.",
["bm_suit_lonorwa"] = "Dead of Winter",
["bm_suit_lonorwa_desc"] = "Şık ve zarif, aynı zamanda sıcak ve rahat. Karlı ormanda veya kış sokaklarında pusu mu? Dert etme, hazırsın.",
["bm_suit_lowinttech"] = "Ripstop Casual",
["bm_suit_lowinttech_desc"] = "Asya’nın büyük metropollerinde popüler bir şehir kıyafeti. Dayanıklılığı ve hareket rahatlığı nedeniyle triad üyeleri ve diğer gangsterler sıkça tercih eder.",
["bm_suit_mar21_thug"] = "Dragon Bomber",
["bm_suit_mar21_thug_default"] = "Dragon Bomber Contrast",
["bm_suit_mar21_thug_default_desc"] = "Zengin çocukların lise futbol maçına bunu giyebilmek için anne babalarına yalvardığını biliyorsun.",
["bm_suit_mar21_thug_desc"] = "Hakkını vermek lazım. Bazı triad üyeleri, eskimiş gangster kıyafeti klişesini alıp gangsterlerin yaptığı vicdansız işler için gereken rahatlığı bozmadan yeniden havalı kılmayı iyi biliyor. Hem de hiç zorlanmadan. Bu, kötü bir 1970’ler Kung Fu filminde göreceğin türden değil. Hiç değil. Modern kesim, uzay çağı kumaşları, ne ararsan var.",
["bm_suit_mar22_thug_white"] = "Dragon Bomber White",
["bm_suit_mar22_thug_white_desc"] = "Bunu taşıyacak kadar zarifsen muhtemelen soygun sırasında kıyafetlerine kan bulaştırmamakta da ustasındır.",
["bm_suit_mariachi"] = "The Minstrel",
["bm_suit_mariachi_desc"] = "Gerçek bir mariachi takımı yapmanın incelikleri küçümsenmemeli. Bazıları aldatıcı derecede sade görünür ama altında çoğu zaman nesilden nesile aktarılan karmaşık bir ustalık yatar.",
["bm_suit_miami"] = "The Sunny Rico",
["bm_suit_miami_desc"] = "Korunmak, elbette mermileri durdurmak kadar fark edilmemekle de ilgilidir. 1980’ler tarzı takım elbiselerin bol kıvrımları silahları gizlemek için geniş alan sunar. Kumaş çeşitliliği de gerektiğinde hava koşullarına uyum sağlamanı sağlar. ",
["bm_suit_mocow"] = "Western Chic",
["bm_suit_mocow_desc"] = "Amerikan kovboyunun o ikonik fiyakası var, pisliği ve hayvan kokusu yok. Dans kulübünde de Eski Batı salonunda da hoş karşılanırsın.",
["bm_suit_moneysuit"] = "Cash Flow",
["bm_suit_moneysuit_default"] = "Money Laundering",
["bm_suit_moneysuit_default_desc"] = "Parayı al ve KAÇ!",
["bm_suit_moneysuit_desc"] = "İlk soygunumdu, tamam mı? Kuş uçmaz kervan geçmez bir yerde minicik bir banka şubesi. Kasada çok para olmaz, sadece veznelerden toplarız diye düşünüyorum. İki ganimet çantası hayli hayli yeter. Meğer düşündüğümden çok daha fazla vezne varmış. Hem bu küçücük banka pek de küçük değilmiş; kasa ağzına kadar dolu! Ama beni bilirsin, geride tek dolar bırakmam. Kendi çantalarımı, bankanın çantalarını, sivillerden alabildiğim bütün el ve sırt çantalarını doldurduktan sonra gömleğimle iç çamaşırımı çıkarıp... şey... yaratıcı davrandım.$NL;Güneş görmeyen yerlerimde birkaç kâğıt kesiği oldu ama değdi!$NL;",
["bm_suit_moneysuit_gold"] = "Gold Standard",
["bm_suit_moneysuit_gold_desc"] = "Açgözlülüğün insanın ruhunu yakan ateş olduğunu söylerler ama üzerinde iyi duruyor.",
["bm_suit_moneysuit_money"] = "Dress for Success",
["bm_suit_moneysuit_money_desc"] = "Aşağı yukarı bir milyon dolar gibi görünüyorsun. Umarım yağmur yağmaz.",
["bm_suit_murky_suit"] = "Murkywater Uniform",
["bm_suit_murky_suit_desc"] = "Murkywater paralı askerlerinin kullandığı bir askerî üniforma. Üzerinde Murkywater logolu bir arma bulunur.",
["bm_suit_newhorizon"] = "New Horizon",
["bm_suit_newhorizon_desc"] = "Yeni bir çağ doğuyor. İttifaklar kuruldu. Yollar belirlendi. Uzaktaki o ateşli parıltı giderek güçleniyor.$NL;$NL;Sıradakine hazır mısın?",
["bm_suit_nightwalker"] = "The Count",
["bm_suit_nightwalker_desc"] = "Gecenin ölümsüz bir yaratığı olarak pek çok moda akımının gelip geçtiğini gördün. Bazı görünümler zamana daha iyi dayanır ama hiçbir şeyin yaşayan bir ölüye 18. yüzyıl aristokratının zarif inceliği kadar yakışmadığını bilirsin. Sen klas bir kan emicisin!",
["bm_suit_none"] = "Default Outfit",
["bm_suit_none_desc"] = "Bu, soyguncunun seçili zırhla giydiği varsayılan kıyafettir.",
["bm_suit_oct21_thug_red"] = "Dragon Bomber Red",
["bm_suit_oct21_thug_red_desc"] = "Bazıları bu takımın kırmızı kollarının, düşmanın dikkatini ayaklarının yaptığından uzaklaştıracağını söyledi. Yeni bir fikir ama belki de körü körüne güvenmeye değmez!",
["bm_suit_overkillpunk"] = "Boardroom Havoc",
["bm_suit_overkillpunk_desc"] = "Biraz sertlik katılmış şehirli tavır nadiren yanıltır. Üstelik altında kusursuz bir gömlek ve kravatla hemen her duruma hazırsın. Başka bir deyişle, öldürmek için giyindin.",
["bm_suit_peacoat"] = "The Casual Formal",
["bm_suit_peacoat_desc"] = "Bir soyguncunun kıyafeti bazen hem belli ölçüde resmî ve saygın hem de rahat ve işe uygun olmalıdır. Bu kot alt parça ile daha ciddi üst parçanın birleşimi, iki dünyanın en iyi yanlarını bir araya getirir.",
["bm_suit_poolrepair"] = "Repairman",
["bm_suit_poolrepair_desc"] = "Kararsızsan hep tamirci yolunu seç. Sayısız bayağı filmdeki en akılsız kurgu, adi imaların kaynağı olabilir ama hemen her yere girmeni sağlar. Çoğu kişi tuvaletini veya televizyonunu kullanamazsa çıldırır; zenginlerinse havuzları hep kusursuz olmalı. Havuzcu kadın veya erkek genellikle hoş karşılanır. Bol cebi ve dar alanlarda hareket esnekliğiyle oldukça kullanışlı bir kıyafet de. Kasa açmak için su çekmen gerektiğinde de kim itiraz edecek?",
["bm_suit_puffervest"] = "Invested",
["bm_suit_puffervest_blue"] = "Nightlife",
["bm_suit_puffervest_blue_desc"] = "Güneş batınca yelek giyilir.",
["bm_suit_puffervest_desc"] = "Havalı bir şehirde yaşıyorsun ama hava soğumaya mı başladı? Yelek giy! Kamp ateşi partisine mi gidiyorsun? Yelek! Gitar çalan bir zaman yolcusu musun? Turuncu yelek! Yelekler harika. Sıcak tutarlar, iyi görünürler, hatta bazıları can yeleği olarak da kullanılabilir.",
["bm_suit_puffervest_grey"] = "Rugged",
["bm_suit_puffervest_grey_desc"] = "Sadece sana bakarak anlayamazlar.",
["bm_suit_puffervest_red"] = "Northside",
["bm_suit_puffervest_red_desc"] = "İyi görünmek ve sıcak kalmak birbirini dışlamaz.",
["bm_suit_punk"] = "The Vicious",
["bm_suit_punk_desc"] = "Punk rock ceketi ve pantolonu, \"kibar\" toplumun yerleşik kurallarına meydan okuyarak gururla giyilen bir zırhtır. Gerçek bir punk ceketinin her zımbası emekle, elle takılır. Yine elle yapılan her boya süslemesinin, giyen kişi için derin bir anlamı vardır. Tabii bütün dünyaya çekilmiş kocaman bir siktir değilse.",
["bm_suit_railroad"] = "Trainmaster",
["bm_suit_railroad_desc"] = "Bir lokomotiften daha güçlü kimdir? Onu yöneten kişi. Trenin ne zaman kalkacağına, ne kadar hızlı gideceğine, biri için duracaksa kimin için duracağına sen karar verirsin. İstesen bütün operasyonu raydan çıkarabilirsin ama yapmıyorsun. Seni başa bu yüzden koydular.",
["bm_suit_raincoat"] = "Raincoat",
["bm_suit_raincoat_desc"] = "Giyeni kuru tutan klasik sarı bir yağmurluk. Parlak rengi, şiddetli yağmurun görüşü bozduğu durumlarda trafik güvenliğini de artırır.",
["bm_suit_rusbear"] = "Dogsled Master",
["bm_suit_rusbear_desc"] = "Soygun yaparken donacaksın diye bir kural yok. Bununla hem iyi görünür hem rahat eder hem de soygunlarına devam edersin.",
["bm_suit_scrub"] = "Scrubs",
["bm_suit_scrub_desc"] = "Hastanede görev yapan bir cerrahın giydiği türden koruyucu kıyafet. Cerrahi kıyafetlerde genellikle hem sakinleştiren hem de kan ve diğer vücut sıvılarının lekelerini personelin kolayca fark etmesini sağlayan renkler kullanılır.",
["bm_suit_slaughterhouse"] = "Legacy Tactical",
["bm_suit_slaughterhouse_desc"] = "İyi bir taktik yeleğe ve muharebe pantolonuna asla hayır deme. Bol cepli olsun. Asla fazla cep olmaz. Payday gang kariyerinin başlarında Chains, bu takımı oluşturmak, denemek, ayarlamak ve soygunda en iyi performansı vereceğinden emin olmak için neredeyse iki ay uğraştı. Bunca yıl sonra pek az değişti ve fiziksel açıdan zorlu soygunlarda hâlâ gözde kıyafetlerden biri.",
["bm_suit_sneak_suit"] = "Tactical BDU",
["bm_suit_sneak_suit_desc"] = "Bu bir gizlilik kıyafeti. Sessiz hareket için rahattır; yumuşak, siyah malzemesi gece operasyonlarında karanlığa karışmayı sağlar. Mühimmat ve ekipman için cepleri vardır.",
["bm_suit_sparkle"] = "Overgold ",
["bm_suit_sparkle_desc"] = "İşte fark edilmek, gösterişli bir izlenim bırakmak mı istiyorsun? Evet, yolu bu.",
["bm_suit_t800"] = "Infamy Leather",
["bm_suit_t800_desc"] = "Ek bir deri katmanı her zaman iyi fikirdir. Bir de bu kadar iyi görünüyorsa en budala adam bile sana bulaşmadan önce iki kere düşünür.",
["bm_suit_texvest"] = "Rough Rider",
["bm_suit_texvest_black"] = "Midnight",
["bm_suit_texvest_black_desc"] = "Karanlık vardır, aysız bozkır gecesi kadar karanlık vardır, bir de sen varsın.",
["bm_suit_texvest_blue"] = "Chill",
["bm_suit_texvest_blue_desc"] = "Baskı arttığında bile soğukkanlılığını korursun.",
["bm_suit_texvest_desc"] = "Zorlu arazide de atından inmez, üstelik iyi görünürsün. Kovboy, azmin efsanevi bir simgesi olarak dimdik durur; hem de yakışıklı bir simgesi. Bu kıyafet Eski Batı’da işe yarıyordu, bugün de bal gibi yarar. Modern kovboy ataları kadar korkusuzdur, sadece biraz daha şıktır. Biraz tarzdan zarar gelmez ortak.",
["bm_suit_texvest_green"] = "Woodland",
["bm_suit_texvest_green_desc"] = "Köklerini hatırla.",
["bm_suit_tstp_hitman"] = "Wushu",
["bm_suit_tstp_hitman_blue"] = "Wushu Blue",
["bm_suit_tstp_hitman_blue_desc"] = "Keyifsizliğe kapılma; avını indirirken ruh hâlini maviyle ifade et!",
["bm_suit_tstp_hitman_brown"] = "Wushu Brown",
["bm_suit_tstp_hitman_brown_desc"] = "Ortamla kaynaşman gereken ama bunu yine de tarz sahibi yapmayı istediğin pis arka sokaklardaki infazlar ve soygunlar için!",
["bm_suit_tstp_hitman_default"] = "Wushu Grey",
["bm_suit_tstp_hitman_default_desc"] = "Yağmurlu bir günde iş gören usta tetikçi için.",
["bm_suit_tstp_hitman_desc"] = "İşindeki becerisini sanata dönüştürmekle övünen soyguncu veya tetikçi için bu kıyafet tam aranan şey olabilir. Geleneksel kesim ve gösterişsiz kumaşlar, en yeni taktik lif teknolojisiyle buluşuyor. Yağmura bile dayanır!",
["bm_suit_tstp_hitman_red"] = "Wushu Red-Gold",
["bm_suit_tstp_hitman_red_desc"] = "Kurbanının hatırlayacağı son şey, retinasına kazınan bu kumaşın muhteşem görünüşü olacak. Tabii arkadan indirmeye karar vermezsen. Böylesine gösterişli bir kıyafeti gizlice saklamak biraz ziyan olmaz mı?",
["bm_suit_tstp_traditional"] = "Triad Casual",
["bm_suit_tstp_traditional_blue"] = "Triad Casual Blue",
["bm_suit_tstp_traditional_blue_desc"] = "İsveç kralı, Çinli bir tetikçinin kıyafetini giymek isteyen bir soyguncu olsaydı bunu seçebilirdi!",
["bm_suit_tstp_traditional_brown"] = "Triad Casual Patterns",
["bm_suit_tstp_traditional_brown_desc"] = "70’lerin havasını hissetmek ama modern bir dokunuşu da korumak isteyen soyguncular için.",
["bm_suit_tstp_traditional_default"] = "Triad Casual Grey",
["bm_suit_tstp_traditional_default_desc"] = "Kalabalıkta dikkat çekmek istemeyen soyguncu için sakin tonlar.",
["bm_suit_tstp_traditional_desc"] = "Sert, adam döven, kaçak mal taşıyan bir triad gangsterinin bile ara sıra arkasına yaslanıp rahatlaması gerekir. Ama kötüler uyuyamaz; o yüzden işler sarpa sardığında dayanacak bir şeyi hep el altında tutmalısın. Mesela dolandırdığın uyuşturucu baronu kapını kırarken. İşte bu bir seçenek; durumun ne olursa olsun tarzını korumanı sağlar!",
["bm_suit_tstp_traditional_red"] = "Triad Casual Red",
["bm_suit_tstp_traditional_red_desc"] = "Kırmızı ve siyah birleşimi asla yanıltmaz.",
["bm_suit_tux"] = "Tuxedo",
["bm_suit_tux_desc"] = "Resmî davetler için geleneksel bir smokin. Kendine özgü siyah beyaz tasarımını karakteristik siyah papyon tamamlar.",
["bm_suit_var_baron_blue"] = "The Grand Octennial Marine",
["bm_suit_var_baron_blue_desc"] = "Kutlamayı gece yarısı yapmayı tercih eden soyguncuya.",
["bm_suit_var_baron_default"] = "The Grand Octennial Red",
["bm_suit_var_baron_default_desc"] = "Kızıl güneş doğarken kutlamayı tercih eden soyguncuya.",
["bm_suit_var_bikerjacket_suit_default"] = "Route 66",
["bm_suit_var_bikerjacket_suit_default_desc"] = "Amerika’nın Ana Caddesi sekiz farklı eyaletten geçer. En büyüğünün hangisi olduğunu tahmin et.",
["bm_suit_var_bikervest_default"] = "Reckless",
["bm_suit_var_bikervest_default_desc"] = "Hızlı yaşa, daha hızlı sür. Ölüm yalnızca bir pit molasıdır.",
["bm_suit_var_boss_suit_default"] = "Dark Master ",
["bm_suit_var_boss_suit_default_desc"] = "İntikam zamanı geldiğinde bu takım tam yerini bulur.",
["bm_suit_var_boss_suit_green"] = "Pond Master ",
["bm_suit_var_boss_suit_green_desc"] = "Sinsi, yüzeyin altında bekleyen bu kıyafetin sahibi; saldırı vakti gelene dek gerçek gücünü saklamanın değerini bilir.",
["bm_suit_var_boss_suit_red"] = "Red Master ",
["bm_suit_var_boss_suit_red_desc"] = "Şık ve talihin damgasını taşıyan bu takım her ortama uyar.",
["bm_suit_var_boss_suit_yellow"] = "Golden Master ",
["bm_suit_var_boss_suit_yellow_desc"] = "Ne de olsa altın üstün metaldir. Öyleyse neden gösterişli, süslü bir desene dokunmuş hâlini giymeyesin?",
["bm_suit_var_bullranch_suit_black"] = "Rogue",
["bm_suit_var_bullranch_suit_black_desc"] = "Bazen yeni yollar açmak için bazı kuralları çiğnemek gerekir.",
["bm_suit_var_bullranch_suit_blue"] = "Denim",
["bm_suit_var_bullranch_suit_blue_desc"] = "İşler zorlaşınca güçlüler kot giyer.",
["bm_suit_var_bullranch_suit_brown"] = "Classic",
["bm_suit_var_bullranch_suit_brown_desc"] = "Öncü ruhu senin içinde yaşıyor.",
["bm_suit_var_bullranch_suit_default"] = "Modern",
["bm_suit_var_bullranch_suit_default_desc"] = "Değişmeyen tek şey değişimdir.",
["bm_suit_var_cargocasual_suit_default"] = "Gray Area",
["bm_suit_var_cargocasual_suit_default_desc"] = "Doğru ve yanlışın sınırlarının dışında yaşıyorsun.",
["bm_suit_var_classyske_cream"] = "Boney Blues",
["bm_suit_var_classyske_cream_desc"] = "Her ekim geldiğinde yaban mersinli turta ve bir parça vanilyalı krema, balkabağı turtasına güzel bir alternatiftir. Senin zevkin buysa bu takımla kemikli tarzına bürün.$NL;$NL;Yaratıcı: Luke Millanta.",
["bm_suit_var_classyske_default"] = "Black to the Bones",
["bm_suit_var_classyske_default_desc"] = "Evet millet, yine yılın o zamanı geldi. Sıradan insanlar, bütün yıl giymeyi diledikleri çılgın kostümleri giyebiliyor! Ama biz soyguncuların böyle dertleri yok, değil mi? İstediğimizi istediğimiz zaman giyeriz. Yine de bayramın havasına kemikli bir şıklıkla katılmakta bir sakınca yok.$NL;$NL;Yaratıcı: Luke Millanta.",
["bm_suit_var_classyske_red"] = "Bone Blood Bonanza",
["bm_suit_var_classyske_red_desc"] = "Bütün yıl kâbus fabrikasında yaşamak mı istiyorsun? Buyur, durma. Kan sıçramalarından bir türlü uzak duramayan soyguncular için bu kıyafet iş görür. Yalnız vampirlere ve boğalara dikkat!$NL;$NL;Yaratıcı: Luke Millanta.",
["bm_suit_var_clown_2_default"] = "The Most Majestic Clown",
["bm_suit_var_clown_2_default_desc"] = "Bain’le tanışmadan önce, Dallas saklanıp Chains’in atış poligonunu işletmesine yardım ederken yaşayan en başarılı soyguncu olacağını hiç düşünmemişti. Ama yılmadı, çizgisini bozmadı ve hâlâ dimdik ayakta. Bu takım bazılarına saçma görünebilir ama soyguncu bir palyaço onu gururla taşıyabilir.$NL;$NL;Konsept: Angusburgers.",
["bm_suit_var_clown_2_orange"] = "The Coolest Clown",
["bm_suit_var_clown_2_orange_desc"] = "Silah uzmanı, tatlı dilli, hazırcevap bir şair; Chains’in pek çok marifeti var. Dallas, Payday Gang’in beyniyse Chains de kalbidir. Soygunculukta on yılı kutlarken bu takımı sevgiyle giy!$NL;$NL;Konsept: Angusburgers.",
["bm_suit_var_clown_2_white"] = "The Crazy Clown",
["bm_suit_var_clown_2_white_desc"] = "Wolf’un elinde olsa bu takımın içini memleketi İsveç’ten gelen yünle kaplardı. Ama DC ve çoğu soygun yerinin havası bunu pek kullanışsız kılardı. Yine de yapsaydı adını \"Kaşınan Palyaço\" olarak değiştirmesi gerekebilirdi. Bu da pek şık duyulmuyor, değil mi?$NL;$NL;Konsept: Angusburgers.",
["bm_suit_var_clown_2_yellow"] = "The Most Suave Clown",
["bm_suit_var_clown_2_yellow_desc"] = "Sheffield’dan Londra’ya, karanlık arka sokaklarda iş çevirdiği ilk yıllardan beri Hoxton’ın kaderinde daha büyük işler vardı. Payday Gang ile on yıldan sonra (parmaklıklar ardındaki o küçük arayı saymazsak) bu palyaçonun yıldızı hâlâ yükseliyor. Bu da onun takımı.$NL;$NL;Konsept: Angusburgers.",
["bm_suit_var_clown_black"] = "Vintage Black",
["bm_suit_var_clown_black_and_white"] = "The Black & White Split",
["bm_suit_var_clown_black_and_white_desc"] = "Sol ve sağ, ölüm ve yaşam, haz ve bölünmüş bir kişilikle dolaşmanın getirdiği bitmek bilmez zihinsel eziyet. Eh, en azından tartışacak birini hep bulursun...",
["bm_suit_var_clown_black_desc"] = "Bir varmış bir yokmuş, neşeli bir hırsız çetesinin üyesi Küçük Yaşlı Wolf varmış. Wolf pek öfkeli, dengesiz bir adammış; şiddet nöbetleri geçirir, küçük yaşlı kadınların kılığına girer, altın için yanıp tutuşurmuş. Bir gün Wolf’un aklına bir fikir gelmiş. Siyah kadife bir takım çalıp yerel üniversitedeki bir derse sızmaya çalışmış; servetinden ayırabileceği bir sürü zengin olacağını düşünmüş. Ama ne yazık ki girerken bahçıvana çatmış. Bahçıvan alarmı verince Wolf mağarasına kaçmak zorunda kalmış.",
["bm_suit_var_clown_default"] = "Disturbing Violet",
["bm_suit_var_clown_default_desc"] = "Hiçbir yerden çıkıp şehre geldi. Tanınmayan bir psikopat. Adını veya kökenini kimse bilmiyor. Söylentiye göre bir gangsteri kalemle öldüren ilk kişiymiş. Onunla konuşma fırsatı bulursan bu söylentiye inanırsın. Peki kıyafetleri... bir delinin mi, yoksa tiyatro dehasının mı kıyafetleri? Karar senin.",
["bm_suit_var_clown_red"] = "The Crimson Comic",
["bm_suit_var_clown_red_desc"] = "Soyguncu, kendisinden önce nice ünlü haydudun giydiği takımı üzerine geçirdi. Böylesine kişisel bir maskeyle, bir palyaço için bile büyük beklentilerdi bunlar. Ama hayat onu o kadar çok kez döve döve sindirmişti ki buna hazırdı. Peki kimdi bu soyguncu? Nişan alan polisler için anında hedef tahtasına dönüşecek kadar renkli bir takım giymeye kim cesaret ederdi?",
["bm_suit_var_clown_white"] = "Professor White",
["bm_suit_var_clown_white_desc"] = "Duke’un bir üniversite hocası hep renkli yelek ve gömleklerle beyaz takım elbise giyerdi. Nadir sanat eserleri alıp üniversite müzesine veren büyük bir kaçakçılık ağına karıştığı ortaya çıkınca bir tür akıl hocasına dönüştü. Haber duyulduğunda skandal büyüdü; üniversite neredeyse battı. İyi niyetli ama son derece yasa dışı planları bozulan profesör kayboldu ve bir daha haber alınamadı. Duke bazen anısını yaşatmak için onunkine benzeyen bu takımı giyer. ",
["bm_suit_var_cyberhoodie_default"] = "Cyberhoodie Black",
["bm_suit_var_cyberhoodie_default_desc"] = "Elektronik müzikle karanlık iç içe.",
["bm_suit_var_cyberhoodie_mnt"] = "Cyberhoodie Red",
["bm_suit_var_cyberhoodie_mnt_desc"] = "Siber yolları hacklerken kıpkırmızı yan.",
["bm_suit_var_cyberhoodie_tgr"] = "Cyberhoodie Yellow",
["bm_suit_var_cyberhoodie_tgr_desc"] = "Bu kapüşonlunun rengi sarı olabilir ama cesareti tam!",
["bm_suit_var_cyberhoodie_vpr"] = "Cyberhoodie Green",
["bm_suit_var_cyberhoodie_vpr_desc"] = "Ormanda kapüşonlu giymen gerektiği hâlde tarzından ödün vermek istemediğin anlar için.",
["bm_suit_var_cybertrench_default"] = "Cybertrench Monochrome",
["bm_suit_var_cybertrench_default_desc"] = "Modern görünümü eski usul bir televizyonla buluşturuyor.",
["bm_suit_var_cybertrench_mnt"] = "Cybertrench Red Pinstripe",
["bm_suit_var_cybertrench_mnt_desc"] = "Kenarlar alev alev kalsın.",
["bm_suit_var_cybertrench_tgr"] = "Cybertrench Yellow",
["bm_suit_var_cybertrench_tgr_desc"] = "Siyah bir ekranın ortasındaki altın renkli piksel çizgisi gibi.",
["bm_suit_var_cybertrench_vpr"] = "Cybertrench Green",
["bm_suit_var_cybertrench_vpr_desc"] = "Asit gibi çarpıcı bir izlenim bırak.",
["bm_suit_var_desperado_blue"] = "Bad Blue Hombre",
["bm_suit_var_desperado_blue_desc"] = "Dallas sahneye yürüyüp gitarı sahibinin elinden kaptı. Gitarcı itiraz etmeye başladı ama soyguncunun seni-geberteceğim bakışı onu susturmaya yetti. Dallas sapı sıkıca kavrayıp bara yöneldi; deri yelekli bir serseri orada genç bir kızı taciz ediyordu. Kimse tepki veremeden Dallas gitarı serserinin kafasında parçaladı. Adam çığlıklarla yere düşerken tahta kıymıkları yüzünde derin yarıklar açtı. Dallas gitmek üzere döndü, o sırada ortadaki bir içki şişesini de kapıp kanlar içindeki serseriyi yerde baygın bıraktı. Şövalyelik öldü diyen kim?",
["bm_suit_var_desperado_default"] = "Dark Gunslinger",
["bm_suit_var_desperado_default_desc"] = "Rust saldırganıyla yüz yüze duruyordu. İki adam da rakibinin silahının namlusuna bakıyordu. Güneş alınlarına vururken zaman durmuştu. Rust, silah tutan avucundaki teri hissederek tetik parmağını dikkatle oynatmaya başladı. Birden silahşorların arasına bir karga kondu. İkisine de baktı; sanki sonraki birkaç dakikada kimin hayatta kalacağına karar veriyordu. Başını eğip Rust’a gakladı. Rust tetiği çekerek rakibinin işini bitirdi.",
["bm_suit_var_desperado_green"] = "The Sage",
["bm_suit_var_desperado_green_desc"] = "Sangres çocukken gezgin bir mariachi grubu kasabasına gelmişti. Trompetçiye hayran kalan Sangres, cesaretini toplayıp yanına gitti; bir gün nasıl müzisyen olabileceğini sordu. Mariachi dedi ki: \"Çalışmalısın küçük adam. Her gün, bütün gün. Hayatın, ruhun, sevgilin olmalı.\" Sangres hiç mariachi olmadı ama farklı... kariyerleri boyunca müzisyenin öğüdünü aklından çıkarmadı.",
["bm_suit_var_desperado_red"] = "Blood Marker",
["bm_suit_var_desperado_red_desc"] = "Silahşor yere düştü; son nefesi çatlamış, kuru topraktan kum kaldırdı. Yakındaki bir akrep, ölüşünü kayıtsızca izledi. Akbabalar tepede dönmeye başlarken cesedin üzerine bir gölge düştü; tanınmayan biri üstüne eğildi. Yıpranmış, kösele gibi bir el uzanıp silahşorun tabancasını aldı. Soğuk mavi gözler aşınmış silah çeliğini inceledi. Gözlerin sahibi memnuniyetle doğrulup yürüdü, ufukta kayboldu.",
["bm_suit_var_desperado_white"] = "Silverado",
["bm_suit_var_desperado_white_desc"] = "Bir yanında kılıfı, omzunda gitarıyla yalnız bir atlı kasabaya girdi. Beyaz takımının yıpranmış etekleri, tozlu yollarda uzun bir yolculuk anlattı. Atının yanında, adımlarına uyarak bir çakal yürüyordu; uzun bacaklarıyla toprağa ağır ağır basıyordu. Adam döküntü bir barın önünde durup silahını çekti, açık kapıdan içeri nişan aldı. Ateş etti. Bir çığlık duyulunca çakal içeri fırladı. Birkaç saniye sonra serseri görünüşlü birinin cesedini sürükleyerek döndü. Adam attan inip cansız bedeni atın arkasına attı, şerifin ofisine doğru yola koyuldu...",
["bm_suit_var_enforcer_suit_blood"] = "Traditional",
["bm_suit_var_enforcer_suit_blood_desc"] = "En popüler sürümlerden biri. Siyah beyaz asla yanıltmaz... Yalnız beyaza kan bulaştırma.",
["bm_suit_var_enforcer_suit_default"] = "Greyhound",
["bm_suit_var_enforcer_suit_default_desc"] = "Bu sürüm daha sade; kalabalığa karışmak istediğin zamanlar için ideal.",
["bm_suit_var_enforcer_suit_dragon"] = "Ceremonial",
["bm_suit_var_enforcer_suit_dragon_desc"] = "Ölüm kalım savaşına şık gitmek istiyorsan her zaman resmiyete bağlı kalabilirsin.",
["bm_suit_var_enforcer_suit_red_dragon"] = "Ritual",
["bm_suit_var_enforcer_suit_red_dragon_desc"] = "İster ölümüne bir düello, ister şiddetli bir çatışma, ister önemli bir pazarlık olsun; bu çeşit seni yarı yolda bırakmaz.",
["bm_suit_var_esport_black"] = "Chains Centurions",
["bm_suit_var_esport_black_desc"] = "İlginç bir bilgi: Vlad’ın yarı sarhoş hâlde kasa satarak herkesi nasıl zengin edeceğini bitmek bilmeden anlattığı toplantıdan sonra Chains eski eşofmanını atıp bunu aldı.",
["bm_suit_var_esport_default"] = "Dallas Destroyers",
["bm_suit_var_esport_default_desc"] = "İlginç bilgi: Dallas, suç kariyerinin başlarında bağlı olduğu Chicago mafyası ilk kez birini öldürmesini emrettiğinde bu kıyafeti giyiyordu. Hedefin genç bir kadın muhbir olması içine sinmedi. Sonunda örgüte ihanet etmesine yol açan buydu.",
["bm_suit_var_esport_green"] = "Wolf Woofers",
["bm_suit_var_esport_green_desc"] = "İlginç bir bilgi: Wolf’un, İsveç’in kuzeyindeki Kiruna şehrinin dışında, ormanın içinde bir kütük evi var. Yılda bir kez oraya dönüp ormanda koşmaya çalışır. (Wolf koşuya çıktığında ayıların bile saklandığı söylenir!)",
["bm_suit_var_esport_white"] = "Houston Hounds",
["bm_suit_var_esport_white_desc"] = "İlginç bir bilgi: Dallas suç kariyerine başlarken Houston, Atlanta dışında Chains’in sık uğradığı bir atış poligonu işletiyordu. Dallas Chicago’da çalıştığı mafyaya ihanet edip saklanmak zorunda kalınca Houston onu yanına aldı, poligondan iş yürütmesine izin verdi. Bu, Houston’ın hayatında kendini ağabeyinden bağımsız hissettiği tek dönemdi.",
["bm_suit_var_esport_yellow"] = "Hoxton Hustlers",
["bm_suit_var_esport_yellow_desc"] = "İlginç bir bilgi: 90’larda Hoxton’ın her gün fanatikçe antrenman yaptığı kısa bir dönem vardı. Koşuya çıkar, ağırlık kaldırır, ara sıra kriket bile oynardı. Bu geçici delilik nöbeti ona bir süreliğine viski sevgisini neredeyse unutturmuştu. Neredeyse.",
["bm_suit_var_gangstercoat_british"] = "The Muted Executor",
["bm_suit_var_gangstercoat_british_desc"] = "Sade ve ağırbaşlı. Ağzının köşesinde bir puro veya pipoyla iyi gider ama unutmayın çocuklar: sigara öldürür.",
["bm_suit_var_gangstercoat_default"] = "The Urban Executor",
["bm_suit_var_gangstercoat_default_desc"] = "Gösterişsiz ama mesajı açık. Bunun içinde kimse kötü görünmez.",
["bm_suit_var_gangstercoat_french"] = "The Inspector Executor",
["bm_suit_var_gangstercoat_french_desc"] = "Pembe elmas peşindeysen ve şüpheli bir Fransız aksanıyla konuşuyorsan bu kusursuz tamamlayıcıdır. Büyüteç için cebi bile var.",
["bm_suit_var_gangstercoat_irish"] = "The Shamrock Executor",
["bm_suit_var_gangstercoat_irish_desc"] = "Aziz Patrick Günü’nde soygun yapmak için mükemmel.",
["bm_suit_var_general_blue"] = "The French General",
["bm_suit_var_general_blue_desc"] = "Savaşa da geçit törenine de hazır. Meç ayrı satılır.",
["bm_suit_var_general_default"] = "The Classic General",
["bm_suit_var_general_default_desc"] = "Zarif ve otoriter bir duruş için.",
["bm_suit_var_general_red"] = "The Blood General",
["bm_suit_var_general_red_desc"] = "Sen ayrıldıktan sonra savaş alanının zeminiyle uyumlu.",
["bm_suit_var_general_white"] = "The Ivory General",
["bm_suit_var_general_white_desc"] = "Bunun kuru temizleme faturası oldukça kabarık gelir.",
["bm_suit_var_gentleman_default"] = "Moody Longcoat",
["bm_suit_var_gentleman_default_desc"] = "Geceye karışıp geçmek isteyen soyguncuya sade ve koyu bir görünüm...",
["bm_suit_var_gentleman_father"] = "Pious Black",
["bm_suit_var_gentleman_father_desc"] = "Bu takımın gösterişsiz tonlarını beğenmek için dindar, hatta maneviyata önem veren biri olmana gerek yok.",
["bm_suit_var_gentleman_marine"] = "The Blue Swagger",
["bm_suit_var_gentleman_marine_desc"] = "Soygunda devlet adamına yaraşır bir tavır gerektiğinde zarif ve kasvetli bir kıyafet.",
["bm_suit_var_gentleman_veteran"] = "Hunter's Elegance",
["bm_suit_var_gentleman_veteran_desc"] = "Kırda da siperlerde de kaçış minibüsünün arka koltuğunda da yerini yadırgamaz.",
["bm_suit_var_gunslinger_casual"] = "Sandstorm",
["bm_suit_var_gunslinger_casual_desc"] = "Kum tepelerinin ardından geldiğini kimse görmeyecek.",
["bm_suit_var_gunslinger_default"] = "Highwayman",
["bm_suit_var_gunslinger_default_desc"] = "Posta arabasını soyarken şişko arabacıya ciddi olduğunu göster.",
["bm_suit_var_gunslinger_piro"] = "The Ostentatious",
["bm_suit_var_gunslinger_piro_desc"] = "Tam öğle vakti rakibinin 20 fit karşısında dururken tarzını konuşturmak isteyen silahşora. (Ya da sadece matkabın işini bitirmesini bekleyene.)",
["bm_suit_var_gunslinger_red"] = "The Red Gunman",
["bm_suit_var_gunslinger_red_desc"] = "Sana ters bakan adama kaç mermi sıkarsan sık, koyu kırmızı can kanı bu takımın görkemli rengine erişemez.",
["bm_suit_var_highinttech_blue"] = "Ripstop Tactical Azure",
["bm_suit_var_highinttech_blue_desc"] = "Bu taktik takımın gök mavisi çeşidi.",
["bm_suit_var_highinttech_default"] = "Ripstop Tactical Black",
["bm_suit_var_highinttech_default_desc"] = "Bu taktik kıyafetin neredeyse tamamen siyah çeşidi.",
["bm_suit_var_highinttech_green"] = "Ripstop Tactical White",
["bm_suit_var_highinttech_green_desc"] = "Bu taktik takımın beyaz çeşidi.",
["bm_suit_var_highinttech_orange"] = "Ripstop Tactical Vermilion",
["bm_suit_var_highinttech_orange_desc"] = "Bu taktik takımın canlı kızıl çeşidi.",
["bm_suit_var_hiphop_beige"] = "Shady Wu",
["bm_suit_var_hiphop_beige_desc"] = "Şehirli Kung Fu Ustası çatılarda ilerlerken sirenler uluyordu. Zaman daralıyordu. Kalp atışları kulaklarında sabit bir ritim tutuyor, beyaz spor ayakkabılarının her adımı ritme ekleniyordu. Önünde binalar arasında büyük bir boşluk vardı. Karşı tarafta, bir bacadan sarkan, alıp getirmesi için gönderildiği ödül duruyordu. Atlayışa hazırlandı. Turna usulü havalanma zamanı...",
["bm_suit_var_hiphop_default"] = "Heistmaster Flash",
["bm_suit_var_hiphop_default_desc"] = "Üç gangster bozuntusu, ara sokakta Jiro’nun etrafını sardı. Cüzdanını isterken ırkçı hakaretler savuruyorlardı. Kendi başlarına ve bütün çetelerine ne kadar büyük dert açtıklarını bir bilselerdi. Jiro sabretti. Başka bir yerde olması gerekiyordu; kendine fazla güvenen üç aptalın kıçını tekmelemekle zaman kaybedemezdi. Ama ne yazık ki laf anlatılmıyordu. Birkaç dakika sonra Jiro ara sokaktan tek başına çıktı. Geride gangster özentilerinin can çekişen iniltileri duyuluyor, kanları asfaltla karışıp yağmur suyu mazgallarına süzülüyordu...",
["bm_suit_var_hiphop_green"] = "Krushin' Groovy",
["bm_suit_var_hiphop_green_desc"] = "Dünya böyle bir savaş görmedi. İki taraf, sesli kitle imha silahlarıyla birbirini yok etmeye hazır. Metal, Hip hop’a karşı. Nihai hesaplaşma. Kim kazanacaktı? Zebra taytlı grup mu, pantolonlarını ters giyenler mi?",
["bm_suit_var_hiphop_red"] = "Shizzle Duds",
["bm_suit_var_hiphop_red_desc"] = "Marvin günlerdir bir şey yememişti. Lanet olası Snoopfather çetesi evini basmış, son parasını da almıştı. Elbette para, zekice sahte bir marulun içine gizlenmişti. İntikam almaya kararlı bir hâlde Snoopfather bölgesine ilerlerken midesindeki guruldayan boşluğu düşünüyordu...",
["bm_suit_var_hiphop_white"] = "Hippity Hop",
["bm_suit_var_hiphop_white_desc"] = "Garth, kaykay sürerken böyle bir pantolon giymeyecek kadar akıllıydı. Payday Gang için bir iş yaparken pantolonunun tekerleklere takılıp onu düşürdüğünü, karşıdan gelen trafiğe savurduğunu falan düşünsene; ne kötü görünürdü!",
["bm_suit_var_hippie_abstraction"] = "White Bunny",
["bm_suit_var_hippie_abstraction_desc"] = "1960’ların sonlarında bir adam doğdu. Akıl hocası olacak kişiyle tanışana dek hayatı kaos, ihanet ve belayla geçecekti. Akıl hocası ona bir şeyler öğretti, dünyanın gerçekte nasıl işlediğini anlattı. Pek az kişinin bildiği, duyulmamış sırları açığa çıkaracak bir kitaptan söz etti. Adam bu bilgiyi alıp hayatını yeniden şekillendirdi. Sonunda tüm zamanların en büyük suç dehalarından biri oldu; kendisine haksızlık eden herkesten intikam alacak, halkın asla haberdar olmayacağı en büyük soyguna girişecekti...",
["bm_suit_var_hippie_default"] = "Gimme Shelter",
["bm_suit_var_hippie_default_desc"] = "Chains, göz bebeği 1968 model üstü açık otomobilin gazını kökledi. Death Valley’den geçen otoyolda tozu dumana katarken hızını saatte 88 mile çıkardı. Depoda yeterli benzin olmasını umuyordu. Arkada Hoxton yüksek sesle horluyor, ayaklarının dibinde boş bir sek malt şişesi yuvarlanıyordu. Dikiz aynasında uzakta yanıp sönen mavi ışıklar yaklaşıyordu. Kaçacak yer yoktu. Chains yavaşlayıp hızı 55’in hemen altında tuttu. Işıklar yaklaştı. Eyalet devriye aracı arkalarına gelince motorun kükremesinin üstüne siren sesi de eklendi. Chains’in şaşkın bakışları arasında polis arabası yanlarından geçip gitti; belli ki başka bir av arıyordu.",
["bm_suit_var_hippie_flowerpower"] = "Peacemaker",
["bm_suit_var_hippie_flowerpower_desc"] = "Duke dalgın dalgın eski aile fotoğraflarını karıştırdı. Vay be, 60’lar ve 70’ler ailesine moda bakımından hiç yaramamıştı! Babasının tam böyle bir kıyafeti vardı. Belki bir soyguncunun üzerinde daha iyi dururdu?",
["bm_suit_var_hippie_native"] = "California Dreaming",
["bm_suit_var_hippie_native_desc"] = "Kalabalık sahnedeki şeytanlara çığlık atıyordu. Gıcırdayan gürültü ve geri besleme döngülerinden dört uluyan iblis. Işıkla sesten bir esrime. Öylesine büyülenmişlerdi ki sahne görevlisinin grubun yedek ekipmanlarını arabasına doldurup en yakın çalıntı mal alıcısını bulmak için geceye karıştığını kimse fark etmedi...",
["bm_suit_var_hippie_tribe"] = "Lizard King",
["bm_suit_var_hippie_tribe_desc"] = "Oda dumanla doluydu. Solgun güneş kirli camlardan geçiyor, toplananlar için dans eder gibi görünen gölgeler düşürüyordu. Herkes Lizard King’in gelmesini bekliyordu. Kapı açıldı; ışığın önünde silueti belirdi. Bir yansıma gözünün kenarına çarpıp retinasına döndü, sürüngenimsi bir parıltı yarattı. Çölde ne görmüştü?",
["bm_suit_var_jumpsuit_blue"] = "Bucket of Blue",
["bm_suit_var_jumpsuit_blue_desc"] = "Bir zamanlar Steve adlı bir düzenbaz vardı, cebinde bir plan saklardı. Dost çetesiyle bir akım başlattı; pek uzun sürmedi. Şakadan fazlası bir banka soygununda, sıradan boyacılarınkinden daha havalı mavi tulumlar giydiler. Rehineleri tutup oyun oynamaya zorladılar; biri zemini parçalayana dek. Polis kapıdan gelmesin diye umuyorlardı.",
["bm_suit_var_jumpsuit_brown"] = "Dust Devil Sienna",
["bm_suit_var_jumpsuit_brown_desc"] = "Payday Gang bugüne kadar Güney’de pek iş almadı; sınırın güneyini saymıyoruz bile! Ama bu ileride değişirse diye Locke, tozlu ovalarda iyi koruma sağlayacak bu takımlardan bol miktarda stokladı.",
["bm_suit_var_jumpsuit_default"] = "Grey Heat",
["bm_suit_var_jumpsuit_default_desc"] = "Tehlikeyi köşede gördüğünde hayatındaki her şeyi bırakabilecek pek az kişi vardır. Dallas gençliğinde bir zamanlar bunu yapabileceğini sandı; neredeyse hem akıl sağlığına hem özgürlüğüne mal oluyordu. O sırada böyle bir tulum giyiyordu ve o gün onu kurtaran tek şey o oldu.",
["bm_suit_var_jumpsuit_green"] = "Chains' Camo",
["bm_suit_var_jumpsuit_green_desc"] = "Güvenli evin bir yerinde, aramaya zahmet etme, Chains’in duygusal değer verdiği eşyalarını sakladığı bir sandık var. İçinde tıpkı bunun gibi bir tulum da bulunuyor. Özel günlerde çıkarıyor ve nedense onu çok koruyor. \"Ödünç alırken\" yakalanan soyguncular, yerinde bir yumrukla ödüllendirildi.",
["bm_suit_var_jumpsuit_red"] = "Overkill Red",
["bm_suit_var_jumpsuit_red_desc"] = "Soyguncuların lakaplarını dünya şehirlerinden almasının olayı ne? Tesadüf mü? Tembeller mi? Hayal güçleri mi yok? Yoksa eskiden Bain’in kurduğu, bilinmeyen büyük bir planın parçası olan daha büyük bir şey mi dönüyor? Peki sırada ne var, Teksas’taki Lubbock’un adını taşıyan bir soyguncu mu? Belki Tokyo? Biraz aşırıya kaçıyor, değil mi? Bu akım nereye kadar gidebilir? Bölüm 3’te de devam edecek mi? Anlatacak kadar yaşayanlar cevabı öğrenebilir.",
["bm_suit_var_kungfumaster_black"] = "Laohu Dashi Chi",
["bm_suit_var_kungfumaster_black_desc"] = "Bu tasarım zihnini boşaltıp odaklanarak işi bitirmen gereken anlar için.",
["bm_suit_var_kungfumaster_default"] = "Laohu Dashi Apex",
["bm_suit_var_kungfumaster_default_desc"] = "Bazı klasiklerin modası asla geçmez!",
["bm_suit_var_kungfumaster_red"] = "Laohu Dashi Lotus",
["bm_suit_var_kungfumaster_red_desc"] = "Elbette dikkat çekersin ama bu görünüm, ne olursa olsun direnip savaşmayı sürdürmeni sağlar.",
["bm_suit_var_kungfumaster_white"] = "Laohu Dashi Haze",
["bm_suit_var_kungfumaster_white_desc"] = "Bazen azı karar. Üstelik bunu giydiğinde üstlerine atılmanı hiç beklemeyecekler.",
["bm_suit_var_leather_black"] = "Black Array",
["bm_suit_var_leather_black_desc"] = "Orijinal siyah ve parlak görünüm. Bazıları hâlâ en iyisinin bu olduğunu söylüyor.",
["bm_suit_var_leather_default"] = "Brown Array",
["bm_suit_var_leather_default_desc"] = "Gösterişsiz, ince tonlar ve Korint derisi.",
["bm_suit_var_leather_red"] = "Red Array",
["bm_suit_var_leather_red_desc"] = "Hafif rugan kaplamalı kırmızı ve siyah.",
["bm_suit_var_leather_white"] = "White Array",
["bm_suit_var_leather_white_desc"] = "Tertemiz ve diri; morötesi ışığın altına çıkmaya hazır. En azından silahlar patlayana kadar.",
["bm_suit_var_leatherfluff_suit_default"] = "Statement",
["bm_suit_var_leatherfluff_suit_default_desc"] = "Nereden geldiğini asla unutma.",
["bm_suit_var_lonorwa_blue"] = "Dead of Winter Ice",
["bm_suit_var_lonorwa_blue_desc"] = "Bu çeşit, açık ve koyu tonları iyi harmanlıyor.",
["bm_suit_var_lonorwa_default"] = "Dead of Winter Solid",
["bm_suit_var_lonorwa_default_desc"] = "İşte klasik sürüm bu. Gerçekten kendini belli eden.",
["bm_suit_var_lonorwa_orange"] = "Dead of Winter Orange ",
["bm_suit_var_lonorwa_orange_desc"] = "Biraz daha işlevsel bir görünümden zarar gelmez.",
["bm_suit_var_lonorwa_white"] = "Dead of Winter Snow",
["bm_suit_var_lonorwa_white_desc"] = "Kış tarlalarında görünmez olmak mı istiyorsun? Bu çeşit tam sana göre.",
["bm_suit_var_lowinttech_blue"] = "Ripstop Casual Azure",
["bm_suit_var_lowinttech_blue_desc"] = "Pratik ama rahat bu takımın mavi çeşidi.",
["bm_suit_var_lowinttech_default"] = "Ripstop Casual Black",
["bm_suit_var_lowinttech_default_desc"] = "Bu kullanışlı ve rahat takımın siyah çeşidi.",
["bm_suit_var_lowinttech_red"] = "Ripstop Casual Vermilion",
["bm_suit_var_lowinttech_red_desc"] = "Bu kullanışlı ve rahat takımın kırmızı çeşidi.",
["bm_suit_var_lowinttech_yellow"] = "Ripstop Casual White",
["bm_suit_var_lowinttech_yellow_desc"] = "Bu kullanışlı ve rahat takımın beyaz çeşidi.",
["bm_suit_var_mariachi_black"] = "Calavera",
["bm_suit_var_mariachi_black_desc"] = "Kanun kaçağı, ölmüş sevgilisinin mumyalanmış bedenini süsleyen buketten bir gül aldı. Onun canını alan kartel üyesinden intikam almaya yemin etti. Kaybının hesabını sorarken giyeceği takımın üzerine, sevgilisinin anısına bu gülü işletti.",
["bm_suit_var_mariachi_brown"] = "Dust Devil",
["bm_suit_var_mariachi_brown_desc"] = "Askerlikten döndükten sonra Chains’in kaybolacağı, bir süre gözden uzak kalacağı bir şehre ihtiyacı vardı. Birisi San Franscisco’nun buna harika olduğunu söyledi ama oradaki grunge gruplarını düşünmemişti. Chains’in grunge gruplarını ne kadar çoook sevdiğini hepimiz biliyoruz, değil mi? Özellikle berbat olanları. Evet, Chains SF’de fazla kalmadı. Biraz güneye gitti ve kader başka planlar göstermeden önce Mexico City’deki mariachi festivalinde kısa süre dublörlük yaptı. Bugüne dek kimse ona corrido sevip sevmediğini sormadı...",
["bm_suit_var_mariachi_default"] = "Midnight Serenade",
["bm_suit_var_mariachi_default_desc"] = "Wolf, en sevdiği grubun son albümünü satın almaya (gerçekten para ödeyerek almaya) kesin kararlı bir şekilde plakçıya girdi. Kapı arkasından kapanınca yüzünden nadiren görülen bir dehşet geçti. Ortalıkta tek bir 12 inçlik karton plak kılıfı bile yoktu! Homurdanarak tezgahtaki eşofmanlı dingile yürüyüp yakasına yapıştı. Sakalının altından \"Lanet plaklar nerede?\" diye hırladı. Zavallı adam CD’lerin plaktan üstün olduğuna dair bir şeyler geveledi. Bunun üzerine Wolf raflardaki \"üstün\" plastik disklere bir sürü delik açtı...",
["bm_suit_var_mariachi_red"] = "Teotihuacan",
["bm_suit_var_mariachi_red_desc"] = "Söylentiler, karmaşık ağına rüzgâr vurduğunda ürpertici bir uluma çıkaran ölümcül bir çöl örümceğini anlatır. Kimileri ağın silahlı çatışmalarda ölen bütün kayıp ruhların ağıtlarını tuttuğunu, kimileriyse dünyanın bugünkü hâlini kınayan kadim Maya tanrılarının öfkeli seslerini çağırdığını söyler.",
["bm_suit_var_mariachi_white"] = "Skin of the Saint",
["bm_suit_var_mariachi_white_desc"] = "Bu takımın yumuşak pamuklu kumaşının bir hikâyesi var. Dokuyan adam, ölmüş kızının anısına Ölüler Günü’nden önce bitirebilmesi için bekleyen terziye zamanında ulaşmak üzere katır sırtında beş gün yol gitti. Azıcık yiyeceğini ve suyunu yük hayvanıyla paylaşıp zorlu yollarla, fırtınalarla, haydutlarla savaştı; sonunda varacağı yere ulaştı. Ardından gelen kutlamalarda dokumacı, havada kızının kahkahasını duyduğuna yemin etti.",
["bm_suit_var_miami_black"] = "The Black Celebration",
["bm_suit_var_miami_black_desc"] = "Soyguncular ağlamaz ve çok azı rimel sürer. Ama hemen herkesin içindeki gizli gotik ruhu bir ara doyasıya yaşadığı düşünülebilir. Ya da belki öyle değildir. Belki sadece renkleri birbiriyle uyumlu seçmekle uğraşmak istemiyorlardır.",
["bm_suit_var_miami_default"] = "Sky Blue",
["bm_suit_var_miami_default_desc"] = "Bir keresinde Sangres, Brezilya ile Meksika arasında uçakla çalıntı silah taşınmasına eşlik ediyordu. Bu takımı giyen ortağı uçuş sırasında ona ihanet etti. Kısa bir boğuşmanın ardından Sangres onu kargo kapısından dışarı tekmeledi. Artık eski olan ortağı kollarını çılgınca savurup çığlıklarla düşerken Sangres, takımın mavisinin parlak mavi gökyüzünde ne kadar iyi kamuflaj olduğunu fark etmeden edemedi. Sonra yere \"şlap\" diye çarptı ve görüntü bozuldu.",
["bm_suit_var_miami_grey"] = "Swamp Grey",
["bm_suit_var_miami_grey_desc"] = "Jimmy, bu takımın Florida Everglades’de timsahlardan kaçınmak için harika kamuflaj olduğuna hâlâ inanıyor. Hoxton onu denemeye kışkırttı; haklı çıkarsa 20.000 $ vereceğini söyledi. Henüz yapmadı ama sığınakta biri konuyu her açtığında geçiştirip \"Yakında dostum, belki yarın\" diyor.",
["bm_suit_var_miami_pink"] = "Cadillac Pink",
["bm_suit_var_miami_pink_desc"] = "Rust, Teksas’ın Ding Dong kasabasında yerel Overkill MC şubesine keşif yaparken iddiaya girip bir kez bu takımı giydi. Yerel bara girince bir sürü tuhaf bakış topladı ama tek kişi bile laf etmeye veya sorun çıkarmaya cesaret edemedi. Bir adam Teksas’ta böyle bir takımla dolaşıyorsa dünya onun hiçbir şeyden korkmadığını bilir!",
["bm_suit_var_miami_white"] = "Disco White",
["bm_suit_var_miami_white_desc"] = "Söylentiye göre Miami Polis Departmanı’nın arşivlerinde bir yerde, Dallas’ı böyle bir takım giymiş, üstü açık bir Falcogini Model F sürerken gösteren bir fotoğraf var. Elbette bu sadece bir söylenti. Dallas yanında bahsedersen her şeyi inkâr eder. Üstelik konu her açıldığında kimliği belirsiz biri, arşivlerin bulunduğu karakolun bodrumunu su basmasına yol açarak, yakarak, havaya uçurarak veya başka bir yoldan yok etmeye çalışır...",
["bm_suit_var_peacoat_black"] = "Trophy Black",
["bm_suit_var_peacoat_black_desc"] = "Ünlü bir ödül avcısı bir zamanlar böyle bir ceketi on yıl boyunca her gün giyerdi. Crimenet kurulmadan çok önce yıllarca Bain’in peşini bırakmadı. Sonunda avcının şansı tükenip Bain tarafından indirildiğinde Bain ceketi hatıra olarak sakladı.",
["bm_suit_var_peacoat_blue"] = "Workman's Blues",
["bm_suit_var_peacoat_blue_desc"] = "Sokol bir zamanlar Dmitri adlı bir inşaat işçisi tanıyordu. Her hafta aynı barda birlikte hokey izlerlerdi. Bu palto Sokol’a o günleri hatırlatıyor; Dmitri’nin de aynısından vardı. Ağır çalışmadan kir ve toz lekeleriyle dolu, kenarları aşınmış ve saçaklanmıştı. Ama gururla giyerdi; her küçük leke, emekle geçen onurlu bir hayatın hikâyesini anlatırdı. ",
["bm_suit_var_peacoat_brown"] = "Bullet Brown",
["bm_suit_var_peacoat_brown_desc"] = "V8 motorlu üstü açık otomobil, en az on polis aracının takibinde otoyolda kükrerken güneş ışığı koyu yeşil boyasında parlıyordu. San Francisco’nun kalabalık sokaklarında sağa sola kıvrıldılar. Sürücünün ensesinden süzülen tek bir ter damlası, dikkatini meşhur Lombard Street’te kaldırıma çarpmasına yetecek kadar dağıttı. Polisler hâlâ peşindeyken arabadan inip koştu. Sonra tam olarak ne olduğunu kimse bilmiyor ama söylentiye göre Chinatown’da izini kaybettirdi. Gördükleri son şey, kalabalığın içinde kaybolurken kahverengi paltosunun parıltısıydı.",
["bm_suit_var_peacoat_default"] = "The Grey Redeemer",
["bm_suit_var_peacoat_default_desc"] = "Uzun zaman önce suç dünyasında karanlık bir gölge dolaşıyor, en aşağılık mafya üyelerini anlatılamaz şiddet eylemleriyle birer birer öldürüyordu. Amerika’nın suç baronlarını korku sardı; intikamın ne zaman geleceğini kimse bilmiyordu. Çok az kişi bu gezgin dehşeti bir anlığına görebildi ama tek bir iblis mi yoksa birden fazla mı olduğunu söyleyemedi. Gelen tek tarif ölümün giydiği kıyafetti. Tıpkı bunun gibiydi.",
["bm_suit_var_peacoat_white"] = "Godfather's White Lie",
["bm_suit_var_peacoat_white_desc"] = "Mafya babası, rakip çetenin kanlı sonunu emretmekle geçen bir haftanın ardından ailesiyle güzel bir yemek yemeye hazır hâlde restorana girdi. O çetenin tek sağ kalanının banyoda beklediğinden habersizdi. Mafya babası paltosunu çıkaramadan adam sırtına bir kurşun sıkıp kan davasını sonsuza dek bitirdi.",
["bm_suit_var_poolrepair_default"] = "Pool Boy",
["bm_suit_var_poolrepair_default_desc"] = "Doğru kadın veya erkeğin üzerinde bu kıyafet, çaresiz bir ev sahibinin aklını arkadaşlarının bodrum kasasını boşaltmasına yetecek kadar başından alır.",
["bm_suit_var_puffervest_suit_default"] = "Seaside",
["bm_suit_var_puffervest_suit_default_desc"] = "O deniz meltemini hisset!",
["bm_suit_var_punk_billieboy"] = "Mos Med Gnu",
["bm_suit_var_punk_billieboy_desc"] = "Uyum. Korkakça boyun eğme her an etrafımızı sarıyor. Bir tuğla yığını gibi her bireyin zihnine ağırlık yapıp onu kabullenmeye zorluyor. Tabii asi bir çığlık atıp yumruğunu havaya kaldırmadan duramayanlardansan başka. Bir bankaya bunu giyerek giren soyguncu, dünyaya hiçbir şeyden korkmadığını gösterir!",
["bm_suit_var_punk_blue"] = "Rockaway Beach",
["bm_suit_var_punk_blue_desc"] = "New York’taki her müzisyen 1983’ün meşhur \"müzik dükkânı soygun serisini\" bilir. Hikâyeye göre Jacket, çılgın soygunculuk kariyerinden önce bir punk grubundaki arkadaşlarıyla dolaşıyor, bira ve uyuşturucu karşılığında sahne işlerine yardım ediyordu. Bir gece gösteriden hemen önce şarkıcının en sevdiği gitarın sol teli koptu. Adam sıradan telle yetinmeyip özel marka ithal düz sarım tellerini isterken bütün dükkânlar kapalıydı. Jacket yeni tel bulmak için biraz... yaratıcı... olmak zorunda kaldı. Gösteriye beş dakika kala buldu.",
["bm_suit_var_punk_default"] = "Pasadena Buzzbomb",
["bm_suit_var_punk_default_desc"] = "Sydney, son soygunu kutlamak için sığınakta parti verilen bir gece iddiaya girip saçını parlak turuncuya boyamıştı. Vlad da oradaydı; her zamanki gösterişli, erkek şovenisti tavırlarıyla dolanıyordu. Sydney’nin saçını görünce kendini tutamayıp Rusça \"fazla olgun bir havuç\" hakkında bir yorum yaptı. Şanssızlığına, Sydney ne dediğini gerçekten anladı. Bir süre sonra banyoda kanayan burnuyla ilgilenirken kendi kendine güldü ve bir daha Sydney’nin saç rengine yorum yapmamaya karar verdi. \"Yine de\" diye düşündü, \"buna fena hâlde değdi!\"",
["bm_suit_var_punk_red"] = "White Wedding",
["bm_suit_var_punk_red_desc"] = "Liverpool’da bir gece Clash konserinden dönen Hoxton, gecenin en sevdiği şarkısını mırıldanarak bir ara sokağa girdi. Büyük çöp kutusunun arkasından bıçak sallayan iki dazlak çıktı. Bozuk gitar rifflerinin doğal sarhoşluğundaki Hox, uzatılan bıçakları umursamadan holiganları patakladı. Sonra da onları saklandıkları çöp kutusuna attı; bütün bunları yaparken en sevdiği şarkıyı mırıldanmayı sürdürüyordu...",
["bm_suit_var_punk_scottish"] = "Army Life",
["bm_suit_var_punk_scottish_desc"] = "Punk bir zamanlar ahlak paniğine kapılan ebeveynlerin kâbusu, geçici konser mekânına çevrilen pek çok metruk deponun da kurtarıcısıydı. Dragan, 1980’lerde bir akşam bir iş bağlantısıyla buluşmak için Londra Docklands’deki, kötü şöhretli yedi günlük \"Deadweek\" mohikan saç partisine gitti. Bağlantı hiç gelmedi ve Dragan ondan bir daha haber alamadı. Bugün bile ne olduğunu hâlâ bilmiyor.",
["bm_suit_var_rusbear_arctic"] = "Dogsled Master Ivory ",
["bm_suit_var_rusbear_arctic_desc"] = "Bununla karlı arazide gerçekten iyi kamufle olursun.",
["bm_suit_var_rusbear_blacmor"] = "Dogsled Master Ebony",
["bm_suit_var_rusbear_blacmor_desc"] = "Bu çeşit gece soygunları için kusursuz.",
["bm_suit_var_rusbear_default"] = "Dogsled Master Classic",
["bm_suit_var_rusbear_default_desc"] = "Dikkat çekebilirsin ama en azından kan lekeleri belli olmaz... O kadar da olmaz.",
["bm_suit_var_rusbear_quilt"] = "Dogsled Master Marine",
["bm_suit_var_rusbear_quilt_desc"] = "Denize mi açılıyorsun? Neden uygun bir renk giymeyesin?",
["bm_suit_var_t800_cowboy"] = "Infamy Dust",
["bm_suit_var_t800_cowboy_desc"] = "At üstünde geldi; zorlu bir soygun gününün ardından gözünü yerel salona dikmiş soyguncu kadın.",
["bm_suit_var_t800_default"] = "Infamy Dark",
["bm_suit_var_t800_default_desc"] = "İster zaman yolculuğu yapan bir ölüm makinesi ol ister sonraki soygununu yaparken 1950’lerin greaser ruhunu yaşatmaya çalışan sıradan biri; bu takım seni kolluyor.",
["bm_suit_var_t800_red"] = "Infamy Red",
["bm_suit_var_t800_red_desc"] = "Kırmızı derinin iddialı görünümüyle Kötü Şöhretini göster.",
["bm_suit_var_t800_toughboy"] = "Infamy White",
["bm_suit_var_t800_toughboy_desc"] = "Bu siyah beyaz birleşimi muhtemelen çamurda yuvarlanmayı sevmeyen soygunculara daha uygun.",
["bm_suit_var_texvest_default"] = "Prestige",
["bm_suit_var_texvest_default_desc"] = "Taşra şıklığı.",
["bm_suit_var_xmas_tuxedo_black"] = "Rusty Santa",
["bm_suit_var_xmas_tuxedo_black_desc"] = "Motosikleti bozulmuştu. Issızlığın ortasında kalmanın tam zamanıydı. Sığınaktaki Noel partisini kesin kaçıracaktı. Bu yıl Rust’a Jiro’nun sake yumurtalı kokteylinden yoktu. Kahretsin. Çantasını alıp yürümeye başladı. Güneş karlı manzaranın üzerinde batıyordu. Döküntü bir çiftlik evinin yanından geçerken içeriden yürek burkan bir çığlık geldi. Rust duraksadı. Onun işi değildi. Ama bir şey fikrini değiştirdi. Pencereden yerde birini görüp içeri koştu; ağacını süslerken düşmüş yaşlı bir kadın buldu. Kalkmasına yardım edip yaralarıyla ilgilendikten sonra çaya kaldı. Meğer ahırda hâlâ çalışan klasik bir motosiklet varmış, ödünç alabilirmiş. Belki o partiyi kaçırmayacaktı...",
["bm_suit_var_xmas_tuxedo_blue"] = "Miracle Blues",
["bm_suit_var_xmas_tuxedo_blue_desc"] = "Sydney ara sokaktan başını uzatıp mavi kırmızı ışıkları yanıp sönen, sireni uluyan polis arabasının geçişini izledi. Taşıdığı ganimet dolu çantayı düzeltti, telefonunu çıkarıp aradı. Hattın öteki ucundan \"Evet?\" diyen bir ses geldi. \"Benim. 34. sokağın köşesi. Ortalık temiz, buraya gel\" diye yanıtlayıp kapattı ve bekledi. Rüzgâr uğulduyor, kar sokakta savruluyordu; o karanlığa bakıp endişeyle homurdanıyordu. Birkaç dakika sonra bir minibüs yanaştı. Şoför inip selam verdi. \"Paket nerede?\" Ara sokağa girdiler. Sydney, üzerinde yavrularını emziren bir köpeğin yattığı kutu yığınını gösterdi. Kocaman bir deste para çıkarıp şoföre uzattı. \"Ne yapacağını biliyorsun dostum.\" Şoför parayı alıp yanıtladı: \"Tamamdır, merak etme. Güvende olmalarını sağlayacağım.\"",
["bm_suit_var_xmas_tuxedo_default"] = "Elf Extravaganza",
["bm_suit_var_xmas_tuxedo_default_desc"] = "Karlı ormanda tek başına duran küçük kulübenin taş bacasından duman yükseliyor. Ortalık sessiz; yalnızca kış uykusundaki ağaçların kuru dallarının ayaz rüzgârda hışırtısı duyuluyor. Uzaklarda bir yerde geyik ailesi ısınmak ve yırtıcılardan korunmak için bir mağarada toplanıyor. Ama bu gece Wolf yiyecek peşinde değil. Kulübesinde ateşin başında yalnız oturuyor; elinde soğuk bal şarabıyla soygunculuğu boyunca yaşadığı her şeyi düşünüyor.",
["bm_suit_var_xmas_tuxedo_green"] = "The Smashin' Rudolph",
["bm_suit_var_xmas_tuxedo_green_desc"] = "Duke bu tatil arifesinde bir kadeh fazla brendi içmişti. Hoxton’ın hediye ettiği antika İngiliz revolverini yeniden birleştirmeye çalışırken başı dönüyordu. Kedilerinden biri masanın yanındaki taburede dikkatle izliyordu. Yüksek bir \"FOİNG\" sesiyle tetik yayı odanın öbür ucuna uçtu; kedi peşine fırladı. İkisi de güvenli evin Noel ağacının dallarında kayboldu ve ağaç devrildi. Üst kat korkuluğundan aşıp büyük gürültüyle aşağı düştü. Ardından bir \"Aaargh!\" ve \"Yukarıda ne halt oluyor?\" bağırtısı geldi. Birkaç dakika sonra Chains, başında Noel Baba şapkası ve eli yüzünde, merdivenleri öfkeyle çıktı. Pek mutlu değildi. Elini çekince kocaman, şişmiş, belli bir ren geyiğininki kadar kıpkırmızı bir burun göründü. Sanki düşen ağacın gövdesi çarpmış gibi...",
["bm_suit_waistcoat"] = "The Linchpin ",
["bm_suit_waistcoat_desc"] = "Güçlü ve profesyonel bir hava yaymak istiyorsan bu kıyafet işini fazlasıyla görür.",
["bm_suit_winter_suit"] = "Winter Camo Parka",
["bm_suit_winter_suit_desc"] = "Askerî kış kamuflajlı tam bir takım. Amaç karda görünürlüğü azaltmak.",
["bm_suit_xmas_tuxedo"] = "Dapper Dashing Holiday",
["bm_suit_xmas_tuxedo_desc"] = "Noel öncesi soygundu. Kasanın içinde tek bir kilit pimi bile oynamıyordu; bütün suç Locke’taydı. Matkapları çantalara özenle koymayı unutmuş, soyguncular oraya varana kadar da fark etmemişti. Twitch minibüste rahatça beklerken Jimmy sırf yapabildiği için bir pencere kırdı. Hadi Clover! Hadi Sangres! Jacket ve Wick, siz de! Tek bir soyguncu bile Vlad’ın kayınbiraderinin gerçekten Saint Nick olduğuna inanmıyordu.",
