["bm_wolf_rising"] = "Risen Wolf Mask",
["bm_wolf_rising_desc"] = "Sırf görüntüsü bile bir rakibi delirtmeye yeter. Kandan ve eski kemiklerden yapılmış gibi, yüzündeki ikinci bir deriye benziyor. Kafanın arkasındaki sesler korosunu hep dinle. Yapman gereken yıkıcı şeyleri durmadan söyleyenleri. Cazibesine yenil, kendi deliliğinin tadını çıkar. Bu kez kendini tutma. Hiçbir şey için. Bu kez düşmanlarını kendi başıboş, ağzı köpüren deliliğine sürükle. Gerçekte olduğun iblise dönüş; çünkü cehenneme gittin ve sevdin. Kendini tutmanın anlamı yok. Tek teselli, düşmanının kanının dudaklarından usulca süzülüşünü hissetmek.",
