["bm_wpn_fps_upg_o_xpsg33_magnifier"] = "Riktpunkt Magnifier Gadget",
["bm_wpn_fps_upg_o_xpsg33_magnifier_desc"] = "Açmak veya kapatmak için $BTN_GADGET; düğmesine bas.",
["bm_wpn_gre_electric_unlock"] = "\"Vızıltı Bombası\" başarımını tamamla!$NL;Veya Jiu Feng Smuggler Pack 2 DLC’sini satın al!",
["bm_wpn_money_event_ended"] = "Etkinlik Bitti: Artık kullanılamıyor",
["bm_wpn_prj_ace"] = "Ace of Spades",
["bm_wpn_prj_ace_desc"] = "Fırlatma kartları genellikle sahnenin öbür ucundaki karpuzları ikiye ayıran sihirbazlarla ilişkilendirilir. Ama ağırlık ve jilet gibi kenarlar eklediğinde sessiz bir katilin olur. Bu çelik aslardan birini kolunda sakla; şartlar ne olursa olsun oyuna katılmaya hep hazır ol.$NL;$NL;Ace of Spades, PAYDAY 2’nin iki yılını kutlamak için topluluğa verilen ücretsiz bir fırlatılabilir silahtır!",
["bm_wpn_prj_four"] = "Shuriken",
["bm_wpn_prj_four_desc"] = "Kullanıcısının eline gizlenmiş bir kılıç gibi olan shuriken, ölümcül ve tamamen sessiz bir silahtır. İlk örnekleri çivi ve iğnelerden yapılan fırlatma yıldızının kan ve savaşla dolu uzun bir tarihi vardır. Bu modern paslanmaz çelik yıldızlar, önündeki herkese ölümcül bir tehdit oluşturur. Onları bulabildiğin sürece seni kimse durduramaz.$NL;$NL;Shurikenler, zamanla hasar veren ve düşmanların eylemini kesintiye uğratma şansı olan zehirle kaplanmıştır.",
["bm_wpn_prj_hur"] = "Fırlatma Baltası",
["bm_wpn_prj_hur_desc"] = "Keskin bir balta her zaman işe yarar. Bu balta da özellikle fırlatmaya uygun olduğu için motorcular arasında popüler oldu. Motosiklet sürmek bazen tehlikelidir; biraz \"korunmaya\" ihtiyaç duyarsın. Böylece motorcular onu otoyol kavgalarında çok kullanışlı bulunca bu spor baltasının stokları birden tükendi.",
["bm_wpn_prj_jav"] = "Cirit",
["bm_wpn_prj_jav_desc"] = "Kökeni tarih öncesinin karanlığında kaybolan cirit, basit bir silahtır. Sonuçta birine fırlatıp gününü mahvettiğin sivri uçlu bir sopadır. Ama bu basitliğine rağmen kullanmak beceri ve güç ister.",
["bm_wpn_prj_target"] = "Fırlatma Bıçağı",
["bm_wpn_prj_target_desc"] = "İsabetli ve sessiz bir öldürme için sağlam bir yedek plan, güvenilir bir taktik. Fırlatma Bıçağı, insanların nesneleri gelişigüzel bir yöne atmaktan sıkılıp güvenilir bir silah istediği zamanlardan beri savaş tarihinde yer alır.",
