["bm_zeal_mask_desc"] = "O yoktu; resmî olarak yoktu. Çok gizli saldırı birliği ZEAL’e katıldığından beri. Hep son çareydi; aşırı şiddet gerektiğinde gönderilirdi. Kendini hiç tutmadı. Her operasyonda insanlığından bir parça kaybetti. Her operasyonda bir ölüm aracı olarak daha keskinleşti. Artık doğruyla yanlışı ayırmıyordu. Yalnızca yukarıdan gelen emirlere uyuyordu. Gizli süper askerlerin karanlık ordusunda tek bir gölge. Bir gün uyandı; aklında yalnızca başkalarını öldürmek vardı. Sonunda gerçek amacını bulmuştu.",
