["female_1_desc"] = "Uyruk: İrlandalı$NL;Yaş: 27$NL;$NL;Clover, şehrin sert bir mahallesinde, sert bir ailede büyüdü. Ataları her nesilde savaşçıydı; İrlanda mirasına tutkuyla bağlıdır. Yoncaları hem şans için hem de \"İrlandalıyım ve gururluyum\" demenin yolu olarak takar.",
["german_desc"] = "Uyruğu: İsveçli$NL;Yaşı: 34$NL;$NL;Wolf hayatının büyük bölümünde yasalara uyan bir vatandaştı. 2000’lerin sonundaki küresel ekonomik durgunluk sırasında Wolf’un şirketinin bir süre yalnızca tek müşterisi kaldı. O müşteri de çekinip ayrılmak istedi. Şirket iflas etti.$NL;$NL;Artık şirketini yönetirken sahip olduğu kararlılıkla bir suç kariyeri sürdürüyor.",
["heist_contact_jimmy"] = "Jimmy",
