["menu_steam_market_content_smosh_01"] = "Topluluk 2",
["old_hoxton_desc_codex"] = "Hoxton, ilk PAYDAY ekibinin üyelerinden biridir. 2012’ye kadar süren başarılı büyük soygunların ardından Hoxton, FBI tarafından yakalanıp hapse gönderildi. 2014’te Payday Gang kaçmasına yardım etti. Çıktığından beri birinin ona tuzak kurduğundan emin.",
["russian_desc"] = "Uyruk: Amerikalı$NL;Yaş: 44$NL;$NL;Deneyimli, kurnaz, yöntemli. 30 yaşında Chicago’nun iki mafya ailesini birbirine düşürmeye çalıştı. İşler ters gitti; birkaç mafya babası Dallas’ın kellesini istedi ama o bir şekilde yeraltına inip hayatta kaldı. Ortalık yatışınca suç dünyasının basamaklarını yeniden tırmandı.$NL;$NL;Artık herkesin korktuğu yüz o.",
["spanish_desc"] = "Uyruk: Amerikalı$NL;Yaş: 37$NL;$NL;Chains ergenliğinde hep başını belaya sokardı. Koruyucu aileler ve çocuk ıslahevleri arasında geçen yılların ardından kendini orduda buldu. Orada mükemmel bir asker oldu ama kendisine emir verilmesinden hep nefret etti.$NL;$NL;Chains ordudan ayrılıp paralı asker oldu; askerî uzmanlığını en yüksek teklifi verene sundu.",
